	})

	// Cross-app and cross-network replay rejected at Primitives layer.
	rBytes, _ := decodeHex32(group1Root)
	nBytes, _ := decodeHex32("0f0c52b5f0b816e1a40729aee24faac212639a7f8078148652636b40a0e2944f")
