// Render shows the realm's pages on gnoweb:
//
//	""         home: how it works + all tables
//	"table/N"  a table: members, leaderboard, bets
//	"bet/N"    a bet: players, reports, votes, payouts, actions
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	if len(parts) == 2 {
		if _, err := strconv.Atoi(parts[1]); err == nil {
			switch parts[0] {
			case "table":
				if v := tables.Get(parts[1]); v != nil {
					return renderTable(v.(*Table))
				}
				return "# Table not found\n\n[Back home](" + home() + ")"
			case "bet":
				if v := bets.Get(parts[1]); v != nil {
					return renderBet(v.(*Bet))
				}
				return "# Bet not found\n\n[Back home](" + home() + ")"
			case "pool":
				if v := pools.Get(parts[1]); v != nil {
					return renderPool(v.(*Pool))
				}
				return "# Group bet not found\n\n[Back home](" + home() + ")"
			}
		}
	}
	return renderHome()
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# 🍺 Tavern Wagers\n\n")
	sb.WriteString("**Bet on anything with your friends. The money's locked upfront, neutral judges call it, and the winner gets paid automatically. No more \"I'll pay you later.\"**\n\n")
	sb.WriteString("## How it works\n\n")
	sb.WriteString("1. **Open a table** and invite your friends.\n")
	sb.WriteString("2. **Make a bet** against a friend. Both players lock the same stake + a 10% honesty bond.\n")
	sb.WriteString("3. **Play** (chess, FIFA, D&D, anything).\n")
	sb.WriteString("4. **Both players report the result.** If you agree, you're paid instantly and get your bonds back.\n")
	sb.WriteString("5. **Disagree?** Everyone else at the table becomes a judge. They have no money in it, so they have no reason to lie. A strict majority decides.\n")
	sb.WriteString("6. **Lying costs you.** The player who loses the vote forfeits their bond: half to the honest player, half to the judges. Judges also split a 1% fee for showing up.\n")
	sb.WriteString("7. **No majority before the deadline?** Everyone is refunded in full.\n\n")
	sb.WriteString("**Group bets** work the same way for 3 to 20 players (poker night, tournaments), paying out winner-takes-all or split by finishing position. ")
	sb.WriteString("There's no dealer with all the power: non-players judge disputes, and a game needs at least 3 judges unless the players explicitly accept the risk.\n\n")
	sb.WriteString("The realm keeps nothing. Every coin that goes in comes back out to players and judges.\n\n")
	sb.WriteString("[➕ Open a new table](" + call("CreateTable") + ")\n\n")

	sb.WriteString(count(tables.Size(), "table") + " · " + count(bets.Size()+pools.Size(), "bet") + " · " +
		count(totalSettled, "settled bet") + " · **" + gnot(totalLocked, false) + "** locked all time · " +
		count(liarsCaught, "liar") + " caught 🚩 · biggest pot **" + gnot(biggestPot, false) + "**\n\n")

	sb.WriteString("## Tables\n\n")
	if tables.Size() == 0 {
		sb.WriteString("_No tables yet. Be the first._\n")
		return sb.String()
	}
	sb.WriteString("| Table | Members | Bets | Owner |\n|---|---|---|---|\n")
	shown := 0
	tables.ReverseIterate("", "", func(_ string, v any) bool {
		shown++
		if shown > 30 {
			return true // newest 30 only
		}
		t := v.(*Table)
		sb.WriteString("| [" + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ") | " +
			strconv.Itoa(len(t.Members)) + " | " + strconv.Itoa(len(t.BetIDs)+len(t.PoolIDs)) + " | " + who(t, t.Owner) + " |\n")
		return false
	})
	return sb.String()
}

func renderTable(t *Table) string {
	var sb strings.Builder
	id := strconv.Itoa(t.ID)
	sb.WriteString("[← All tables](" + home() + ")\n\n")
	sb.WriteString("# 🍺 " + escape(t.Name) + "\n\n")
	sb.WriteString("Table #" + id + " · owner " + who(t, t.Owner) + " · " + strconv.Itoa(len(t.Members)) + " members\n\n")
	sb.WriteString("[🎲 New 1v1 bet](" + call("CreateBet", "tableID", id) + ") · ")
	sb.WriteString("[🙋 Open challenge](" + call("CreateBet", "tableID", id, "opponentName", "anyone") + ") · ")
	sb.WriteString("[🃏 New group bet](" + call("CreatePool", "tableID", id, "payout", "100", "acceptFewJudges", "false") + ") · ")
	sb.WriteString("[👋 Add member (owner only)](" + call("AddMember", "tableID", id) + ") · ")
	sb.WriteString("[✏️ Change your nickname](" + call("SetNickname", "tableID", id) + ") · ")
	sb.WriteString("[🚪 Leave](" + call("LeaveTable", "tableID", id) + ")\n\n")

	// Leaderboard, sorted by net winnings.
	sb.WriteString("## 🏆 Leaderboard\n\n")
	var rows []row
	for _, m := range t.Members {
		s := &Stats{}
		if v := t.Stats.Get(m.String()); v != nil {
			s = v.(*Stats)
		}
		rows = append(rows, row{m, s})
	}
	for i := 1; i < len(rows); i++ { // insertion sort, highest net first
		for j := i; j > 0 && rows[j].s.Net > rows[j-1].s.Net; j-- {
			rows[j], rows[j-1] = rows[j-1], rows[j]
		}
	}
	sb.WriteString("| # | Member | Net | W | L | D | Disputes lost | Judged | |\n|---|---|---|---|---|---|---|---|---|\n")
	for i, r := range rows {
		liar := strconv.Itoa(r.s.DisputesLost)
		if r.s.DisputesLost > 0 {
			liar = "🚩 " + liar
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + who(t, r.addr) + badges(r.s, i) + " | " + gnot(r.s.Net, true) + " | " +
			strconv.Itoa(r.s.Wins) + " | " + strconv.Itoa(r.s.Losses) + " | " + strconv.Itoa(r.s.Draws) + " | " +
			liar + " | " + strconv.Itoa(r.s.Judged) + " | [🎲 Challenge](" + challenge(t, r.addr) + ") |\n")
	}

	if len(t.Events) > 0 {
		sb.WriteString("\n## 📜 Activity\n\n")
		for i := len(t.Events) - 1; i >= 0 && i >= len(t.Events)-10; i-- {
			e := t.Events[i]
			sb.WriteString("- " + escape(e.Text) + " _(" + e.At.UTC().Format("Jan 2, 15:04") + ")_\n")
		}
	}

	if len(t.PoolIDs) > 0 {
		sb.WriteString("\n## 🃏 Group bets\n\n| Game | Players | Stake | Status |\n|---|---|---|---|\n")
		for i := len(t.PoolIDs) - 1; i >= 0 && i >= len(t.PoolIDs)-30; i-- {
			p := mustPool(t.PoolIDs[i])
			sb.WriteString("| [" + escape(p.Title) + "](" + page("pool/"+strconv.Itoa(p.ID)) + ") | " +
				strconv.Itoa(len(p.Players)) + " | " + gnot(p.Stake, false) + " | " + poolBadge(t, p) + " |\n")
		}
	}

	sb.WriteString("\n## 🎲 Bets\n\n")
	if len(t.BetIDs) == 0 {
		sb.WriteString("_No bets yet._\n")
		return sb.String()
	}
	sb.WriteString("| Bet | Players | Stake | Status |\n|---|---|---|---|\n")
	for i := len(t.BetIDs) - 1; i >= 0 && i >= len(t.BetIDs)-30; i-- { // newest 30
		b := mustBet(t.BetIDs[i])
		sb.WriteString("| [" + escape(b.Title) + "](" + page("bet/"+strconv.Itoa(b.ID)) + ") | " +
			who(t, b.PlayerA) + " vs " + who(t, b.PlayerB) + " | " + gnot(b.Stake, false) + " | " + statusBadge(t, b) + " |\n")
	}
	return sb.String()
}

func renderBet(b *Bet) string {
	var sb strings.Builder
	id := strconv.Itoa(b.ID)
	t := mustTable(b.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🎲 " + escape(b.Title) + "\n\n")
	sb.WriteString("**Status: " + statusBadge(t, b) + "**\n\n")
	if hint := nextStep(t, b); hint != "" {
		sb.WriteString("> 👉 " + hint + "\n\n")
	}

	sb.WriteString("| | Player A | Player B |\n|---|---|---|\n")
	sb.WriteString("| Who | " + who(t, b.PlayerA) + " | " + who(t, b.PlayerB) + " |\n")
	sb.WriteString("| Stake | " + gnot(b.Stake, false) + " | " + gnot(b.Stake, false) + " |\n")
	sb.WriteString("| Honesty bond | " + gnot(b.Bond, false) + " | " + gnot(b.Bond, false) + " |\n")
	sb.WriteString("| Reported | " + result(t, b, b.ReportA) + " | " + result(t, b, b.ReportB) + " |\n\n")
	sb.WriteString("Pot: **" + gnot(2*b.Stake, false) + "**\n\n")
	aw, bw, dr := headToHead(t, b.PlayerA, b.PlayerB)
	if aw+bw+dr > 0 {
		sb.WriteString("Head to head at this table: " + plain(t, b.PlayerA) + " **" + strconv.Itoa(aw) + "** · " +
			plain(t, b.PlayerB) + " **" + strconv.Itoa(bw) + "** · draws **" + strconv.Itoa(dr) + "**\n\n")
	}
	if b.Status == StatusSettled || b.Status == StatusRefunded {
		loser := b.PlayerA
		if b.Final == ResultA {
			loser = b.PlayerB
		}
		other := b.PlayerB
		if loser == b.PlayerB {
			other = b.PlayerA
		}
		sb.WriteString("[🔁 Run it back](" + callSend("CreateBet", strconv.FormatInt(b.Stake+b.Bond, 10)+"ugnot", "tableID", strconv.Itoa(t.ID),
			"title", rematchTitle(b.Title), "opponentName", nameOrAddr(t, other),
			"stake", strconv.FormatInt(b.Stake, 10)) + ") _(for " + plain(t, loser) + ")_\n\n")
	}

	send := strconv.FormatInt(b.Stake+b.Bond, 10) + "ugnot"
	switch b.Status {
	case StatusOpen:
		if b.PlayerB == "" {
			sb.WriteString("**Open challenge:** any member of the table can take this bet. First to accept plays.\n\n")
		}
		sb.WriteString("### Actions\n\n")
		sb.WriteString("- Player B: [✅ Accept and lock " + gnot(b.Stake+b.Bond, false) + "](" +
			callSend("AcceptBet", send, "betID", id) + ")\n")
		if b.PlayerB != "" {
			sb.WriteString("- Player B: [🙅 Decline](" + call("DeclineBet", "betID", id) + ")\n")
		}
		sb.WriteString("- Player A: [❌ Cancel and refund](" + call("CancelBet", "betID", id) + ")\n")
	case StatusLive:
		sb.WriteString("### Report the result\n\n")
		sb.WriteString("[" + plain(t, b.PlayerA) + " won](" + call("Report", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[" + plain(t, b.PlayerB) + " won](" + call("Report", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Draw](" + call("Report", "betID", id, "result", ResultDraw) + ")\n\n")
		if (b.ReportA == "") != (b.ReportB == "") {
			when := b.FirstReportAt.Add(ReportWindow)
			sb.WriteString("_One player has reported. The other has until " + when.UTC().Format(time.RFC822) +
				" to answer, then either player can [⚖️ send it to the judges](" + call("Escalate", "betID", id) + ")._\n")
		}
	case StatusDisputed:
		sb.WriteString("### ⚖️ Judges are voting\n\n")
		sb.WriteString("Players disagree. Judges (table members with no money in this bet) decide. ")
		need := len(b.Judges)/2 + 1
		sb.WriteString("A result needs **" + strconv.Itoa(need) + " of " + strconv.Itoa(len(b.Judges)) + "** votes. ")
		sb.WriteString("Voting closes " + b.Deadline.UTC().Format(time.RFC822) + ".\n\n")
		sb.WriteString("Votes so far: " + plain(t, b.PlayerA) + " won **" + strconv.Itoa(b.countVotes(ResultA)) + "** · " + plain(t, b.PlayerB) + " won **" +
			strconv.Itoa(b.countVotes(ResultB)) + "** · Draw **" + strconv.Itoa(b.countVotes(ResultDraw)) + "**\n\n")
		sb.WriteString("Judges: [Vote " + plain(t, b.PlayerA) + " won](" + call("Vote", "betID", id, "result", ResultA) + ") · ")
		sb.WriteString("[Vote " + plain(t, b.PlayerB) + " won](" + call("Vote", "betID", id, "result", ResultB) + ") · ")
		sb.WriteString("[Vote draw](" + call("Vote", "betID", id, "result", ResultDraw) + ")\n\n")
		sb.WriteString("_No majority by the deadline? Anyone can [refund everyone](" + call("ExpireDispute", "betID", id) + ")._\n")
	}

	if b.Status == StatusOpen {
		preview := t.judgesFor(b.PlayerA, b.PlayerB)
		sb.WriteString("\n### ⚖️ Judges if accepted\n\n")
		if b.PlayerB == "" {
			sb.WriteString("_Everyone below except whoever accepts._\n\n")
		}
		if len(preview) == 0 {
			sb.WriteString("_Nobody else is at this table, so a disagreement would be refunded._\n")
		}
		for _, j := range preview {
			sb.WriteString("- " + who(t, j) + "\n")
		}
	}

	if len(b.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_Fixed when the bet was accepted. Only used if the players disagree._\n\n")
		for _, j := range b.Judges {
			vote := "not voted"
			if v, ok := b.Votes.Get(j.String()).(string); ok {
				vote = result(t, b, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}

	if len(b.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, p := range b.Payouts {
			sb.WriteString("| " + who(t, p.To) + " | " + gnot(p.Amount, false) + " | " + p.Why + " |\n")
		}
	}
	return sb.String()
}

type row struct {
	addr address
	s    *Stats
}

func renderPool(p *Pool) string {
	var sb strings.Builder
	id := strconv.Itoa(p.ID)
	t := mustTable(p.TableID)
	sb.WriteString("[← " + escape(t.Name) + "](" + page("table/"+strconv.Itoa(t.ID)) + ")\n\n")
	sb.WriteString("# 🃏 " + escape(p.Title) + "\n\n")
	sb.WriteString("**Status: " + poolBadge(t, p) + "**\n\n")
	if p.FewJudges {
		sb.WriteString("> ⚠️ This game was started with fewer than 3 judges. If players disagree, very few people decide the result. Play with people you trust.\n\n")
	}
	n := int64(len(p.Players))
	sb.WriteString("Stake **" + gnot(p.Stake, false) + "** each · bond " + gnot(p.Bond, false) + " each · pot **" + gnot(n*p.Stake, false) + "**\n\n")

	sb.WriteString("Payout: ")
	for i, sh := range p.Shares {
		if i > 0 {
			sb.WriteString(" · ")
		}
		sb.WriteString(placeName(i) + " " + strconv.FormatInt(sh, 10) + "%")
	}
	sb.WriteString("\n\n## Players\n\n| Player | Joined | Reported |\n|---|---|---|\n")
	for _, a := range p.Players {
		joined := "⏳"
		if p.Joined.Has(a.String()) {
			joined = "✅"
		}
		rep := "—"
		if v, ok := p.Reports.Get(a.String()).(string); ok {
			rep = rankingText(t, p, v)
		}
		sb.WriteString("| " + who(t, a) + " | " + joined + " | " + rep + " |\n")
	}

	switch p.Status {
	case StatusOpen:
		sb.WriteString("\n[✅ Join and lock " + gnot(p.Stake+p.Bond, false) + "](" +
			callSend("JoinPool", strconv.FormatInt(p.Stake+p.Bond, 10)+"ugnot", "poolID", id) + ") · ")
		sb.WriteString("[❌ Cancel (creator)](" + call("CancelPool", "poolID", id) + ")\n")
	case StatusLive:
		sb.WriteString("\nPlayers: [📝 Report the finishing order](" + call("ReportPool", "poolID", id) + ") ")
		sb.WriteString("_(" + strconv.Itoa(len(p.Shares)) + " name(s), best first, e.g. `" + exampleRanking(t, p) + "`)_\n")
	case StatusDisputed:
		sb.WriteString("\n### ⚖️ Judges are voting\n\nPlayers disagree. Judges: [vote the order](" + call("VotePool", "poolID", id) + ") · ")
		sb.WriteString("voting closes " + p.Deadline.UTC().Format(time.RFC822) + ".\n")
	}

	if p.Status == StatusOpen {
		sb.WriteString("\n### ⚖️ Judges once everyone joins\n\n")
		n := 0
		for _, m := range t.Members {
			if !containsAddr(p.Players, m) {
				sb.WriteString("- " + who(t, m) + "\n")
				n++
			}
		}
		if n == 0 {
			sb.WriteString("_Nobody is left to judge: a disagreement would be refunded._\n")
		}
	}
	if len(p.Judges) > 0 {
		sb.WriteString("\n### ⚖️ Judges\n\n_The table members who didn't play. Only used if players disagree._\n\n")
		for _, j := range p.Judges {
			vote := "not voted"
			if v, ok := p.Votes.Get(j.String()).(string); ok {
				vote = rankingText(t, p, v)
			}
			sb.WriteString("- " + who(t, j) + ": " + vote + "\n")
		}
	}
	if len(p.Payouts) > 0 {
		sb.WriteString("\n### 💸 Payouts\n\n| To | Amount | Why |\n|---|---|---|\n")
		for _, x := range p.Payouts {
			sb.WriteString("| " + who(t, x.To) + " | " + gnot(x.Amount, false) + " | " + x.Why + " |\n")
		}
	}
	return sb.String()
}

func rankingText(t *Table, p *Pool, r string) string {
	var parts []string
	for i, a := range p.rankingAddrs(r) {
		parts = append(parts, placeName(i)+" "+plain(t, a))
	}
	return strings.Join(parts, ", ")
}

func exampleRanking(t *Table, p *Pool) string {
	var names []string
	for i := 0; i < len(p.Shares) && i < len(p.Players); i++ {
		names = append(names, nameOrAddr(t, p.Players[i]))
	}
	return strings.Join(names, ",")
}

func poolBadge(t *Table, p *Pool) string {
	switch p.Status {
	case StatusOpen:
		return "🟡 " + strconv.Itoa(p.Joined.Size()) + "/" + strconv.Itoa(len(p.Players)) + " joined"
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		order := p.rankingAddrs(p.Final)
		if len(order) > 0 {
			return "✅ " + plain(t, order[0]) + " won"
		}
		return "✅ settled"
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return p.Status.String()
}

// badges are small honours on the leaderboard, derived from stats.
func badges(s *Stats, rank int) string {
	out := ""
	if rank == 0 && s.Net > 0 {
		out += " 👑"
	}
	if s.Streak >= 3 {
		out += " 🔥" + strconv.Itoa(s.Streak)
	}
	if s.Judged >= 3 {
		out += " ⚖️"
	}
	return out
}

// nextStep tells visitors what the bet is waiting for.
func nextStep(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "Waiting for " + plain(t, b.PlayerB) + " to accept and lock " + gnot(b.Stake+b.Bond, false) + "."
	case StatusLive:
		switch {
		case b.ReportA == "" && b.ReportB == "":
			return "Game on! After the game, both " + plain(t, b.PlayerA) + " and " + plain(t, b.PlayerB) + " report the result."
		case b.ReportA == "":
			return "Waiting for " + plain(t, b.PlayerA) + " to report."
		default:
			return "Waiting for " + plain(t, b.PlayerB) + " to report."
		}
	case StatusDisputed:
		return "The players disagree. Judges, it's your call."
	}
	return ""
}

// headToHead counts settled results between two players at a table,
// from a's point of view: a's wins, b's wins, draws.
func headToHead(t *Table, a, b address) (int, int, int) {
	aw, bw, dr := 0, 0, 0
	for _, id := range t.BetIDs {
		x := mustBet(id)
		if x.Status != StatusSettled {
			continue
		}
		var winner address
		switch x.Final {
		case ResultA:
			winner = x.PlayerA
		case ResultB:
			winner = x.PlayerB
		}
		pair := (x.PlayerA == a && x.PlayerB == b) || (x.PlayerA == b && x.PlayerB == a)
		if !pair {
			continue
		}
		switch winner {
		case a:
			aw++
		case b:
			bw++
		default:
			dr++
		}
	}
	return aw, bw, dr
}

func rematchTitle(title string) string {
	if !strings.HasPrefix(title, "Rematch: ") {
		title = "Rematch: " + title
	}
	if len(title) > 140 {
		title = title[:140]
	}
	return title
}

func nameOrAddr(t *Table, a address) string {
	if n := t.Nick(a); n != "" {
		return n
	}
	return a.String()
}

func count(n int, word string) string {
	if n == 1 {
		return "**1** " + word
	}
	return "**" + strconv.Itoa(n) + "** " + word + "s"
}

// challenge links to CreateBet with the table and opponent filled in.
func challenge(t *Table, a address) string {
	return call("CreateBet", "tableID", strconv.Itoa(t.ID), "opponentName", nameOrAddr(t, a))
}

// ---------------------------------------------------------------------------
// Formatting helpers

func statusBadge(t *Table, b *Bet) string {
	switch b.Status {
	case StatusOpen:
		return "🟡 waiting for " + plain(t, b.PlayerB)
	case StatusLive:
		return "🟢 live"
	case StatusDisputed:
		return "⚖️ disputed"
	case StatusSettled:
		return "✅ settled: " + result(t, b, b.Final)
	case StatusCancelled:
		return "❌ cancelled"
	case StatusRefunded:
		return "↩️ refunded"
	}
	return b.Status.String()
}

// result describes a reported/voted result using the players' nicknames.
func result(t *Table, b *Bet, r string) string {
	switch r {
	case ResultA:
		return plain(t, b.PlayerA) + " won"
	case ResultB:
		return plain(t, b.PlayerB) + " won"
	}
	return showReport(r)
}

// plain is a nickname (or short address) without markdown, for link text.
func plain(t *Table, a address) string {
	if a == "" {
		return "anyone"
	}
	if n := t.Nick(a); n != "" {
		return escape(n)
	}
	s := a.String()
	return s[:7] + "…" + s[len(s)-4:]
}

func showReport(r string) string {
	switch r {
	case ResultA:
		return "A won"
	case ResultB:
		return "B won"
	case ResultDraw:
		return "draw"
	}
	return "—"
}

// gnot formats ugnot as GNOT with up to 6 decimals.
func gnot(u int64, signed bool) string {
	sign := ""
	if u < 0 {
		sign = "-"
		u = -u
	} else if signed && u > 0 {
		sign = "+"
	}
	whole := u / 1_000_000
	frac := u % 1_000_000
	s := strconv.FormatInt(whole, 10)
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		s += "." + strings.TrimRight(f, "0")
	}
	return sign + s + " GNOT"
}

// who shows a member's nickname at a table, falling back to a short address.
func who(t *Table, a address) string {
	if a == "" {
		return "_anyone_"
	}
	if n := t.Nick(a); n != "" {
		return "**" + escape(n) + "**"
	}
	return short(a)
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:7] + "…" + s[len(s)-4:] + "`"
}

func escape(s string) string {
	r := strings.NewReplacer("|", "\\|", "[", "\\[", "]", "\\]", "<", "&lt;", ">", "&gt;", "\n", " ")
	return r.Replace(s)
}

func prefix() string {
	return strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), runtime.ChainDomain())
}

func home() string           { return prefix() }
func page(sub string) string { return prefix() + ":" + sub }

// call builds a gnoweb transaction link: /r/...$help&func=Fn&k=v
func call(fn string, kv ...string) string {
	return callSend(fn, "", kv...)
}

func callSend(fn, send string, kv ...string) string {
	q := url.Values{}
	for i := 0; i+1 < len(kv); i += 2 {
		q.Add(kv[i], kv[i+1])
	}
	if send != "" {
		q.Add(".send", send)
	}
	link := prefix() + "$help&func=" + fn
	if enc := q.Encode(); enc != "" {
		link += "&" + enc
	}
	return link
}

// Package tavernwagers lets friend groups ("tables") bet on anything with each other.
//
// How it works:
//   - A table is an invite-only group of friends.
//   - Two players lock the same stake into the realm before the game,
//     plus a 10% honesty bond.
//   - After the game, both players report the result. If they agree, the
//     realm pays out instantly and both bonds come back.
//   - If they disagree, every other table member becomes a judge. Judges
//     have no money in the bet, so they have no reason to lie. As soon as
//     a strict majority of judges agree, the bet settles.
//   - A player whose report loses the vote forfeits their bond. Half goes
//     to the honest player, half to the judges who voted with the majority.
//     Majority judges also split a 1% fee from the pot for showing up.
//   - If the judges can't reach a majority before the deadline, everyone
//     is refunded in full.
//
// The realm takes no cut: every coin that goes in comes back out to the
// players and judges.
package tavernwagers

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
)

const (
	ResultA    = "a"    // player A won
	ResultB    = "b"    // player B won
	ResultDraw = "draw" // draw, stakes go back

	MinStake int64 = 10_000                // 0.01 GNOT
	MaxStake int64 = 1_000_000_000_000_000 // 1 billion GNOT: keeps every pot far from int64 overflow

	ReportWindow = 24 * time.Hour // how long a player has to answer the other's report
	VoteWindow   = 48 * time.Hour // how long judges have to vote
)

type BetStatus int

const (
	StatusOpen      BetStatus = iota // waiting for player B to accept
	StatusLive                       // both staked, waiting for reports
	StatusDisputed                   // players disagree, judges voting
	StatusSettled                    // paid out
	StatusCancelled                  // cancelled before B accepted
	StatusRefunded                   // judges could not decide, everyone refunded
)

func (s BetStatus) String() string {
	switch s {
	case StatusOpen:
		return "open"
	case StatusLive:
		return "live"
	case StatusDisputed:
		return "disputed"
	case StatusSettled:
		return "settled"
	case StatusCancelled:
		return "cancelled"
	case StatusRefunded:
		return "refunded"
	}
	return "unknown"
}

// Stats is one member's record at a table.
type Stats struct {
	Net          int64 // ugnot won minus ugnot lost
	Wins         int
	Losses       int
	Draws        int
	DisputesLost int // times this player's report lost a judges' vote
	Judged       int // times this member voted with the majority as a judge
	Streak       int // current win streak
	BestStreak   int
}

func (s *Stats) win() {
	s.Wins++
	s.Streak++
	if s.Streak > s.BestStreak {
		s.BestStreak = s.Streak
	}
}

func (s *Stats) lose() {
	s.Losses++
	s.Streak = 0
}

type Table struct {
	ID      int
	Name    string
	Owner   address
	Members []address
	Stats   *avl.Tree // address -> *Stats
	Names   *avl.Tree // address -> nickname
	BetIDs  []int
	PoolIDs []int
	Events  []Event // newest last, capped at MaxEvents
	Created time.Time
}

// Event is a line in a table's activity feed.
type Event struct {
	At   time.Time
	Text string
}

const MaxEvents = 25

func (t *Table) log(text string) {
	t.Events = append(t.Events, Event{time.Now(), text})
	if len(t.Events) > MaxEvents {
		t.Events = t.Events[len(t.Events)-MaxEvents:]
	}
}

// label is a member's nickname, or a short address, for activity text.
func (t *Table) label(a address) string {
	if a == "" {
		return "anyone"
	}
	if n := t.Nick(a); n != "" {
		return n
	}
	s := a.String()
	return s[:7] + "…" + s[len(s)-4:]
}

type Payout struct {
	To     address
	Amount int64
	Why    string
}

type Bet struct {
	ID      int
	TableID int
	Title   string
	PlayerA address
	PlayerB address
	Stake   int64 // per player
	Bond    int64 // per player
	Status  BetStatus

	ReportA       string
	ReportB       string
	FirstReportAt time.Time

	Judges   []address
	Votes    *avl.Tree // address -> result string
	Deadline time.Time // voting deadline when disputed

	Final   string
	Payouts []Payout
	Created time.Time
}

var (
	tables   avl.Tree // id -> *Table
	bets     avl.Tree // id -> *Bet
	tableSeq int
	betSeq   int

	totalLocked  int64 // ugnot locked in accepted bets, all time
	totalSettled int   // bets settled (paid out to a winner or draw)
	liarsCaught  int   // reports that lost a judges' vote
	biggestPot   int64 // largest pot ever settled, ugnot
	judgesPaid   int64 // ugnot paid to judges, all time
)

// ---------------------------------------------------------------------------
// Tables

// CreateTable opens a new table. The caller becomes its owner and first
// member, shown under the given nickname.
func CreateTable(cur realm, name string, nickname string) int {
	caller := cur.Previous().Address()
	name = strings.TrimSpace(name)
	require(name != "", "table name required")
	require(len(name) <= 64, "table name too long (max 64)")
	require(printable(name), "table name has invalid characters")

	tableSeq++
	t := &Table{
		ID:      tableSeq,
		Name:    name,
		Owner:   caller,
		Members: []address{caller},
		Stats:   avl.NewTree(),
		Names:   avl.NewTree(),
		Created: time.Now(),
	}
	t.setName(caller, nickname)
	t.log("🍺 " + t.label(caller) + " opened the table")
	tables.Set(strconv.Itoa(t.ID), t)
	return t.ID
}

// AddMember invites a friend to a table under a nickname. Only the table
// owner can do this. Members can change their own nickname later.
func AddMember(cur realm, tableID int, member address, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can add members")
	require(member.IsValid(), "invalid address")
	require(!t.isMember(member), "already a member")
	require(len(t.Members) < 50, "table is full (max 50)")
	t.setName(member, nickname) // validate the nickname before changing anything
	t.Members = append(t.Members, member)
	t.log("👋 " + t.label(member) + " joined the table")
}

// LeaveTable removes you from a table. You can't leave while you're
// playing or judging an unfinished bet, and the owner can't leave.
func LeaveTable(cur realm, tableID int) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(t.isMember(caller), "you are not a member of this table")
	require(caller != t.Owner, "the owner can't leave the table")
	label := t.label(caller)
	t.removeMember(caller)
	t.log("🚪 " + label + " left the table")
}

// RemoveMember lets the owner remove someone who has no unfinished bets.
func RemoveMember(cur realm, tableID int, member address) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(caller == t.Owner, "only the table owner can remove members")
	require(member != t.Owner, "the owner can't be removed")
	require(t.isMember(member), "not a member of this table")
	label := t.label(member)
	t.removeMember(member)
	t.log("🚪 " + label + " was removed from the table")
}

func (t *Table) removeMember(a address) {
	require(!t.busy(a), "they still have an unfinished bet at this table (as a player or judge)")
	var kept []address
	for _, m := range t.Members {
		if m != a {
			kept = append(kept, m)
		}
	}
	t.Members = kept
	t.Names.Remove(a.String())
}

// busy reports whether a member is a player or judge in an unfinished bet.
func (t *Table) busy(a address) bool {
	for _, id := range t.BetIDs {
		b := mustBet(id)
		switch b.Status {
		case StatusOpen, StatusLive, StatusDisputed:
			if b.PlayerA == a || b.PlayerB == a || b.isJudge(a) {
				return true
			}
		}
	}
	for _, id := range t.PoolIDs {
		p := mustPool(id)
		switch p.Status {
		case StatusOpen, StatusLive, StatusDisputed:
			if containsAddr(p.Players, a) || containsAddr(p.Judges, a) {
				return true
			}
		}
	}
	return false
}

// SetNickname changes how you appear at a table.
func SetNickname(cur realm, tableID int, nickname string) {
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	require(t.isMember(caller), "you are not a member of this table")
	t.setName(caller, nickname)
}

// ---------------------------------------------------------------------------
// Bets

// CreateBet proposes a bet against another table member and locks your stake.
// opponent is their nickname at the table (or their g1... address).
// Send exactly stake + 10% bond, e.g. stake 1000000 -> send 1100000ugnot.
// You are player A, the opponent is player B. The judges are fixed when
// the bet is accepted: every other member of the table at that moment.
func CreateBet(cur realm, tableID int, title string, opponentName string, stake int64) int {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	t := mustTable(tableID)
	title = strings.TrimSpace(title)
	require(title != "", "bet title required")
	require(len(title) <= 140, "bet title too long (max 140)")
	require(printable(title), "bet title has invalid characters")
	require(t.isMember(caller), "you are not a member of this table")
	// "anyone" makes an open challenge: the first member to accept plays.
	var opponent address
	if strings.ToLower(strings.TrimSpace(opponentName)) == "anyone" {
		require(len(t.Members) >= 2, "nobody else is at this table yet")
	} else {
		opponent = t.resolve(opponentName)
		require(opponent != caller, "you can't bet against yourself")
	}
	require(stake >= MinStake, "stake too small (min "+strconv.FormatInt(MinStake, 10)+"ugnot)")
	require(stake <= MaxStake, "stake too large")

	bond := stake / 10
	requireSent(stake + bond)

	betSeq++
	b := &Bet{
		ID:      betSeq,
		TableID: tableID,
		Title:   title,
		PlayerA: caller,
		PlayerB: opponent,
		Stake:   stake,
		Bond:    bond,
		Status:  StatusOpen,
		Votes:   avl.NewTree(),
		Created: time.Now(),
	}
	bets.Set(strconv.Itoa(b.ID), b)
	t.BetIDs = append(t.BetIDs, b.ID)
	t.log("🎲 " + t.label(caller) + " challenged " + t.label(opponent) + ": " + title + " (" + gnot(stake, false) + ")")
	return b.ID
}

// AcceptBet is called by player B to match the stake and bond.
func AcceptBet(cur realm, betID int) {
	require(cur.Previous().IsUserCall(), "only direct user calls accepted")
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	if b.PlayerB == "" {
		require(mustTable(b.TableID).isMember(caller), "you are not a member of this table")
		require(caller != b.PlayerA, "you can't accept your own challenge")
		b.PlayerB = caller
	}
	require(caller == b.PlayerB, "only the challenged player can accept")
	requireSent(b.Stake + b.Bond)
	b.Status = StatusLive
	mustTable(b.TableID).log("🤝 " + mustTable(b.TableID).label(b.PlayerB) + " accepted " + mustTable(b.TableID).label(b.PlayerA) + "'s bet: " + b.Title)
	b.Judges = mustTable(b.TableID).judgesFor(b.PlayerA, b.PlayerB)
	totalLocked += 2 * (b.Stake + b.Bond)
}

// CancelBet lets player A take the bet back before B accepts it.
func CancelBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "only open bets can be cancelled")
	require(caller == b.PlayerA, "only the player who created the bet can cancel it")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "cancelled, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// DeclineBet lets player B turn a challenge down. Player A is refunded.
func DeclineBet(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusOpen, "bet is not open")
	require(caller == b.PlayerB, "only the challenged player can decline")
	b.Status = StatusCancelled
	b.Payouts = []Payout{{b.PlayerA, b.Stake + b.Bond, "declined, refund"}}
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// Report is how each player says who won: "a", "b" or "draw".
// If both players report the same result, the bet pays out right away.
// If they disagree, it goes to the judges.
func Report(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	result = normalizeResult(result)

	switch caller {
	case b.PlayerA:
		require(b.ReportA == "", "you already reported")
		b.ReportA = result
	case b.PlayerB:
		require(b.ReportB == "", "you already reported")
		b.ReportB = result
	default:
		panic("only the two players can report")
	}

	if b.ReportA == "" || b.ReportB == "" {
		b.FirstReportAt = time.Now()
		return
	}

	if b.ReportA == b.ReportB {
		b.settle(b.ReportA, nil)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
		return
	}

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Escalate sends a bet to the judges when one player reported and the
// other went quiet for longer than the report window.
func Escalate(cur realm, betID int) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusLive, "bet is not waiting for reports")
	require(caller == b.PlayerA || caller == b.PlayerB, "only the players can escalate")
	require((b.ReportA == "") != (b.ReportB == ""), "escalate needs exactly one report")
	require(time.Now().After(b.FirstReportAt.Add(ReportWindow)), "the other player still has time to report")

	if !b.openDispute() {
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// Vote is for judges of a disputed bet: "a", "b" or "draw".
// The bet settles the moment one result has a strict majority of judges.
func Vote(cur realm, betID int, result string) {
	caller := cur.Previous().Address()
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(b.isJudge(caller), "you are not a judge on this bet")
	require(!b.Votes.Has(caller.String()), "you already voted")
	require(time.Now().Before(b.Deadline), "voting is closed")
	result = normalizeResult(result)

	b.Votes.Set(caller.String(), result)

	if b.countVotes(result)*2 > len(b.Judges) {
		var majority []address
		for _, j := range b.Judges {
			if v, ok := b.Votes.Get(j.String()).(string); ok && v == result {
				majority = append(majority, j)
			}
		}
		b.settle(result, majority)
		pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
	}
}

// ExpireDispute refunds everyone if the judges failed to reach a majority
// before the deadline. Anyone can call it.
func ExpireDispute(cur realm, betID int) {
	b := mustBet(betID)
	require(b.Status == StatusDisputed, "bet is not in dispute")
	require(time.Now().After(b.Deadline), "voting is still open")
	b.refundAll("no judge majority")
	pay(banker.NewBanker(banker.BankerTypeRealmSend, cur), cur.Address(), b.Payouts)
}

// ---------------------------------------------------------------------------
// Settlement logic (pure bookkeeping, no coins move here)

// openDispute snapshots the judges. It returns false if the bet had to be
// refunded instead (a table with no possible judges).
func (b *Bet) openDispute() bool {
	if len(b.Judges) == 0 {
		b.refundAll("no judges at this table")
		return false
	}
	mustTable(b.TableID).log("⚖️ Dispute! The judges will decide \"" + b.Title + "\"")
	b.Status = StatusDisputed
	b.Deadline = time.Now().Add(VoteWindow)
	return true
}

func (b *Bet) refundAll(why string) {
	b.Status = StatusRefunded
	each := b.Stake + b.Bond
	b.Payouts = []Payout{
		{b.PlayerA, each, why + ", refund"},
		{b.PlayerB, each, why + ", refund"},
	}
}

// settle fills in b.Payouts for a final result and updates the leaderboard.
// majority is nil when the players agreed (no judges involved).
func (b *Bet) settle(final string, majority []address) {
	b.Status = StatusSettled
	totalSettled++
	b.Final = final
	pot := 2 * b.Stake

	disputed := majority != nil
	fee := int64(0)
	if disputed {
		fee = 2 * (b.Stake / 100) // 1% of the pot, always even
	}

	var payouts []Payout
	add := func(to address, amt int64, why string) {
		if amt > 0 {
			payouts = append(payouts, Payout{to, amt, why})
		}
	}

	// 1. The pot, minus the judges' fee.
	switch final {
	case ResultA:
		add(b.PlayerA, pot-fee, "won the pot")
	case ResultB:
		add(b.PlayerB, pot-fee, "won the pot")
	case ResultDraw:
		add(b.PlayerA, b.Stake-fee/2, "draw, stake back")
		add(b.PlayerB, b.Stake-fee/2, "draw, stake back")
	}

	// 2. Honesty bonds.
	forfeited := int64(0)
	var honest []address
	t := mustTable(b.TableID)
	players := []address{b.PlayerA, b.PlayerB}
	reports := []string{b.ReportA, b.ReportB}
	for i := range players {
		if !disputed || reports[i] == final {
			add(players[i], b.Bond, "bond back")
			if disputed {
				honest = append(honest, players[i])
			}
		} else {
			forfeited += b.Bond
			t.stats(players[i]).DisputesLost++
			liarsCaught++
			t.log("🚩 The judges ruled against " + t.label(players[i]) + " on \"" + b.Title + "\". Bond forfeited.")
		}
	}

	// 3. Forfeited bonds: half to the honest player(s), half to judges.
	judgePool := fee
	if forfeited > 0 {
		if len(honest) > 0 {
			toHonest := forfeited / 2
			judgePool += forfeited - toHonest
			split(honest, toHonest, "liar's bond", add)
		} else {
			judgePool += forfeited
		}
	}

	// 4. Judges who voted with the majority split their pool.
	if disputed {
		split(majority, judgePool, "judge reward", add)
		for _, j := range majority {
			t.stats(j).Judged++
		}
	}

	b.Payouts = payouts
	if pot > biggestPot {
		biggestPot = pot
	}
	for _, j := range majority {
		judgesPaid += received(payouts, j)
	}

	// Leaderboard: net result per person, relative to what they put in.
	deposit := b.Stake + b.Bond
	t.stats(b.PlayerA).Net += received(payouts, b.PlayerA) - deposit
	t.stats(b.PlayerB).Net += received(payouts, b.PlayerB) - deposit
	for _, j := range majority {
		t.stats(j).Net += received(payouts, j)
	}
	switch final {
	case ResultA:
		t.stats(b.PlayerA).win()
		t.stats(b.PlayerB).lose()
		t.log("🏆 " + t.label(b.PlayerA) + " beat " + t.label(b.PlayerB) + ": " + b.Title + " (+" + gnot(b.Stake, false) + ")")
	case ResultB:
		t.stats(b.PlayerB).win()
		t.stats(b.PlayerA).lose()
		t.log("🏆 " + t.label(b.PlayerB) + " beat " + t.label(b.PlayerA) + ": " + b.Title + " (+" + gnot(b.Stake, false) + ")")
	case ResultDraw:
		t.stats(b.PlayerA).Draws++
		t.stats(b.PlayerB).Draws++
		t.log("🤝 " + t.label(b.PlayerA) + " and " + t.label(b.PlayerB) + " drew: " + b.Title)
	}
}

// split divides amount evenly; the remainder goes to the first recipient so
// no dust is ever stuck in the realm.
func split(to []address, amount int64, why string, add func(address, int64, string)) {
	if len(to) == 0 || amount <= 0 {
		return
	}
	n := int64(len(to))
	each := amount / n
	rest := amount - each*n
	for i, a := range to {
		amt := each
		if i == 0 {
			amt += rest
		}
		add(a, amt, why)
	}
}

func received(payouts []Payout, who address) int64 {
	total := int64(0)
	for _, p := range payouts {
		if p.To == who {
			total += p.Amount
		}
	}
	return total
}

// pay moves the coins. The banker is always created inside the exported
// crossing function, from its own cur.
func pay(bk banker.Banker, from address, payouts []Payout) {
	for _, p := range payouts {
		bk.SendCoins(from, p.To, chain.Coins{{"ugnot", p.Amount}})
	}
}

// ---------------------------------------------------------------------------
// Read-only getters

func GetTableName(tableID int) string { return mustTable(tableID).Name }
func GetBetStatus(betID int) string   { return mustBet(betID).Status.String() }
func GetBetResult(betID int) string   { return mustBet(betID).Final }

func GetNet(tableID int, who address) int64 {
	t := mustTable(tableID)
	if v := t.Stats.Get(who.String()); v != nil {
		return v.(*Stats).Net
	}
	return 0
}

// ---------------------------------------------------------------------------
// Helpers

func (t *Table) isMember(a address) bool {
	for _, m := range t.Members {
		if m == a {
			return true
		}
	}
	return false
}

// setName validates and stores a nickname (unique per table). An empty
// nickname clears it, and the address is shown instead.
func (t *Table) setName(a address, nickname string) {
	nickname = strings.TrimSpace(nickname)
	if nickname == "" {
		t.Names.Remove(a.String())
		return
	}
	require(len(nickname) <= 24, "nickname too long (max 24)")
	for _, r := range nickname {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			r == ' ' || r == '-' || r == '_' || r == '.'
		require(ok, "nickname can only use letters, numbers, spaces, - _ .")
	}
	lower := strings.ToLower(nickname)
	t.Names.Iterate("", "", func(k string, v any) bool {
		require(k == a.String() || strings.ToLower(v.(string)) != lower, "nickname already taken at this table")
		return false
	})
	t.Names.Set(a.String(), nickname)
}

// Nick returns a member's nickname, or "" if they have none.
func (t *Table) Nick(a address) string {
	if v := t.Names.Get(a.String()); v != nil {
		return v.(string)
	}
	return ""
}

// judgesFor lists every member except the two players.
func (t *Table) judgesFor(a, b address) []address {
	var judges []address
	for _, m := range t.Members {
		if m != a && m != b {
			judges = append(judges, m)
		}
	}
	return judges
}

// resolve finds a member by nickname (case-insensitive) or g1 address.
func (t *Table) resolve(who string) address {
	who = strings.TrimSpace(who)
	if strings.HasPrefix(who, "g1") {
		if a := address(who); a.IsValid() {
			require(t.isMember(a), "opponent is not a member of this table")
			return a
		}
	}
	lower := strings.ToLower(who)
	var found address
	t.Names.Iterate("", "", func(k string, v any) bool {
		if strings.ToLower(v.(string)) == lower {
			found = address(k)
			return true
		}
		return false
	})
	require(found != "" && t.isMember(found), "opponent is not a member of this table")
	return found
}

func (t *Table) stats(a address) *Stats {
	if v := t.Stats.Get(a.String()); v != nil {
		return v.(*Stats)
	}
	s := &Stats{}
	t.Stats.Set(a.String(), s)
	return s
}

func (b *Bet) isJudge(a address) bool {
	for _, j := range b.Judges {
		if j == a {
			return true
		}
	}
	return false
}

func (b *Bet) countVotes(result string) int {
	n := 0
	b.Votes.Iterate("", "", func(_ string, v any) bool {
		if v.(string) == result {
			n++
		}
		return false
	})
	return n
}

// printable rejects control characters (newlines, tabs, etc.).
func printable(s string) bool {
	for _, r := range s {
		if r < 32 || r == 127 {
			return false
		}
	}
	return true
}

func normalizeResult(r string) string {
	r = strings.ToLower(strings.TrimSpace(r))
	require(r == ResultA || r == ResultB || r == ResultDraw, `result must be "a", "b" or "draw"`)
	return r
}

func requireSent(want int64) {
	sent := unsafe.OriginSend()
	require(len(sent) == 1 && sent[0].Denom == "ugnot",
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
	require(sent[0].Amount == want,
		"send exactly "+strconv.FormatInt(want, 10)+"ugnot (stake + 10% bond)")
}

func mustTable(id int) *Table {
	v := tables.Get(strconv.Itoa(id))
	if v == nil {
		panic("table not found")
	}
	return v.(*Table)
}

func mustBet(id int) *Bet {
	v := bets.Get(strconv.Itoa(id))
	if v == nil {
		panic("bet not found")
	}
	return v.(*Bet)
}

func require(ok bool, msg string) {
	if !ok {
		panic(msg)
	}
}

package rooms

import "chain"

// The admin can pause new activity, set the fee for rooms opened later (at
// most MaxFeeBps), move the treasury, and verify assets, each verification
// counting only VerifyDelay later. A pause stops Open, Join, deposits, Lock,
// Offer and Fill; it never stops Withdraw, Unlock or Cancel, so deposits
// can always leave. The admin has no way to move anyone's assets.

var (
	admin        address // set to the deployer in init
	pendingAdmin address
	paused       bool
)

// SetPaused stops or resumes new activity.
func SetPaused(cur realm, value bool) {
	assertAdmin(cur)
	paused = value
	state := "resumed"
	if value {
		state = "paused"
	}
	chain.Emit("Paused", "state", state)
}

// ProposeAdmin names the next admin; the change happens when that address
// calls AcceptAdmin. Pass "" to withdraw a proposal.
func ProposeAdmin(cur realm, next string) {
	assertAdmin(cur)
	if next == "" {
		pendingAdmin = ""
		return
	}
	addr := address(next)
	if !addr.IsValid() {
		panic("next admin is not a valid address")
	}
	pendingAdmin = addr
	chain.Emit("AdminProposed", "next", addr.String())
}

// AcceptAdmin completes a handover started with ProposeAdmin.
func AcceptAdmin(cur realm) {
	who := callerOf(cur)
	if pendingAdmin == "" || who != pendingAdmin {
		panic("you are not the proposed admin")
	}
	admin = who
	pendingAdmin = ""
	chain.Emit("AdminChanged", "admin", who.String())
}

// IsPaused reports whether new activity is stopped.
func IsPaused() bool {
	return paused
}

// Admin returns the current admin address, or "" when there is none.
func Admin() string {
	return admin.String()
}

func assertAdmin(cur realm) {
	who := callerOf(cur)
	refuseCoins(cur)
	if admin == "" || who != admin {
		panic("admin only")
	}
}

func assertNotPaused() {
	if paused {
		panic("trade rooms are paused: you can still withdraw, unlock and cancel")
	}
}

package rooms

import (
	"chain"
	"math"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// The service fee. When a room settles, the realm keeps FeeBps basis points
// of every coin and token that crosses, from each side, and sends it to the
// treasury; the rest goes to the other party. NFTs cross whole and pay
// nothing. Withdrawing, cancelling and expiring cost nothing.
//
// A room keeps the rate it was opened with, so the admin can never raise
// the fee on a trade already under way, and no rate can exceed MaxFeeBps.

const (
	// DefaultFeeBps is 0.5%.
	DefaultFeeBps = 50
	// MaxFeeBps caps the fee at 1%, whatever the admin sets.
	MaxFeeBps = 100
)

var (
	feeBps   uint64  = DefaultFeeBps
	treasury address // set to the deployer in init; fees are off while it is empty

	fees avl.Tree // kind + ":" + denom -> int64 fees collected
)

// SetFee sets the rate for rooms opened from now on, in basis points
// (50 is 0.5%), at most MaxFeeBps. Rooms already open keep their rate.
func SetFee(cur realm, bps uint64) {
	assertAdmin(cur)
	if bps > MaxFeeBps {
		panic("the fee can be at most " + strconv.Itoa(MaxFeeBps) + " basis points")
	}
	feeBps = bps
	chain.Emit("FeeChanged", "bps", strconv.FormatUint(bps, 10))
}

// SetTreasury names the account that receives fees from now on.
func SetTreasury(cur realm, to string) {
	assertAdmin(cur)
	addr := address(to)
	if !addr.IsValid() {
		panic("treasury is not a valid address")
	}
	treasury = addr
	chain.Emit("TreasuryChanged", "treasury", addr.String())
}

// FeeBps returns the rate a room opened now would get.
func FeeBps() uint64 {
	return openingFee()
}

// Treasury returns the account that receives fees, or "" when fees are off.
func Treasury() string {
	return treasury.String()
}

// openingFee is the rate a new room keeps for its whole life.
func openingFee() uint64 {
	if treasury == "" {
		return 0
	}
	return feeBps
}

// feeOf is the fee on amount at bps basis points, rounded down. It never
// overflows: bps is at most MaxFeeBps.
func feeOf(amount int64, bps uint64) int64 {
	if bps == 0 || amount <= 0 {
		return 0
	}
	b := int64(bps)
	return amount/10000*b + amount%10000*b/10000
}

// pay sends one asset of a settling room to the party receiving it, less
// the room's fee on coins and tokens.
func (r *room) pay(cur realm, to address, a asset) {
	fee := int64(0)
	if a.kind != KindNFT {
		fee = feeOf(a.amount, r.feeBps)
	}
	if fee > 0 {
		send(cur, treasury, asset{kind: a.kind, denom: a.denom, amount: fee})
		addFee(a.kind, a.denom, fee)
	}
	send(cur, to, asset{kind: a.kind, denom: a.denom, amount: a.amount - fee})
}

func addFee(kind, denom string, amount int64) {
	key := kind + ":" + denom
	total := int64(0)
	if v := fees.Get(key); v != nil {
		total = v.(int64)
	}
	if amount > math.MaxInt64-total {
		total = math.MaxInt64
	} else {
		total += amount
	}
	fees.Set(key, total)
}

package rooms

import (
	"strconv"
	"strings"
)

// jsonString quotes s as a JSON string. Everything outside printable ASCII
// is written as a \u escape, so the output is plain ASCII.
func jsonString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r >= 0x20 && r < 0x7f:
			b.WriteRune(r)
		case r > 0xffff:
			r -= 0x10000
			writeU16(&b, 0xd800+(r>>10))
			writeU16(&b, 0xdc00+(r&0x3ff))
		default:
			writeU16(&b, r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func writeU16(b *strings.Builder, r rune) {
	const hex = "0123456789abcdef"
	b.WriteString(`\u`)
	b.WriteByte(hex[(r>>12)&0xf])
	b.WriteByte(hex[(r>>8)&0xf])
	b.WriteByte(hex[(r>>4)&0xf])
	b.WriteByte(hex[r&0xf])
}

func jsonUint(v uint64) string {
	return strconv.FormatUint(v, 10)
}

func jsonInt(v int64) string {
	return strconv.FormatInt(v, 10)
}

func jsonBool(v bool) string {
	if v {
		return "true"
	}
	return "false"
}

// jsonObject joins already-encoded key/value pairs.
func jsonObject(pairs ...string) string {
	if len(pairs)%2 != 0 {
		panic("jsonObject needs key/value pairs")
	}
	var b strings.Builder
	b.WriteByte('{')
	for i := 0; i < len(pairs); i += 2 {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonString(pairs[i]))
		b.WriteByte(':')
		b.WriteString(pairs[i+1])
	}
	b.WriteByte('}')
	return b.String()
}

func jsonArray(items []string) string {
	return "[" + strings.Join(items, ",") + "]"
}

package rooms

import (
	"chain"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc721/enumerable/v0"
	"gno.land/p/nt/grc721/v0"
)

// NFTs: one GRC721 token is one asset on a side, held whole. gno.land has no
// GRC721 registry yet, so rooms keeps its own, on the trust model of
// gno.land/r/nt/grc20reg/v0: a collection registers itself, from its own
// realm, under the key "<realm path>.<symbol>". An NFT asset's denom is that
// key, "#" and the token id; a key never holds "#".

// MaxTokenIDLen bounds what a room stores per NFT.
const MaxTokenIDLen = 64

type collection struct {
	token *grc721.Token
	// list is the collection's enumerable view, when it has one: it lets
	// OwnedJSON show a wallet's NFTs of this collection.
	list *enumerable.Enumerable
}

var collections avl.Tree // "<realm path>.<symbol>" -> *collection

// RegisterCollection makes a GRC721 collection tradable in rooms and returns
// its key. Only the collection's own realm can register it, once; list is
// its enumerable view, or nil. A collection's realm also lets owners
// approve this realm (see Address) for one token id, as its own Approve
// does; DepositNFT spends that approval.
//
//	key := rooms.RegisterCollection(cross(cur), Token, List)
func RegisterCollection(cur realm, token *grc721.Token, list *enumerable.Enumerable) string {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	refuseCoins(cur)
	if token == nil {
		panic("collection is nil")
	}
	path := cur.Previous().PkgPath()
	if !strings.HasPrefix(path, "gno.land/r/") || strings.Contains(path, "#") {
		panic("register a collection from its own realm")
	}
	key := path + "." + token.GetSymbol()
	// Token.ID() is "<creating realm path>.<symbol>.<id>" and cannot be
	// forged: the token was created by the realm that registers it.
	if !strings.HasPrefix(token.ID(), key+".") {
		panic("register a collection from its own realm")
	}
	if list != nil && list.TokenID() != token.ID() {
		panic("the list belongs to another collection")
	}
	if collections.Has(key) {
		panic("collection already registered")
	}
	collections.Set(key, &collection{token: token, list: list})
	chain.Emit("CollectionRegistered",
		"key", key,
		"name", token.GetName(),
		"symbol", token.GetSymbol(),
	)
	return key
}

// DepositNFT moves one NFT of a registered collection from the caller to
// this realm and adds it to the caller's side. The caller must first
// approve this realm's address (see Address) for that token id, in the
// collection's realm.
func DepositNFT(cur realm, roomID uint64, collectionKey string, tokenID string) {
	who := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()
	col := mustCollection(collectionKey)
	assertTokenID(tokenID)

	r := mustRoom(roomID)
	r.assertLive()
	mine, _ := r.sideOf(who)
	r.assertAccepts(KindNFT, collectionKey)
	denom := collectionKey + "#" + tokenID
	tid := grc721.TokenID(tokenID)

	// Say plainly what is missing before anything changes.
	if owner, err := col.token.OwnerOf(tid); err != nil || owner != who {
		panic("you do not own that NFT")
	}
	if to, err := col.token.GetApproved(tid); (err != nil || to != cur.Address()) && !col.token.IsApprovedForAll(who, cur.Address()) {
		panic("approve this realm for that NFT first")
	}

	// Record first, move second: a GRC721 transfer runs the issuer's
	// extension hooks, and anything they call back into must already see
	// the room as it will be. A failed transfer aborts the whole call.
	mine.addNFT(denom)
	r.bump()

	// This realm is the spender: the owner's approval to it is what moves.
	if err := col.token.RealmTeller(0, cur).TransferFrom(0, cur, who, cur.Address(), tid); err != nil {
		panic(err.Error())
	}

	chain.Emit("Deposited",
		"id", idString(r.id),
		"party", who.String(),
		"nft", collectionKey,
		"tokenId", tokenID,
		"version", idString(r.version),
	)
}

// WithdrawNFT returns one NFT from the caller's side to the caller. Same
// rules as WithdrawCoins: it works while the room is open, also after it
// has expired or while the realm is paused.
func WithdrawNFT(cur realm, roomID uint64, collectionKey string, tokenID string) {
	withdraw(cur, roomID, KindNFT, collectionKey+"#"+tokenID, 1)
}

// sendNFT pays one NFT out of this realm's custody.
func sendNFT(cur realm, to address, denom string) {
	key, tid, ok := strings.Cut(denom, "#")
	if !ok {
		panic("unknown NFT")
	}
	col := mustCollection(key)
	if err := col.token.RealmTeller(0, cur).TransferFrom(0, cur, cur.Address(), to, grc721.TokenID(tid)); err != nil {
		panic(err.Error())
	}
}

func (s *side) addNFT(denom string) {
	for _, a := range s.assets {
		if a.kind == KindNFT && a.denom == denom {
			panic("that NFT is already in the room")
		}
	}
	if len(s.assets) >= MaxAssetsPerSide {
		panic("a side can hold at most 8 different assets")
	}
	s.assets = append(s.assets, asset{kind: KindNFT, denom: denom, amount: 1})
}

func mustCollection(key string) *collection {
	v := collections.Get(key)
	if v == nil {
		panic("collection is not registered with rooms")
	}
	return v.(*collection)
}

func assertTokenID(tid string) {
	if tid == "" || len(tid) > MaxTokenIDLen {
		panic("token id must be 1 to " + strconv.Itoa(MaxTokenIDLen) + " bytes")
	}
	for _, r := range tid {
		if r < 0x20 || r == 0x7f {
			panic("token id has a control character")
		}
	}
}

package rooms

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/grc721/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Offers: a room that completes in one transaction.
//
// The maker puts their side in as usual, then calls Offer with the exact
// list of what they want in return. That locks the maker's side on the new
// version. Whoever may take the other seat (the invited account, or anyone
// when the seat is open) calls Fill naming the version they reviewed and
// putting in exactly the wanted list: coins attached to the call, tokens
// and NFTs approved to this realm beforehand (the app sends the approvals
// and Fill in one transaction). Fill takes the seat, moves the wanted
// assets in and settles the room before it returns. Nothing partial: a
// wrong coin, a missing approval or a changed room fails the whole call.
//
// The maker can withdraw the offer at any time: Unlock, any deposit or
// withdrawal, or Cancel. Every change to the room clears it, and Fill names
// the version, so an offer can never be filled on terms the taker did not
// see. While an offer stands, Join is refused, so nobody can block an open
// offer by taking its seat without filling it.

// Offer turns the room into an offer for exactly want, on the room as it is
// at version. want lists one asset per line, at most 8:
//
//	coin <amount> <denom>
//	token <amount> <grc20reg key>
//	nft 1 <collection key>#<token id>
//
// Amounts are in base units. Returns the new version, which the taker
// fills.
func Offer(cur realm, roomID uint64, version uint64, want string) uint64 {
	who := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()

	r := mustRoom(roomID)
	r.assertLive()
	if who != r.maker.owner {
		panic("only the maker can make an offer")
	}
	if version != r.version {
		panic("the room changed: review version " + idString(r.version) + " and offer again")
	}
	if len(r.maker.assets) == 0 {
		panic("put something in before you make an offer")
	}
	if len(r.taker.assets) > 0 {
		panic("they have already put something in: agree in the room instead")
	}
	items := parseWant(want)
	for _, a := range items {
		r.assertAccepts(a.kind, a.denom)
	}
	r.assertStillVerified()

	r.bump()
	r.want = items
	r.maker.locked = r.version

	chain.Emit("Offered",
		"id", idString(r.id),
		"version", idString(r.version),
		"want", wantString(items),
	)
	return r.version
}

// Fill completes an offer: the caller takes the other seat, puts in exactly
// what the offer wants, and the room settles in this call. version is the
// version the caller reviewed. Coins in the offer must be attached to this
// call, from the caller's own account.
func Fill(cur realm, roomID uint64, version uint64) {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	prev := cur.Previous()
	who := prev.Address()
	assertNotPaused()

	r := mustRoom(roomID)
	r.assertLive()
	if len(r.want) == 0 {
		panic("this room has no standing offer")
	}
	if version != r.version {
		panic("the offer changed: review version " + idString(r.version) + " and fill again")
	}
	if r.maker.locked != r.version {
		panic("the offer is withdrawn")
	}
	if who == r.maker.owner {
		panic("you made this offer")
	}
	if r.taker.owner != "" && r.taker.owner != who {
		panic("this offer is for another account")
	}
	if r.taker.owner == "" && !r.openSeat {
		panic("this offer is for another account")
	}
	if len(r.taker.assets) > 0 {
		panic("this room is not an offer any more")
	}
	r.assertStillVerified()

	// Coins can only arrive with a direct call from the signing account,
	// and they must be exactly the wanted coins: no more, no less, no other.
	var sent chain.Coins
	if prev.IsUserCall() {
		sent = unsafe.OriginSend()
	}
	wantCoins := chain.Coins{}
	for _, a := range r.want {
		if a.kind == KindCoin {
			wantCoins = append(wantCoins, chain.Coin{Denom: a.denom, Amount: a.amount})
		}
	}
	if len(wantCoins) > 0 && !prev.IsUserCall() {
		panic("send the coins with a direct call from your account")
	}
	if !sameCoins(sent, wantCoins) {
		if len(wantCoins) == 0 {
			panic("this offer does not take coins")
		}
		panic("attach exactly " + wantCoins.String())
	}

	// Say plainly what is missing before anything changes.
	for _, a := range r.want {
		switch a.kind {
		case KindToken:
			tok := grc20reg.Get(a.denom)
			if tok == nil {
				panic("token is not in the GRC20 registry")
			}
			if tok.BalanceOf(who) < a.amount {
				panic("you do not have enough " + tok.GetSymbol())
			}
			if tok.Allowance(who, cur.Address()) < a.amount {
				panic("approve this realm for " + tok.GetSymbol() + " first")
			}
		case KindNFT:
			key, tid, _ := strings.Cut(a.denom, "#")
			col := mustCollection(key)
			if owner, err := col.token.OwnerOf(grc721.TokenID(tid)); err != nil || owner != who {
				panic("you do not own " + col.token.GetName() + " #" + tid)
			}
			if to, err := col.token.GetApproved(grc721.TokenID(tid)); (err != nil || to != cur.Address()) && !col.token.IsApprovedForAll(who, cur.Address()) {
				panic("approve this realm for " + col.token.GetName() + " #" + tid + " first")
			}
		}
	}

	// Hold the room while the wanted assets move in: an NFT's transfer runs
	// its issuer's code, and nothing that code calls may change this room.
	r.status = statusFilling
	for _, a := range r.want {
		switch a.kind {
		case KindToken:
			grc20reg.TransferFrom(0, cur, a.denom, who, cur.Address(), a.amount)
		case KindNFT:
			key, tid, _ := strings.Cut(a.denom, "#")
			col := mustCollection(key)
			if err := col.token.RealmTeller(0, cur).TransferFrom(0, cur, who, cur.Address(), grc721.TokenID(tid)); err != nil {
				panic(err.Error())
			}
		}
	}

	// Everything is in custody: record the taker's side and swap.
	r.status = StatusOpen
	if r.taker.owner == "" {
		r.taker.owner = who
		index(who, r.id)
	}
	r.taker.assets = append([]asset{}, r.want...)
	r.taker.locked = r.version
	r.want = nil

	chain.Emit("Filled",
		"id", idString(r.id),
		"taker", who.String(),
		"version", idString(r.version),
	)
	r.settle(cur, who)
}

// parseWant reads an offer's want list; see Offer.
func parseWant(want string) []asset {
	items := []asset{}
	for _, line := range strings.Split(want, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		kind, rest, ok := strings.Cut(line, " ")
		if !ok {
			panic("each line of the want list is: kind amount denom")
		}
		amountText, denom, ok := strings.Cut(strings.TrimSpace(rest), " ")
		denom = strings.TrimSpace(denom)
		if !ok || denom == "" {
			panic("each line of the want list is: kind amount denom")
		}
		amount, err := strconv.ParseInt(amountText, 10, 64)
		if err != nil || amount <= 0 {
			panic("want amounts must be positive whole numbers of base units")
		}
		switch kind {
		case KindCoin:
			assertDenom(denom)
		case KindToken:
			if grc20reg.Get(denom) == nil {
				panic("token is not in the GRC20 registry: " + denom)
			}
		case KindNFT:
			key, tid, ok := strings.Cut(denom, "#")
			if !ok {
				panic("an NFT is written as collection key#token id")
			}
			col := mustCollection(key)
			assertTokenID(tid)
			if _, err := col.token.OwnerOf(grc721.TokenID(tid)); err != nil {
				panic("that NFT does not exist: " + denom)
			}
			if amount != 1 {
				panic("an NFT is wanted whole: amount 1")
			}
		default:
			panic("unknown kind in the want list: " + kind)
		}
		for _, a := range items {
			if a.kind == kind && a.denom == denom {
				panic("the want list names " + denom + " twice")
			}
		}
		if len(items) >= MaxAssetsPerSide {
			panic("an offer can want at most 8 different assets")
		}
		items = append(items, asset{kind: kind, denom: denom, amount: amount})
	}
	if len(items) == 0 {
		panic("say what you want in return")
	}
	return items
}

// wantString writes a want list back in Offer's format.
func wantString(items []asset) string {
	lines := make([]string, 0, len(items))
	for _, a := range items {
		lines = append(lines, a.kind+" "+strconv.FormatInt(a.amount, 10)+" "+a.denom)
	}
	return strings.Join(lines, "\n")
}

// assertDenom accepts bank denoms: 3 to 128 characters of lowercase
// letters, digits and / : . _ -, starting with a letter.
func assertDenom(d string) {
	if len(d) < 3 || len(d) > 128 {
		panic("not a coin denom: " + d)
	}
	for i, c := range d {
		ok := c >= 'a' && c <= 'z' || i > 0 && (c >= '0' && c <= '9' || c == '/' || c == ':' || c == '.' || c == '_' || c == '-')
		if !ok {
			panic("not a coin denom: " + d)
		}
	}
}

// sameCoins reports whether a and b hold the same amount of every denom.
func sameCoins(a, b chain.Coins) bool {
	total := func(cs chain.Coins) map[string]int64 {
		m := map[string]int64{}
		for _, c := range cs {
			if c.Amount != 0 {
				m[c.Denom] += c.Amount
			}
		}
		return m
	}
	ma, mb := total(a), total(b)
	if len(ma) != len(mb) {
		return false
	}
	for d, n := range ma {
		if mb[d] != n {
			return false
		}
	}
	return true
}

package rooms

import (
	"strings"
	"time"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Read-only views for clients. Each returns a JSON document as a string so
// a frontend can read it with one vm/qeval query. Amounts are strings
// because int64 does not fit a JavaScript number. Times are unix seconds;
// "now" is the block time the answer was computed at.

const maxPage = 50

// Address returns this realm's address: the spender to approve before
// DepositToken, and the account that holds deposits.
func Address() string {
	return self.String()
}

// RoomJSON returns one room, or null when it does not exist.
func RoomJSON(id uint64) string {
	v := rooms.Get(roomKey(id))
	if v == nil {
		return "null"
	}
	return v.(*room).json(time.Now().Unix())
}

// RoomsOfJSON lists the rooms where addr is maker or taker, newest first.
func RoomsOfJSON(addr string, offset, limit int) string {
	offset, limit = page(offset, limit)
	now := time.Now().Unix()
	items := []string{}
	var ids []uint64
	if v := byParty.Get(strings.TrimSpace(addr)); v != nil {
		ids = v.([]uint64)
	}
	more := false
	for i := len(ids) - 1 - offset; i >= 0; i-- {
		if len(items) == limit {
			more = true
			break
		}
		items = append(items, mustRoom(ids[i]).json(now))
	}
	return jsonObject(
		"rooms", jsonArray(items),
		"more", jsonBool(more),
		"now", jsonInt(now),
	)
}

// LatestJSON lists all rooms, newest first.
func LatestJSON(offset, limit int) string {
	offset, limit = page(offset, limit)
	now := time.Now().Unix()
	items := []string{}
	rooms.ReverseIterateByOffset(offset, limit, func(_ string, v any) bool {
		items = append(items, v.(*room).json(now))
		return false
	})
	return jsonObject(
		"rooms", jsonArray(items),
		"total", jsonUint(lastID),
		"now", jsonInt(now),
	)
}

// StatsJSON returns counters and the settled volume per asset.
func StatsJSON() string {
	vol := []string{}
	volume.Iterate("", "", func(key string, v any) bool {
		kind, denom, _ := strings.Cut(key, ":")
		vol = append(vol, jsonObject(
			"kind", jsonString(kind),
			"denom", jsonString(denom),
			"amount", jsonString(jsonInt(v.(int64))),
		))
		return false
	})
	collected := []string{}
	fees.Iterate("", "", func(key string, v any) bool {
		kind, denom, _ := strings.Cut(key, ":")
		collected = append(collected, jsonObject(
			"kind", jsonString(kind),
			"denom", jsonString(denom),
			"amount", jsonString(jsonInt(v.(int64))),
		))
		return false
	})
	return jsonObject(
		"rooms", jsonUint(lastID),
		"settled", jsonUint(nSettled),
		"cancelled", jsonUint(nCancelled),
		"volume", jsonArray(vol),
		"fees", jsonArray(collected),
		"feeBps", jsonUint(openingFee()),
		"treasury", jsonString(treasury.String()),
		"paused", jsonBool(paused),
		"address", jsonString(self.String()),
		"now", jsonInt(time.Now().Unix()),
	)
}

// TokensJSON lists GRC20 tokens from the registry that rooms accept.
func TokensJSON(offset, limit int) string {
	offset, limit = page(offset, limit)
	items := []string{}
	grc20reg.GetRegistry().IterateByOffset(offset, limit, func(key string, v any) bool {
		items = append(items, tokenJSON(key, v.(*grc20.Token)))
		return false
	})
	return jsonObject("tokens", jsonArray(items))
}

// TokenJSON describes one registered token and, when owner is given, the
// owner's balance and current allowance to this realm.
func TokenJSON(key string, owner string) string {
	tok := grc20reg.Get(key)
	if tok == nil {
		return "null"
	}
	if owner == "" {
		return tokenJSON(key, tok)
	}
	who := address(owner)
	if !who.IsValid() {
		return "null"
	}
	return jsonObject(
		"key", jsonString(key),
		"name", jsonString(tok.GetName()),
		"symbol", jsonString(tok.GetSymbol()),
		"decimals", jsonInt(int64(tok.GetDecimals())),
		"balance", jsonString(jsonInt(tok.BalanceOf(who))),
		"allowance", jsonString(jsonInt(tok.Allowance(who, self))),
	)
}

// BalancesJSON lists the registered GRC20 tokens that owner holds, with the
// balance and the allowance to this realm: a wallet's inventory in one
// query. A page covers limit registry entries (at most 50); read on while
// "more" is true.
func BalancesJSON(owner string, offset, limit int) string {
	offset, limit = page(offset, limit)
	who := address(strings.TrimSpace(owner))
	if !who.IsValid() {
		return "null"
	}
	reg := grc20reg.GetRegistry()
	items := []string{}
	seen := 0
	reg.IterateByOffset(offset, limit, func(key string, v any) bool {
		seen++
		tok := v.(*grc20.Token)
		if bal := tok.BalanceOf(who); bal > 0 {
			items = append(items, jsonObject(
				"key", jsonString(key),
				"name", jsonString(tok.GetName()),
				"symbol", jsonString(tok.GetSymbol()),
				"decimals", jsonInt(int64(tok.GetDecimals())),
				"balance", jsonString(jsonInt(bal)),
				"allowance", jsonString(jsonInt(tok.Allowance(who, self))),
			))
		}
		return false
	})
	return jsonObject(
		"tokens", jsonArray(items),
		"more", jsonBool(offset+seen < reg.Size()),
	)
}

// CollectionsJSON lists the GRC721 collections registered with rooms.
func CollectionsJSON(offset, limit int) string {
	offset, limit = page(offset, limit)
	items := []string{}
	collections.IterateByOffset(offset, limit, func(key string, v any) bool {
		col := v.(*collection)
		items = append(items, jsonObject(
			"key", jsonString(key),
			"name", jsonString(col.token.GetName()),
			"symbol", jsonString(col.token.GetSymbol()),
			"listed", jsonBool(col.list != nil),
			"verified", jsonBool(IsVerified(KindNFT, key)),
		))
		return false
	})
	return jsonObject(
		"collections", jsonArray(items),
		"more", jsonBool(offset+len(items) < collections.Size()),
	)
}

// NFTJSON describes one NFT of a registered collection: who owns it, and
// whether this realm is approved to move it. null when the collection is
// not registered or the token does not exist.
func NFTJSON(collectionKey string, tokenID string) string {
	v := collections.Get(collectionKey)
	if v == nil {
		return "null"
	}
	col := v.(*collection)
	tid := grc721.TokenID(tokenID)
	owner, err := col.token.OwnerOf(tid)
	if err != nil {
		return "null"
	}
	approved := col.token.IsApprovedForAll(owner, self)
	if to, err := col.token.GetApproved(tid); err == nil && to == self {
		approved = true
	}
	return jsonObject(
		"key", jsonString(collectionKey),
		"name", jsonString(col.token.GetName()),
		"symbol", jsonString(col.token.GetSymbol()),
		"tokenId", jsonString(tokenID),
		"owner", jsonString(owner.String()),
		"approved", jsonBool(approved),
	)
}

// maxOwnedPerCollection bounds one OwnedJSON page.
const maxOwnedPerCollection = 20

// OwnedJSON lists the NFTs owner holds in registered collections that can
// be listed (those registered with their enumerable view), at most 20 per
// collection, and whether this realm is approved for each. A page covers
// limit collections; read on while "more" is true.
func OwnedJSON(owner string, offset, limit int) string {
	offset, limit = page(offset, limit)
	who := address(strings.TrimSpace(owner))
	if !who.IsValid() {
		return "null"
	}
	items := []string{}
	seen := 0
	collections.IterateByOffset(offset, limit, func(key string, v any) bool {
		seen++
		col := v.(*collection)
		if col.list == nil {
			return false
		}
		n, err := col.token.BalanceOf(who)
		if err != nil || n <= 0 {
			return false
		}
		if n > maxOwnedPerCollection {
			n = maxOwnedPerCollection
		}
		operator := col.token.IsApprovedForAll(who, self)
		for i := int64(0); i < n; i++ {
			tid, err := col.list.TokenOfOwnerByIndex(who, i)
			if err != nil {
				break
			}
			approved := operator
			if !approved {
				if to, err := col.token.GetApproved(tid); err == nil && to == self {
					approved = true
				}
			}
			items = append(items, jsonObject(
				"key", jsonString(key),
				"name", jsonString(col.token.GetName()),
				"symbol", jsonString(col.token.GetSymbol()),
				"tokenId", jsonString(string(tid)),
				"approved", jsonBool(approved),
			))
		}
		return false
	})
	return jsonObject(
		"nfts", jsonArray(items),
		"more", jsonBool(offset+seen < collections.Size()),
	)
}

func tokenJSON(key string, tok *grc20.Token) string {
	return jsonObject(
		"key", jsonString(key),
		"name", jsonString(tok.GetName()),
		"symbol", jsonString(tok.GetSymbol()),
		"decimals", jsonInt(int64(tok.GetDecimals())),
		"verified", jsonBool(IsVerified(KindToken, key)),
	)
}

// json describes the room at block time now (unix seconds).
func (r *room) json(now int64) string {
	return jsonObject(
		"id", jsonUint(r.id),
		"status", jsonString(r.status),
		"expired", jsonBool(r.status == StatusOpen && now >= r.expiresAt),
		"version", jsonUint(r.version),
		"openSeat", jsonBool(r.openSeat),
		"openMarket", jsonBool(r.openMarket),
		"createdAt", jsonInt(r.createdAt),
		"expiresAt", jsonInt(r.expiresAt),
		"closedAt", jsonInt(r.closedAt),
		"closedBy", jsonString(r.closedBy.String()),
		"maker", r.maker.json(),
		"taker", r.taker.json(),
		"want", assetsJSON(r.want),
		"feeBps", jsonUint(r.feeBps),
		"now", jsonInt(now),
	)
}

func assetsJSON(list []asset) string {
	items := make([]string, 0, len(list))
	for _, a := range list {
		items = append(items, jsonObject(
			"kind", jsonString(a.kind),
			"denom", jsonString(a.denom),
			"amount", jsonString(jsonInt(a.amount)),
		))
	}
	return jsonArray(items)
}

func (s *side) json() string {
	return jsonObject(
		"address", jsonString(s.owner.String()),
		"locked", jsonUint(s.locked),
		"assets", assetsJSON(s.assets),
	)
}

func page(offset, limit int) (int, int) {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	return offset, limit
}

package rooms

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Render shows the realm on gnoweb: the home page lists recent rooms, and
// room/<id> shows one room. Every value that comes from a caller goes
// through sanitize before it reaches the markdown.
func Render(path string) string {
	path = strings.TrimSpace(path)
	if path == "" {
		return renderHome()
	}
	if rest, ok := strings.CutPrefix(path, "room/"); ok {
		id, err := strconv.ParseUint(rest, 10, 64)
		if err == nil {
			if v := rooms.Get(roomKey(id)); v != nil {
				return renderRoom(v.(*room), time.Now().Unix())
			}
		}
	}
	return "# Not found\n\nNo room at this address.\n"
}

func renderHome() string {
	now := time.Now().Unix()
	var b strings.Builder
	b.WriteString("# Trade Window rooms\n\n")
	b.WriteString("Two parties put assets into a room. Each change raises the room's version. ")
	b.WriteString("Both lock the same version, and the second lock swaps everything in one transaction. ")
	b.WriteString("Until then either side can withdraw or cancel. ")
	b.WriteString("A room can also be an offer: the maker's side and an exact list of what they want, filled by the first allowed account in one transaction.\n\n")
	if fee := openingFee(); fee > 0 {
		b.WriteString("Service fee on settlement: " + decimal(int64(fee), 2) + "% of every coin and token that crosses, from each side. NFTs, withdrawals and cancellations pay nothing.\n\n")
	}
	b.WriteString("Rooms opened: " + jsonUint(lastID) +
		", settled: " + jsonUint(nSettled) +
		", cancelled: " + jsonUint(nCancelled) + ".\n\n")
	if paused {
		b.WriteString("New activity is paused. Withdraw, unlock and cancel still work.\n\n")
	}
	if lastID == 0 {
		b.WriteString("No rooms yet.\n")
		return b.String()
	}
	b.WriteString("## Latest\n\n")
	rooms.ReverseIterateByOffset(0, 20, func(_ string, v any) bool {
		r := v.(*room)
		b.WriteString("- [Room " + jsonUint(r.id) + "](:room/" + jsonUint(r.id) + "): " +
			r.statusLabel(now) + ", " + sideSummary(&r.maker) + " for " + sideSummary(&r.taker) + "\n")
		return false
	})
	return b.String()
}

func renderRoom(r *room, now int64) string {
	var b strings.Builder
	b.WriteString("# Room " + jsonUint(r.id) + "\n\n")
	b.WriteString("Status: " + r.statusLabel(now) + ", version " + jsonUint(r.version) + ".\n\n")
	b.WriteString("Opened " + stamp(r.createdAt))
	if r.status == StatusOpen {
		b.WriteString(". Can settle until " + stamp(r.expiresAt))
	} else if r.closedAt != 0 {
		b.WriteString(". Closed " + stamp(r.closedAt))
	}
	b.WriteString(".")
	if r.openMarket {
		b.WriteString(" Open market: this room takes any registered asset, verified or not.")
	} else {
		b.WriteString(" Verified assets only.")
	}
	if r.feeBps > 0 {
		b.WriteString(" Fee on settlement: " + decimal(int64(r.feeBps), 2) + "% of coins and tokens, from each side.")
	}
	b.WriteString("\n\n")
	b.WriteString(renderSide("Maker", &r.maker, r.version))
	if len(r.want) > 0 {
		b.WriteString("## Offer\n\nThe maker wants exactly this in return; the first allowed account that puts it in completes the trade:\n\n")
		for _, a := range r.want {
			b.WriteString("- " + sanitize.InlineText(formatAsset(a)) + ", " + sanitize.InlineCode(a.denom) + "\n")
		}
		b.WriteString("\n")
	}
	if r.taker.owner == "" && len(r.want) > 0 {
		b.WriteString("## Taker\n\nThe seat is open: any account can fill the offer.\n\n")
	} else if r.taker.owner == "" {
		b.WriteString("## Taker\n\nThe seat is open: any account can join.\n\n")
	} else {
		b.WriteString(renderSide("Taker", &r.taker, r.version))
	}
	return b.String()
}

func renderSide(title string, s *side, version uint64) string {
	var b strings.Builder
	b.WriteString("## " + title + "\n\n")
	b.WriteString(sanitize.InlineCode(s.owner.String()))
	if s.locked != 0 && s.locked == version {
		b.WriteString(", locked this version")
	}
	b.WriteString("\n\n")
	if len(s.assets) == 0 {
		b.WriteString("Nothing deposited.\n\n")
		return b.String()
	}
	for _, a := range s.assets {
		b.WriteString("- " + sanitize.InlineText(formatAsset(a)) + ", " + sanitize.InlineCode(a.denom) + "\n")
	}
	b.WriteString("\n")
	return b.String()
}

func sideSummary(s *side) string {
	if len(s.assets) == 0 {
		return "nothing"
	}
	parts := make([]string, 0, len(s.assets))
	for _, a := range s.assets {
		parts = append(parts, sanitize.InlineText(formatAsset(a)))
	}
	return strings.Join(parts, " and ")
}

// wugnotKey is wrapped GNOT in the GRC20 registry. Its token declares 0
// decimals because one unit is one ugnot, so it is shown in GNOT like the
// coin, marked as wrapped so the two are never confused.
const wugnotKey = "gno.land/r/gnoland/wugnot.wugnot"

// formatAsset writes an amount in whole units: GNOT for ugnot and wrapped
// GNOT, the registry's symbol and decimals for other tokens, the raw denom
// otherwise.
func formatAsset(a asset) string {
	switch {
	case a.kind == KindCoin && a.denom == "ugnot":
		return decimal(a.amount, 6) + " GNOT"
	case a.kind == KindToken && a.denom == wugnotKey:
		return decimal(a.amount, 6) + " GNOT (wrapped)"
	case a.kind == KindToken:
		if tok := grc20reg.Get(a.denom); tok != nil {
			return decimal(a.amount, tok.GetDecimals()) + " " + tok.GetSymbol()
		}
	case a.kind == KindNFT:
		key, tid, _ := strings.Cut(a.denom, "#")
		if v := collections.Get(key); v != nil {
			return "NFT " + v.(*collection).token.GetName() + " #" + tid
		}
		return "NFT #" + tid
	}
	return strconv.FormatInt(a.amount, 10) + " " + a.denom
}

// decimal formats amount with the given number of decimals and no
// trailing zeros.
func decimal(amount int64, decimals int) string {
	s := strconv.FormatInt(amount, 10)
	if decimals <= 0 {
		return s
	}
	if len(s) <= decimals {
		s = strings.Repeat("0", decimals-len(s)+1) + s
	}
	whole, frac := s[:len(s)-decimals], strings.TrimRight(s[len(s)-decimals:], "0")
	if frac == "" {
		return whole
	}
	return whole + "." + frac
}

func (r *room) statusLabel(now int64) string {
	if r.status == StatusOpen && now >= r.expiresAt {
		return "expired"
	}
	return r.status
}

// stamp writes unix seconds as an RFC 3339 time in UTC.
func stamp(unix int64) string {
	return time.Unix(unix, 0).UTC().Format(time.RFC3339)
}

// Package rooms is the on-chain trade window.
//
// Two parties share a room. Each one puts assets on their own side: native
// coins (GNOT and any other bank denom), GRC20 tokens from the registry at
// gno.land/r/nt/grc20reg/v0, and GRC721 NFTs from collections registered
// with this realm (see RegisterCollection). The realm holds the deposits.
//
// Every change to the room raises its version. A party locks the room by
// naming the exact version they reviewed, so a lock can never apply to
// contents the party has not seen. When both sides hold a lock on the
// current version, the second lock swaps everything in the same
// transaction: the maker's side goes to the taker and the taker's side
// goes to the maker.
//
// Until that moment each party can withdraw their own deposits, and either
// party can cancel the room, which returns every deposit to its owner. An
// expired room can no longer settle; its deposits stay withdrawable, and
// anyone may cancel it to send them home.
//
// A maker can also turn a room into an offer (see Offer): their side plus an
// exact list of what they want in return. The first account allowed to take
// the other seat that puts in exactly that list completes the trade in one
// transaction (see Fill).
//
// On settlement the realm keeps a service fee on coins and tokens (see
// fee.gno); NFTs, withdrawals and cancellations pay nothing.
package rooms

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"math"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
)

const (
	StatusOpen      = "open"
	StatusSettled   = "settled"
	StatusCancelled = "cancelled"

	// statusFilling holds a room for the length of one Fill, so nothing an
	// asset's own code runs during the transfers can change it.
	statusFilling = "filling"

	KindCoin  = "coin"
	KindToken = "token"
	KindNFT   = "nft"

	// MaxAssetsPerSide bounds the work a settlement or refund can do.
	MaxAssetsPerSide = 8

	DefaultTTLMinutes = 24 * 60
	MinTTLMinutes     = 10
	MaxTTLMinutes     = 7 * 24 * 60
)

type asset struct {
	kind   string // KindCoin, KindToken or KindNFT
	denom  string // bank denom, grc20reg key, or collection key + "#" + token id
	amount int64  // always 1 for an NFT
}

type side struct {
	owner  address
	assets []asset
	locked uint64 // version this side locked; 0 when not locked
}

// A room keeps both sides inline and its times as unix seconds: every
// separate object costs storage deposit, and a room is opened often.
type room struct {
	id       uint64
	maker    side
	taker    side
	openSeat bool // anyone may take the taker seat with Join
	// openMarket rooms take any registered asset; ordinary rooms take only
	// verified ones (see verified.gno).
	openMarket bool
	status     string
	version    uint64
	// want is the maker's standing offer: exactly what the taker must put
	// in for Fill to complete the trade. Any change to the room clears it.
	want      []asset
	feeBps    uint64 // the fee rate this room was opened with
	createdAt int64  // unix seconds of block time
	expiresAt int64
	closedAt  int64 // 0 while open
	closedBy  address
}

var (
	rooms   avl.Tree // padded id -> *room
	byParty avl.Tree // address -> []uint64 room ids, oldest first
	volume  avl.Tree // kind + ":" + denom -> int64 settled amount; NFTs count per collection

	lastID     uint64
	nSettled   uint64
	nCancelled uint64

	self address
)

func init(cur realm) {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	self = cur.Address()
	seedVerified()
	prev := cur.Previous()
	if prev.IsUserCall() && prev.Address().IsValid() {
		admin = prev.Address()
		treasury = admin
	}
}

// Open creates a room with the caller as maker and returns its id. The room
// takes only verified assets (see Verify). counterparty is the taker's
// address, or "" to leave the seat open for the first account that calls
// Join. ttlMinutes is how long the room can settle; 0 means 24 hours, and
// the allowed range is 10 minutes to 7 days.
func Open(cur realm, counterparty string, ttlMinutes int) uint64 {
	return open(cur, counterparty, ttlMinutes, false)
}

// OpenMarket is Open for a room that takes any registered asset, verified
// or not. Both parties trade unverified assets at their own risk; the app
// says so in every view of such a room.
func OpenMarket(cur realm, counterparty string, ttlMinutes int) uint64 {
	return open(cur, counterparty, ttlMinutes, true)
}

func open(cur realm, counterparty string, ttlMinutes int, openMarket bool) uint64 {
	maker := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()

	ttl := ttlMinutes
	if ttl == 0 {
		ttl = DefaultTTLMinutes
	}
	if ttl < MinTTLMinutes || ttl > MaxTTLMinutes {
		panic("room lifetime must be between 10 minutes and 7 days")
	}

	r := &room{
		maker:      side{owner: maker},
		status:     StatusOpen,
		feeBps:     openingFee(),
		openMarket: openMarket,
	}
	counterparty = strings.TrimSpace(counterparty)
	if counterparty == "" {
		r.openSeat = true
	} else {
		cp := address(counterparty)
		if !cp.IsValid() {
			panic("counterparty is not a valid address")
		}
		if cp == maker {
			panic("you cannot open a room with yourself")
		}
		r.taker.owner = cp
	}

	lastID++
	r.id = lastID
	r.version = 1
	now := time.Now().Unix()
	r.createdAt = now
	r.expiresAt = now + int64(ttl)*60

	rooms.Set(roomKey(r.id), r)
	index(maker, r.id)
	if r.taker.owner != "" {
		index(r.taker.owner, r.id)
	}

	chain.Emit("RoomOpened",
		"id", idString(r.id),
		"maker", maker.String(),
		"taker", r.taker.owner.String(),
		"expires", strconv.FormatInt(r.expiresAt, 10),
		"openMarket", strconv.FormatBool(openMarket),
	)
	return r.id
}

// Join takes the open taker seat of a room.
func Join(cur realm, roomID uint64) {
	who := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()

	r := mustRoom(roomID)
	r.assertLive()
	if !r.openSeat {
		panic("this room is invite only")
	}
	if r.taker.owner != "" {
		panic("the seat is already taken")
	}
	if who == r.maker.owner {
		panic("you opened this room")
	}
	if len(r.want) > 0 {
		panic("this room is an offer: fill it instead")
	}
	r.taker.owner = who
	index(who, r.id)
	r.bump()

	chain.Emit("RoomJoined", "id", idString(r.id), "taker", who.String())
}

// DepositCoins adds the coins sent with this call to the caller's side.
// It must be called directly from the depositing account (maketx call or a
// wallet MsgCall), because only then are the sent coins guaranteed to have
// reached this realm.
func DepositCoins(cur realm, roomID uint64) {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	prev := cur.Previous()
	// IsUserCall and OriginSend are a pair: OriginSend describes coins that
	// actually arrived here only when the caller is the signing account.
	// A code realm or a maketx run script could spend the envelope first.
	if !prev.IsUserCall() {
		panic("send coins with a direct call from your account")
	}
	who := prev.Address()
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		panic("attach the coins to this call")
	}
	assertNotPaused()

	r := mustRoom(roomID)
	r.assertLive()
	mine, _ := r.sideOf(who)
	for _, c := range sent {
		if c.Amount <= 0 {
			panic("coin amounts must be positive")
		}
		r.assertAccepts(KindCoin, c.Denom)
		mine.add(KindCoin, c.Denom, c.Amount)
	}
	r.bump()

	chain.Emit("Deposited",
		"id", idString(r.id),
		"party", who.String(),
		"coins", sent.String(),
		"version", idString(r.version),
	)
}

// DepositToken moves amount of a registered GRC20 token from the caller to
// this realm and adds it to the caller's side. The caller must first
// approve this realm's address (see Address) for at least amount.
func DepositToken(cur realm, roomID uint64, tokenKey string, amount int64) {
	who := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()
	if amount <= 0 {
		panic("amount must be positive")
	}
	if grc20reg.Get(tokenKey) == nil {
		panic("token is not in the GRC20 registry")
	}

	r := mustRoom(roomID)
	r.assertLive()
	mine, _ := r.sideOf(who)
	r.assertAccepts(KindToken, tokenKey)
	mine.assertRoomFor(KindToken, tokenKey, amount)

	// This realm is the spender: the owner's allowance to it is what moves.
	// The canonical GRC20 ledger runs no code of the token's author, so
	// nothing can call back into this realm before the deposit is recorded.
	grc20reg.TransferFrom(0, cur, tokenKey, who, cur.Address(), amount)
	mine.add(KindToken, tokenKey, amount)
	r.bump()

	chain.Emit("Deposited",
		"id", idString(r.id),
		"party", who.String(),
		"token", tokenKey,
		"amount", strconv.FormatInt(amount, 10),
		"version", idString(r.version),
	)
}

// WithdrawCoins returns amount of denom from the caller's side to the
// caller. It works while the room is open, also after it has expired or
// while the realm is paused.
func WithdrawCoins(cur realm, roomID uint64, denom string, amount int64) {
	withdraw(cur, roomID, KindCoin, denom, amount)
}

// WithdrawToken returns amount of a GRC20 token from the caller's side to
// the caller. Same rules as WithdrawCoins.
func WithdrawToken(cur realm, roomID uint64, tokenKey string, amount int64) {
	withdraw(cur, roomID, KindToken, tokenKey, amount)
}

func withdraw(cur realm, roomID uint64, kind, denom string, amount int64) {
	who := callerOf(cur)
	refuseCoins(cur)
	if amount <= 0 {
		panic("amount must be positive")
	}
	r := mustRoom(roomID)
	r.assertOpen()
	mine, _ := r.sideOf(who)
	mine.sub(kind, denom, amount)
	r.bump()

	send(cur, who, asset{kind: kind, denom: denom, amount: amount})

	chain.Emit("Withdrawn",
		"id", idString(r.id),
		"party", who.String(),
		"kind", kind,
		"denom", denom,
		"amount", strconv.FormatInt(amount, 10),
		"version", idString(r.version),
	)
}

// Lock records that the caller agrees to swap the room exactly as it is at
// version. It fails if the room has changed since. When the other side
// already holds a lock on the same version, this call settles the room and
// returns "settled"; otherwise it returns "locked".
func Lock(cur realm, roomID uint64, version uint64) string {
	who := callerOf(cur)
	refuseCoins(cur)
	assertNotPaused()

	r := mustRoom(roomID)
	r.assertLive()
	mine, theirs := r.sideOf(who)
	if r.taker.owner == "" {
		panic("waiting for a counterparty to join")
	}
	if version != r.version {
		panic("the room changed: review version " + idString(r.version) + " and lock again")
	}
	if len(r.maker.assets) == 0 || len(r.taker.assets) == 0 {
		panic("both sides need at least one asset")
	}
	r.assertStillVerified()
	if mine.locked == version {
		return "locked"
	}
	mine.locked = version

	chain.Emit("Locked",
		"id", idString(r.id),
		"party", who.String(),
		"version", idString(version),
	)

	if theirs.locked == version {
		r.settle(cur, who)
		return StatusSettled
	}
	return "locked"
}

// Unlock withdraws the caller's lock on the current version.
func Unlock(cur realm, roomID uint64) {
	who := callerOf(cur)
	refuseCoins(cur)
	r := mustRoom(roomID)
	r.assertOpen()
	mine, _ := r.sideOf(who)
	if mine.locked != r.version {
		panic("you have not locked this version")
	}
	mine.locked = 0
	if who == r.maker.owner {
		r.want = nil // the maker's lock is what an offer stands on
	}

	chain.Emit("Unlocked", "id", idString(r.id), "party", who.String())
}

// Cancel closes an open room and returns every deposit to its owner.
// Either party may cancel at any time before settlement; once the room has
// expired, anyone may cancel it.
func Cancel(cur realm, roomID uint64) {
	who := callerOf(cur)
	refuseCoins(cur)
	r := mustRoom(roomID)
	r.assertOpen()
	if !r.isParty(who) && !r.expired() {
		panic("only the two parties can cancel a room before it expires")
	}

	r.status = StatusCancelled
	r.closedAt = time.Now().Unix()
	r.closedBy = who
	nCancelled++

	for _, a := range r.maker.assets {
		send(cur, r.maker.owner, a)
	}
	if r.taker.owner != "" {
		for _, a := range r.taker.assets {
			send(cur, r.taker.owner, a)
		}
	}

	chain.Emit("Cancelled", "id", idString(r.id), "by", who.String())
}

func (r *room) settle(cur realm, by address) {
	r.status = StatusSettled
	r.closedAt = time.Now().Unix()
	r.closedBy = by
	nSettled++

	for _, a := range r.maker.assets {
		r.pay(cur, r.taker.owner, a)
		addVolume(a)
	}
	for _, a := range r.taker.assets {
		r.pay(cur, r.maker.owner, a)
		addVolume(a)
	}

	chain.Emit("Settled",
		"id", idString(r.id),
		"maker", r.maker.owner.String(),
		"taker", r.taker.owner.String(),
		"version", idString(r.version),
		"feeBps", strconv.FormatUint(r.feeBps, 10),
	)
}

// send pays one asset out of this realm's custody.
func send(cur realm, to address, a asset) {
	switch a.kind {
	case KindCoin:
		bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		bnk.SendCoins(cur.Address(), to, chain.Coins{{Denom: a.denom, Amount: a.amount}})
	case KindToken:
		grc20reg.Transfer(0, cur, a.denom, to, a.amount)
	case KindNFT:
		sendNFT(cur, to, a.denom)
	default:
		panic("unknown asset kind")
	}
}

// assertRoomFor panics if adding amount of an asset would break a limit.
func (s *side) assertRoomFor(kind, denom string, amount int64) {
	for _, a := range s.assets {
		if a.kind == kind && a.denom == denom {
			if amount > math.MaxInt64-a.amount {
				panic("amount is too large")
			}
			return
		}
	}
	if len(s.assets) >= MaxAssetsPerSide {
		panic("a side can hold at most 8 different assets")
	}
}

func (s *side) add(kind, denom string, amount int64) {
	s.assertRoomFor(kind, denom, amount)
	for i := range s.assets {
		if s.assets[i].kind == kind && s.assets[i].denom == denom {
			s.assets[i].amount += amount
			return
		}
	}
	s.assets = append(s.assets, asset{kind: kind, denom: denom, amount: amount})
}

func (s *side) sub(kind, denom string, amount int64) {
	for i := range s.assets {
		if s.assets[i].kind != kind || s.assets[i].denom != denom {
			continue
		}
		if amount > s.assets[i].amount {
			panic("you have less than that in the room")
		}
		s.assets[i].amount -= amount
		if s.assets[i].amount == 0 {
			s.assets = append(s.assets[:i], s.assets[i+1:]...)
		}
		return
	}
	panic("you have not deposited that asset")
}

// sideOf returns the caller's side and the other side, or panics for
// anyone who is not one of the two parties.
func (r *room) sideOf(who address) (*side, *side) {
	if who == r.maker.owner {
		return &r.maker, &r.taker
	}
	if r.taker.owner != "" && who == r.taker.owner {
		return &r.taker, &r.maker
	}
	panic("only the two parties of this room can do that")
}

func (r *room) isParty(who address) bool {
	return who == r.maker.owner || (r.taker.owner != "" && who == r.taker.owner)
}

func (r *room) expired() bool {
	return time.Now().Unix() >= r.expiresAt
}

func (r *room) assertOpen() {
	if r.status != StatusOpen {
		panic("this room is " + r.status)
	}
}

// bump records a change to the room: the version moves on, so every lock on
// an earlier version stops applying, and a standing offer is withdrawn.
func (r *room) bump() {
	r.version++
	r.want = nil
}

// assertLive is assertOpen plus a check that the room can still settle.
func (r *room) assertLive() {
	r.assertOpen()
	if r.expired() {
		panic("this room has expired: withdraw or cancel to get deposits back")
	}
}

// refuseCoins stops a direct call that carries coins to any function other
// than DepositCoins. Such coins would reach this realm with nothing
// recording them; failing the call sends them back.
func refuseCoins(cur realm) {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this call does not take coins: use DepositCoins")
	}
}

// callerOf names the immediate caller: the realm or account that was
// current when cur was minted for this crossing call. A crossing
// function's own cur is always current, so the IsCurrent check is belt and
// braces; it keeps every identity read in the shape reviewers and the gno
// audit harness look for.
func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	return cur.Previous().Address()
}

func mustRoom(id uint64) *room {
	v := rooms.Get(roomKey(id))
	if v == nil {
		panic("room not found")
	}
	return v.(*room)
}

// index records that who is a party of room id. One growing list per
// account keeps a returning trader's next room cheap to store.
func index(who address, id uint64) {
	key := who.String()
	var ids []uint64
	if v := byParty.Get(key); v != nil {
		ids = v.([]uint64)
	}
	byParty.Set(key, append(ids, id))
}

func addVolume(a asset) {
	key := a.kind + ":" + a.denom
	if a.kind == KindNFT {
		// One entry per collection, not per token: the tree stays small.
		collection, _, _ := strings.Cut(a.denom, "#")
		key = a.kind + ":" + collection
	}
	total := int64(0)
	if v := volume.Get(key); v != nil {
		total = v.(int64)
	}
	// Volume is informational; saturate instead of failing a settlement.
	if a.amount > math.MaxInt64-total {
		total = math.MaxInt64
	} else {
		total += a.amount
	}
	volume.Set(key, total)
}

// roomKey zero-pads ids so the tree iterates in numeric order.
func roomKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	if len(s) < 20 {
		s = strings.Repeat("0", 20-len(s)) + s
	}
	return s
}

func idString(id uint64) string {
	return strconv.FormatUint(id, 10)
}

package rooms

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Verified assets. A registry proves where a token or a collection comes
// from, not that it is worth anything: anyone can register a token called
// USDC, and an issuer keeps power over its ledger. So a room opened with
// Open accepts only verified assets: GNOT and wrapped GNOT from the start,
// then tokens and NFT collections the admin verifies, each with a public
// reason. A room opened with OpenMarket accepts any registered asset; the
// name of that call is what the wallet shows when it is signed.
//
// A verification counts only VerifyDelay after the admin makes it, so a
// stolen admin key cannot slip a worthless token into ordinary rooms before
// anyone notices; it is public from the moment it is made. Removing a
// verification counts at once: an ordinary room holding that asset can no
// longer settle, and everyone can still take their items back.

// VerifyDelay is how long a new verification waits before it counts.
const VerifyDelay = 24 * 60 * 60 // seconds

// maxReason bounds a verification's public reason.
const maxReason = 280

type verification struct {
	reason string
	since  int64 // unix seconds from which it counts
	by     address
}

var verified avl.Tree // asset class -> *verification

// seedVerified verifies GNOT and wrapped GNOT from the start.
func seedVerified() {
	verified.Set("coin:ugnot", &verification{reason: "The native coin of gno.land."})
	verified.Set("token:"+wugnotKey, &verification{reason: "GNOT wrapped one to one by gno.land/r/gnoland/wugnot, a realm with no admin."})
}

// Verify makes a coin denom, a registered GRC20 token or a registered NFT
// collection acceptable in ordinary rooms from VerifyDelay from now. kind
// is coin, token or nft; key is the denom, the registry key or the
// collection key. reason is public: say why this asset is safe to trade.
func Verify(cur realm, kind, key, reason string) {
	assertAdmin(cur)
	key = strings.TrimSpace(key)
	switch kind {
	case KindCoin:
		assertDenom(key)
	case KindToken:
		if grc20reg.Get(key) == nil {
			panic("token is not in the GRC20 registry")
		}
	case KindNFT:
		mustCollection(key)
	default:
		panic("kind must be coin, token or nft")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" || len(reason) > maxReason {
		panic("give a reason of 1 to " + strconv.Itoa(maxReason) + " bytes")
	}
	for _, r := range reason {
		if r < 0x20 || r == 0x7f {
			panic("the reason has a control character")
		}
	}
	since := time.Now().Unix() + VerifyDelay
	verified.Set(kind+":"+key, &verification{reason: reason, since: since, by: callerOf(cur)})
	chain.Emit("VerifyProposed",
		"kind", kind,
		"key", key,
		"since", strconv.FormatInt(since, 10),
		"reason", reason,
	)
}

// Unverify removes a verification at once. Ordinary rooms stop accepting
// the asset, and those that hold it can no longer settle; deposits stay
// withdrawable. reason is public.
func Unverify(cur realm, kind, key, reason string) {
	assertAdmin(cur)
	class := kind + ":" + strings.TrimSpace(key)
	if !verified.Has(class) {
		panic("that asset is not verified")
	}
	verified.Remove(class)
	chain.Emit("Unverified", "kind", kind, "key", strings.TrimSpace(key), "reason", strings.TrimSpace(reason))
}

// IsVerified reports whether an asset counts as verified now. denom is a
// coin denom, a registry key, or a collection key (with or without
// "#token id").
func IsVerified(kind, denom string) bool {
	return isVerified(kind, denom, time.Now().Unix())
}

func classOf(kind, denom string) string {
	if kind == KindNFT {
		key, _, _ := strings.Cut(denom, "#")
		return KindNFT + ":" + key
	}
	return kind + ":" + denom
}

func isVerified(kind, denom string, now int64) bool {
	v := verified.Get(classOf(kind, denom))
	return v != nil && now >= v.(*verification).since
}

// assertAccepts refuses an asset an ordinary room does not take.
func (r *room) assertAccepts(kind, denom string) {
	if r.openMarket || isVerified(kind, denom, time.Now().Unix()) {
		return
	}
	panic("this room takes only verified assets, and " + denom + " is not verified: trade it in an open-market room")
}

// assertStillVerified stops an ordinary room from settling when one of its
// assets has lost its verification since it went in.
func (r *room) assertStillVerified() {
	if r.openMarket {
		return
	}
	now := time.Now().Unix()
	for _, list := range [][]asset{r.maker.assets, r.taker.assets, r.want} {
		for _, a := range list {
			if !isVerified(a.kind, a.denom, now) {
				panic(a.denom + " is no longer verified, so this room cannot settle: take your items back")
			}
		}
	}
}

// VerifiedJSON lists verifications, counted or still waiting, with their
// public reasons.
func VerifiedJSON(offset, limit int) string {
	offset, limit = page(offset, limit)
	now := time.Now().Unix()
	items := []string{}
	verified.IterateByOffset(offset, limit, func(class string, v any) bool {
		kind, key, _ := strings.Cut(class, ":")
		ver := v.(*verification)
		items = append(items, jsonObject(
			"kind", jsonString(kind),
			"key", jsonString(key),
			"reason", jsonString(ver.reason),
			"since", jsonInt(ver.since),
			"active", jsonBool(now >= ver.since),
		))
		return false
	})
	return jsonObject(
		"assets", jsonArray(items),
		"more", jsonBool(offset+len(items) < verified.Size()),
		"now", jsonInt(now),
	)
}

// Package tavernboard is TavernBoard, a small community message board
// realm for Gno.land, built for the Gnome Tavern Hackathon.
//
// Anyone can post a short message on chain, and anyone can cheer
// (like) a message once. Messages are listed newest first by Render.
// There is no admin, no delete, and no edit: what is posted stays
// posted, which keeps the board simple, reliable, and auditable.
package tavernboard

import (
	"chain/runtime"
	"strconv"
	"strings"
)

// MaxMessageLen caps message size in bytes so one post cannot bloat
// chain state.
const MaxMessageLen = 280

// MaxMessagesShown caps how many messages Render lists at once, so
// the board page stays readable as the board grows.
const MaxMessagesShown = 50

// Message is one board entry. Author is the address that posted it,
// Height is the block height at posting time, and LikedBy records
// which addresses have cheered it (one cheer per address).
type Message struct {
	Author  address
	Text    string
	Height  int64
	Likes   int
	LikedBy map[address]bool
}

// messages holds every post in posting order. A message ID is its
// index in this slice: IDs start at 0 and never change.
var messages []Message

// PostMessage adds a message from the caller and returns its ID.
// It panics if the text is empty or longer than MaxMessageLen bytes.
func PostMessage(cur realm, text string) int {
	if !cur.IsCurrent() {
		panic("tavernboard: PostMessage must be called as a crossing function")
	}
	messages = append(messages, Message{
		Author:  cur.Previous().Address(),
		Text:    cleanText(text),
		Height:  runtime.ChainHeight(),
		Likes:   0,
		LikedBy: map[address]bool{},
	})
	return len(messages) - 1
}

// LikeMessage cheers a message. Each address can cheer a given
// message at most once. It returns the new cheer count and panics
// on an unknown ID or a repeat cheer.
func LikeMessage(cur realm, id int) int {
	if !cur.IsCurrent() {
		panic("tavernboard: LikeMessage must be called as a crossing function")
	}
	who := cur.Previous().Address()
	checkCanLike(id, who)
	messages[id].LikedBy[who] = true
	messages[id].Likes++
	return messages[id].Likes
}

// cleanText trims a candidate message and enforces the size rules.
// It panics on empty or over-long text. Kept separate from
// PostMessage so the rules can be unit tested without a crossing
// call (panics across a realm crossing cannot be recovered).
func cleanText(text string) string {
	text = strings.TrimSpace(text)
	if text == "" {
		panic("tavernboard: message is empty")
	}
	if len(text) > MaxMessageLen {
		panic("tavernboard: message is too long (max " + strconv.Itoa(MaxMessageLen) + " bytes)")
	}
	return text
}

// checkID panics unless id names an existing message.
func checkID(id int) {
	if id < 0 || id >= len(messages) {
		panic("tavernboard: no message with id " + strconv.Itoa(id))
	}
}

// checkCanLike panics unless who may cheer message id: the ID must
// exist and who must not have cheered it already.
func checkCanLike(id int, who address) {
	checkID(id)
	if messages[id].LikedBy[who] {
		panic("tavernboard: already cheered this message")
	}
}

// MessageCount returns how many messages have been posted.
func MessageCount() int {
	return len(messages)
}

// GetMessage returns one message as (author, text, height, likes).
// It panics on an unknown ID. Read-only, so queries can call it
// without a transaction.
func GetMessage(id int) (string, string, int64, int) {
	checkID(id)
	m := messages[id]
	return m.Author.String(), m.Text, m.Height, m.Likes
}

// HasLiked reports whether an address has cheered a message.
// It panics on an unknown ID.
func HasLiked(id int, who address) bool {
	checkID(id)
	return messages[id].LikedBy[who]
}

// Render returns the board as Markdown for gnoweb. The root path
// ("" or "/") lists the newest messages first. A path of the form
// "/<id>" shows a single message in full.
func Render(path string) string {
	if path != "" && path != "/" {
		return renderOne(path)
	}
	out := "# TavernBoard\n\n"
	out += "A community message board on Gno.land. Post a message, cheer the ones you like.\n\n"
	out += "Total messages: " + strconv.Itoa(len(messages)) + "\n"
	if len(messages) == 0 {
		out += "\nNo messages yet. Be the first to post.\n"
		return out
	}
	shown := len(messages)
	if shown > MaxMessagesShown {
		shown = MaxMessagesShown
	}
	for i := 0; i < shown; i++ {
		id := len(messages) - 1 - i
		out += "\n---\n\n" + renderEntry(id)
	}
	if len(messages) > shown {
		out += "\n---\n\nShowing the newest " + strconv.Itoa(shown) + " of " + strconv.Itoa(len(messages)) + " messages. Open a message by ID, for example /0, to see older posts.\n"
	}
	return out
}

// renderOne renders a single message for paths like "/3". Unknown
// paths return a friendly not-found page instead of panicking, so
// gnoweb never shows an error page for a bad link.
func renderOne(path string) string {
	idStr := strings.TrimPrefix(path, "/")
	id, err := strconv.Atoi(idStr)
	if err != nil || id < 0 || id >= len(messages) {
		return "# TavernBoard\n\nMessage not found. The board has " + strconv.Itoa(len(messages)) + " message(s), with IDs from 0 to " + strconv.Itoa(len(messages)-1) + ".\n"
	}
	return "# TavernBoard\n\n" + renderEntry(id)
}

// renderEntry formats one message as a Markdown section.
func renderEntry(id int) string {
	m := messages[id]
	out := "## Message #" + strconv.Itoa(id) + "\n\n"
	out += "- Author: `" + shortAddr(m.Author.String()) + "`\n"
	out += "- Block: " + strconv.FormatInt(m.Height, 10) + "\n"
	out += "- Cheers: " + strconv.Itoa(m.Likes) + "\n\n"
	out += escapeText(m.Text) + "\n"
	return out
}

// shortAddr trims a long g1 address for display, keeping the full
// address available through GetMessage for anyone who needs it.
func shortAddr(a string) string {
	if len(a) <= 16 {
		return a
	}
	return a[:8] + "..." + a[len(a)-4:]
}

// escapeText keeps user text on one line in the rendered page by
// folding newlines to spaces, so a post cannot break the layout.
func escapeText(s string) string {
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	return strings.TrimSpace(s)
}

package tavernboard

import (
	"strings"
	"testing"
)

// otherAuthor is a fixed second address used to seed messages from
// someone other than the test caller.
const otherAuthor = address("g1magld5ptgzaktqcexxq0pgq5lmdf0kz6re8hlv")

func resetBoard() {
	messages = nil
}

func mustPanic(t *testing.T, what string, fn func()) {
	t.Helper()
	defer func() {
		if recover() == nil {
			t.Fatalf("expected panic for %s, got none", what)
		}
	}()
	fn()
}

func TestPostMessage(cur realm, t *testing.T) {
	resetBoard()
	id := PostMessage(cross(cur), "  hello tavern  ")
	if id != 0 {
		t.Fatalf("first message id: got %d, want 0", id)
	}
	if MessageCount() != 1 {
		t.Fatalf("message count: got %d, want 1", MessageCount())
	}
	author, text, height, likes := GetMessage(0)
	// In tests the caller is the test realm itself, so the stored
	// author must be cur.Address(). On chain, a gnokey MsgCall makes
	// cur.Previous() the signing account instead.
	if author != cur.Address().String() {
		t.Fatalf("author: got %q, want caller %q", author, cur.Address().String())
	}
	if text != "hello tavern" {
		t.Fatalf("text should be trimmed: got %q", text)
	}
	if height < 0 {
		t.Fatalf("height should be non-negative: got %d", height)
	}
	if likes != 0 {
		t.Fatalf("likes: got %d, want 0", likes)
	}
	id2 := PostMessage(cross(cur), "second round")
	if id2 != 1 || MessageCount() != 2 {
		t.Fatalf("second post: id %d, count %d, want id 1 count 2", id2, MessageCount())
	}
}

func TestPostMessageRejectsBadText(cur realm, t *testing.T) {
	resetBoard()
	// Panics across a realm crossing abort the whole test run and
	// cannot be recovered, so the text rules are exercised through
	// the cleanText helper that PostMessage itself calls.
	mustPanic(t, "empty message", func() { cleanText("") })
	mustPanic(t, "blank message", func() { cleanText("   ") })
	tooLong := strings.Repeat("a", MaxMessageLen+1)
	mustPanic(t, "over-long message", func() { cleanText(tooLong) })
	if got := cleanText("  padded  "); got != "padded" {
		t.Fatalf("cleanText should trim: got %q", got)
	}
	exact := strings.Repeat("b", MaxMessageLen)
	if id := PostMessage(cross(cur), exact); id != 0 {
		t.Fatalf("max-length message should post with id 0, got %d", id)
	}
}

func TestLikeMessage(cur realm, t *testing.T) {
	resetBoard()
	PostMessage(cross(cur), "cheer me")
	who := cur.Address()
	if HasLiked(0, who) {
		t.Fatal("caller should not have liked before cheering")
	}
	n := LikeMessage(cross(cur), 0)
	if n != 1 {
		t.Fatalf("like count after first cheer: got %d, want 1", n)
	}
	if !HasLiked(0, who) {
		t.Fatal("caller should have liked after cheering")
	}
	_, _, _, likes := GetMessage(0)
	if likes != 1 {
		t.Fatalf("stored likes: got %d, want 1", likes)
	}
	// Repeat-cheer rejection is checked through checkCanLike, the
	// same guard LikeMessage runs before recording a cheer.
	mustPanic(t, "repeat cheer by same address", func() { checkCanLike(0, who) })
}

func TestLikeMessageOtherAuthor(cur realm, t *testing.T) {
	resetBoard()
	// Seed a message from a different author, then cheer it as the
	// test caller. This proves cheers are tracked per address.
	messages = append(messages, Message{
		Author:  otherAuthor,
		Text:    "posted by someone else",
		Height:  42,
		Likes:   0,
		LikedBy: map[address]bool{},
	})
	if HasLiked(0, otherAuthor) {
		t.Fatal("author should not count as having cheered their own post")
	}
	if n := LikeMessage(cross(cur), 0); n != 1 {
		t.Fatalf("cheering another author's post: got %d, want 1", n)
	}
	author, _, height, _ := GetMessage(0)
	if author != otherAuthor.String() || height != 42 {
		t.Fatalf("seeded fields changed: author %q height %d", author, height)
	}
}

func TestBadIDs(cur realm, t *testing.T) {
	resetBoard()
	PostMessage(cross(cur), "only post")
	// ID guards run inside LikeMessage, GetMessage, and HasLiked;
	// they are exercised here through checkID and checkCanLike
	// because crossing-call panics cannot be recovered in tests.
	mustPanic(t, "unknown id", func() { checkID(7) })
	mustPanic(t, "negative id", func() { checkID(-1) })
	mustPanic(t, "like unknown id", func() { checkCanLike(7, otherAuthor) })
	mustPanic(t, "get unknown id", func() { GetMessage(7) })
	mustPanic(t, "hasliked unknown id", func() { HasLiked(7, otherAuthor) })
}

func TestRender(cur realm, t *testing.T) {
	resetBoard()
	empty := Render("")
	if !strings.Contains(empty, "Total messages: 0") || !strings.Contains(empty, "No messages yet") {
		t.Fatalf("empty render missing expected text:\n%s", empty)
	}
	PostMessage(cross(cur), "first post here")
	PostMessage(cross(cur), "second post here")
	LikeMessage(cross(cur), 1)
	board := Render("")
	if !strings.Contains(board, "# TavernBoard") || !strings.Contains(board, "Total messages: 2") {
		t.Fatalf("board render missing header or count:\n%s", board)
	}
	// Newest first: the second post must appear before the first.
	iSecond := strings.Index(board, "second post here")
	iFirst := strings.Index(board, "first post here")
	if iSecond < 0 || iFirst < 0 || iSecond > iFirst {
		t.Fatalf("board should list newest first:\n%s", board)
	}
	if !strings.Contains(board, "Cheers: 1") {
		t.Fatalf("board should show the cheer count:\n%s", board)
	}
	one := Render("/0")
	if !strings.Contains(one, "first post here") || strings.Contains(one, "second post here") {
		t.Fatalf("single render should show only message 0:\n%s", one)
	}
	missing := Render("/99")
	if !strings.Contains(missing, "Message not found") {
		t.Fatalf("unknown id should render not-found text:\n%s", missing)
	}
	garbage := Render("/hello")
	if !strings.Contains(garbage, "Message not found") {
		t.Fatalf("non-numeric path should render not-found text:\n%s", garbage)
	}
}

package aevumflow

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"time"
)

// AevumFlow — trustless invoice escrow for Gno.land.
//
// Lifecycle:
//   1. Issuer calls CreateInvoice(amount, memo, deliverInSec)  -> StatusCreated
//   2. Payer calls Fund(id) attaching exactly `amount` ugnot    -> StatusFunded
//      (coins land in the realm balance via the tx `send` envelope)
//   3. After delivery, Settle(id) releases escrow to the issuer
//      minus a protocol fee (feeBps basis points)               -> StatusSettled
//   4. If the issuer never delivers, anyone may Refund(id)
//      after deliverBy and the payer gets everything back       -> StatusRefunded
//
// Every state transition is enforced on-chain; the escrowed coins can
// only leave the realm through Settle or Refund.

const (
	StatusCreated uint8 = iota
	StatusFunded
	StatusSettled
	StatusRefunded
)

const (
	FeeBps    int64 = 100 // 1% protocol fee, taken at settlement
	MaxMemoLn int   = 140
)

var (
	invoices []*Invoice // id -> invoice (ids are dense, 1-based)
	nextID   uint64
)

type Invoice struct {
	ID        uint64
	Issuer    address
	Payer     address
	Amount    int64     // ugnot attached to Fund()
	Memo      string
	CreatedAt time.Time // block timestamp at creation
	DeliverBy time.Time // refundable after this
	Status    uint8
}

// --- lifecycle ---------------------------------------------------------

// CreateInvoice opens a new invoice. The caller becomes the issuer.
// deliverInSec is how long the payer has before the escrow becomes refundable.
func CreateInvoice(cur realm, amount int64, memo string, deliverInSec int64) uint64 {
	if amount <= 0 {
		panic("amount must be > 0")
	}
	if len(memo) > MaxMemoLn {
		panic("memo too long")
	}
	if deliverInSec <= 0 {
		panic("deliverInSec must be > 0")
	}
	issuer := cur.Previous().Address()
	now := time.Now()
	nextID++
	inv := &Invoice{
		ID:        nextID,
		Issuer:    issuer,
		Amount:    amount,
		Memo:      memo,
		CreatedAt: now,
		DeliverBy: now.Add(time.Duration(deliverInSec) * time.Second),
		Status:    StatusCreated,
	}
	invoices = append(invoices, inv)
	return inv.ID
}

// Fund escrows the payment. The caller must attach exactly inv.Amount ugnot
// through the transaction's send envelope.
func Fund(cur realm, id uint64) {
	inv := mustGet(id)
	if inv.Status != StatusCreated {
		panic("invoice not open for funding")
	}
	if !time.Now().Before(inv.DeliverBy) {
		panic("invoice expired")
	}
	if !cur.Previous().IsUserCall() {
		panic("only user-call accepted")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != inv.Amount {
		panic("must attach exactly " + i64str(inv.Amount) + "ugnot")
	}
	inv.Payer = cur.Previous().Address()
	inv.Status = StatusFunded
}

// Settle releases the escrow to the issuer. Allowed once the invoice is
// Funded; before deliverBy only the issuer may settle, after deliverBy
// anyone may finalize (trustless completion).
func Settle(cur realm, id uint64) {
	inv := mustGet(id)
	if inv.Status != StatusFunded {
		panic("invoice is not funded")
	}
	caller := cur.Previous().Address()
	now := time.Now()
	if now.Before(inv.DeliverBy) && caller != inv.Issuer {
		panic("only the issuer can settle before the deadline")
	}
	fee := inv.Amount * FeeBps / 10000
	payout := inv.Amount - fee
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := cur.Address()
	b.SendCoins(realmAddr, inv.Issuer, chain.Coins{chain.NewCoin("ugnot", payout)})
	inv.Status = StatusSettled
}

// Refund returns the escrowed coins to the payer. Only callable after
// deliverBy on a funded, unsettled invoice.
func Refund(cur realm, id uint64) {
	inv := mustGet(id)
	if inv.Status != StatusFunded {
		panic("invoice is not funded")
	}
	if time.Now().Before(inv.DeliverBy) {
		panic("deadline not reached")
	}
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), inv.Payer, chain.Coins{chain.NewCoin("ugnot", inv.Amount)})
	inv.Status = StatusRefunded
}

// --- views -------------------------------------------------------------

func GetInvoice(id uint64) *Invoice {
	return mustGet(id)
}

func InvoiceCount() uint64 {
	return nextID
}

// FeeFor returns the protocol fee (in ugnot) that would be taken when
// settling an invoice of `amount`.
func FeeFor(amount int64) int64 {
	return amount * FeeBps / 10000
}

// --- render ------------------------------------------------------------

func statusName(s uint8) string {
	switch s {
	case StatusCreated:
		return "Created"
	case StatusFunded:
		return "Funded"
	case StatusSettled:
		return "Settled"
	case StatusRefunded:
		return "Refunded"
	}
	return "?"
}

func Render(path string) string {
	out := "# AevumFlow — invoice escrow\n\n"
	out += "Trustless invoice escrow: issuer creates, payer funds with an attached ugnot send, settle releases to the issuer (1% fee), refund returns escrow after the deadline.\n\n"
	out += "| id | amount | status | memo |\n|---|---|---|---|\n"
	for _, inv := range invoices {
		out += "| " + u64str(inv.ID) + " | " + i64str(inv.Amount) + "ugnot | " + statusName(inv.Status) + " | " + memoCell(inv.Memo) + " |\n"
	}
	if len(invoices) == 0 {
		out += "(no invoices yet)\n"
	}
	if path != "" {
		out += "\n(detailed view not implemented for path: " + path + ")\n"
	}
	return out
}

// --- helpers -----------------------------------------------------------

func mustGet(id uint64) *Invoice {
	if id == 0 || id > nextID {
		panic("invoice not found")
	}
	return invoices[id-1]
}

func memoCell(m string) string {
	// escape pipe chars for the markdown table
	out := make([]rune, 0, len(m))
	for _, r := range m {
		if r == '|' {
			out = append(out, '/')
		} else {
			out = append(out, r)
		}
	}
	return string(out)
}

func u64str(v uint64) string {
	if v == 0 {
		return "0"
	}
	var buf [20]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}

func i64str(v int64) string {
	if v == 0 {
		return "0"
	}
	if v < 0 {
		return "-" + u64str(uint64(-v))
	}
	return u64str(uint64(v))
}

