// Package strongbox is a multisig team treasury for gno.land.
//
// A team creates a vault with a list of signers and a threshold (for
// example 2-of-3). Anyone can fund the vault with GNOT. Any signer can
// propose a payout; once enough signers approve, the payout is sent
// automatically. Everything is visible on the realm's gnoweb page.
//
// All vaults share the realm's bank account; each vault's share is tracked
// in Vault.Balance. Coins sent to the realm address without Deposit belong
// to no vault and cannot be paid out.
package strongbox

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	Denom      = "ugnot"
	MaxSigners = 20
	MaxNameLen = 64
	MaxMemoLen = 280
	// MaxOpenPerProposer caps the pending proposals one signer can have in
	// a vault, so a hostile signer cannot flood it.
	MaxOpenPerProposer = 20
)

type Status int

const (
	StatusPending Status = iota
	StatusExecuted
	StatusCancelled
)

func (s Status) String() string {
	switch s {
	case StatusPending:
		return "pending"
	case StatusExecuted:
		return "paid"
	case StatusCancelled:
		return "cancelled"
	}
	return "unknown"
}

type Proposal struct {
	ID        int
	Proposer  address
	To        address
	Amount    int64
	Memo      string
	Approvals []address
	Status    Status
	CreatedAt int64 // block height
	ClosedAt  int64 // block height, 0 while pending
}

type Inflow struct {
	From   address
	Amount int64
	Height int64
}

type Vault struct {
	ID        int
	Name      string
	Creator   address
	Signers   []address
	Threshold int
	Balance   int64
	// History lives in AVL trees, not slices: a call then touches a few
	// tree nodes instead of rewriting the whole history, so its cost stays
	// flat however long the vault is used. With slices, a hostile signer
	// could grow the history until no transaction fits in the gas limit,
	// locking the funds.
	Proposals     *avl.Tree // padded proposal id -> *Proposal
	ProposalCount int
	Pending       []int     // ids of pending proposals, oldest first (bounded)
	OpenBy        *avl.Tree // proposer address -> number of pending proposals
	PaidTotal     int64     // ugnot paid out so far
	Inflows       *avl.Tree // padded sequence -> Inflow
	InflowCount   int
	CreatedAt     int64
}

var (
	vaults      = avl.NewTree() // padded vault id -> *Vault
	bySigner    = avl.NewTree() // signer address + "/" + padded vault id -> true
	signerCount = avl.NewTree() // signer address -> number of vaults
	nextID      = 1
	pkgPath     string
)

func init(cur realm) {
	pkgPath = cur.PkgPath()
}

// ---------------------------------------------------------------------------
// Transactions

// CreateVault creates a vault. signers is a comma-separated list of
// addresses; the caller is always added as a signer. threshold is the
// number of approvals a payout needs. Returns the new vault id.
func CreateVault(cur realm, name string, signers string, threshold int) int {
	caller := cur.Previous().Address()
	assertNoCoins(cur)

	name = strings.TrimSpace(name)
	require(name != "", "name is required")
	require(len(name) <= MaxNameLen, "name is too long (max "+strconv.Itoa(MaxNameLen)+" bytes)")
	require(isCleanText(name), "name contains control or invisible characters")

	list := []address{caller}
	for _, raw := range strings.Split(signers, ",") {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		addr := normalize(address(raw))
		require(addr.IsValid(), "invalid signer address: "+raw)
		// The realm can never approve anything, so as a signer it would only
		// make the threshold harder or impossible to reach.
		require(addr != cur.Address(), "the Strongbox realm cannot be a signer")
		if !contains(list, addr) {
			list = append(list, addr)
		}
		require(len(list) <= MaxSigners, "too many signers (max "+strconv.Itoa(MaxSigners)+")")
	}
	require(threshold >= 1, "threshold must be at least 1")
	require(threshold <= len(list), "threshold ("+strconv.Itoa(threshold)+") is higher than the number of signers ("+strconv.Itoa(len(list))+")")

	id := nextID
	nextID++
	v := &Vault{
		ID:        id,
		Name:      name,
		Creator:   caller,
		Signers:   list,
		Threshold: threshold,
		Proposals: avl.NewTree(),
		OpenBy:    avl.NewTree(),
		Inflows:   avl.NewTree(),
		CreatedAt: runtime.ChainHeight(),
	}
	vaults.Set(key(id), v)
	for _, s := range list {
		bySigner.Set(s.String()+"/"+key(id), true)
		n, _ := signerCount.Get(s.String()).(int)
		signerCount.Set(s.String(), n+1)
	}

	chain.Emit("VaultCreated", "id", strconv.Itoa(id), "threshold", strconv.Itoa(threshold), "signers", strconv.Itoa(len(list)))
	return id
}

// Deposit adds the ugnot sent with this call to the vault. Anyone can
// deposit. It must be called directly (gnokey maketx call -send ...).
func Deposit(cur realm, vaultID int) {
	// Only a direct user call: a realm in between could otherwise call
	// Deposit several times and count the same sent coins more than once.
	require(cur.Previous().IsUserCall(), "Deposit must be called directly with gnokey maketx call -send")
	v := mustVault(vaultID)

	sent := unsafe.OriginSend()
	require(len(sent) > 0, "send ugnot with the call (-send 1000000ugnot)")
	for _, c := range sent {
		require(c.Denom == Denom, "only "+Denom+" can be deposited")
	}
	amount := sent.AmountOf(Denom)
	require(amount > 0, "deposit amount must be positive")

	v.Balance += amount
	v.InflowCount++
	v.Inflows.Set(key(v.InflowCount), Inflow{
		From:   cur.Previous().Address(),
		Amount: amount,
		Height: runtime.ChainHeight(),
	})
	chain.Emit("Deposit", "vault", strconv.Itoa(vaultID), "amount", strconv.FormatInt(amount, 10))
}

// Propose creates a payout proposal. Only signers can propose; the
// proposer's approval is counted. If the threshold is 1 and the vault has
// enough funds, the payout is sent at once. Returns the proposal id.
func Propose(cur realm, vaultID int, to address, amount int64, memo string) int {
	caller := cur.Previous().Address()
	assertNoCoins(cur)
	v := mustVault(vaultID)
	mustSigner(v, caller)

	to = normalize(to)
	require(to.IsValid(), "invalid recipient address")
	// Paying the realm itself would take coins out of the vault's balance
	// while leaving them in the realm, owned by no vault.
	require(to != cur.Address(), "cannot pay out to the Strongbox realm itself")
	require(amount > 0, "amount must be positive")
	memo = strings.TrimSpace(memo)
	require(len(memo) <= MaxMemoLen, "memo is too long (max "+strconv.Itoa(MaxMemoLen)+" bytes)")
	require(isCleanText(memo), "memo contains control or invisible characters")
	open, _ := v.OpenBy.Get(caller.String()).(int)
	require(open < MaxOpenPerProposer, "you already have "+strconv.Itoa(MaxOpenPerProposer)+" open proposals in this vault; cancel or finish some first")

	p := &Proposal{
		ID:        v.ProposalCount + 1,
		Proposer:  caller,
		To:        to,
		Amount:    amount,
		Memo:      memo,
		Approvals: []address{caller},
		Status:    StatusPending,
		CreatedAt: runtime.ChainHeight(),
	}
	v.ProposalCount++
	v.Proposals.Set(key(p.ID), p)
	v.Pending = append(v.Pending, p.ID)
	v.OpenBy.Set(caller.String(), open+1)
	chain.Emit("Proposed", "vault", strconv.Itoa(vaultID), "proposal", strconv.Itoa(p.ID), "amount", strconv.FormatInt(amount, 10))

	tryExecute(cur, v, p)
	return p.ID
}

// Approve adds the caller's approval. When the threshold is reached and
// the vault holds enough funds, the payout is sent in the same call.
func Approve(cur realm, vaultID int, proposalID int) {
	caller := cur.Previous().Address()
	assertNoCoins(cur)
	v := mustVault(vaultID)
	mustSigner(v, caller)
	p := mustPending(v, proposalID)
	require(!contains(p.Approvals, caller), "you already approved this proposal")

	p.Approvals = append(p.Approvals, caller)
	chain.Emit("Approved", "vault", strconv.Itoa(vaultID), "proposal", strconv.Itoa(proposalID), "approvals", strconv.Itoa(len(p.Approvals)))

	tryExecute(cur, v, p)
}

// Revoke withdraws the caller's approval of a pending proposal.
func Revoke(cur realm, vaultID int, proposalID int) {
	caller := cur.Previous().Address()
	assertNoCoins(cur)
	v := mustVault(vaultID)
	mustSigner(v, caller)
	p := mustPending(v, proposalID)

	idx := indexOf(p.Approvals, caller)
	require(idx >= 0, "you have not approved this proposal")
	kept := make([]address, 0, len(p.Approvals)-1)
	for i, a := range p.Approvals {
		if i != idx {
			kept = append(kept, a)
		}
	}
	p.Approvals = kept
	chain.Emit("Revoked", "vault", strconv.Itoa(vaultID), "proposal", strconv.Itoa(proposalID))
}

// Execute sends an approved payout that could not be sent earlier, for
// example because the vault was short of funds when the last approval
// came in. Any signer can call it.
func Execute(cur realm, vaultID int, proposalID int) {
	caller := cur.Previous().Address()
	assertNoCoins(cur)
	v := mustVault(vaultID)
	mustSigner(v, caller)
	p := mustPending(v, proposalID)

	require(len(p.Approvals) >= v.Threshold, "not enough approvals: "+strconv.Itoa(len(p.Approvals))+"/"+strconv.Itoa(v.Threshold))
	require(v.Balance >= p.Amount, "vault balance too low: has "+formatGNOT(v.Balance)+", needs "+formatGNOT(p.Amount))
	pay(cur, v, p)
}

// Cancel closes a pending proposal. Only its proposer can cancel it.
func Cancel(cur realm, vaultID int, proposalID int) {
	caller := cur.Previous().Address()
	assertNoCoins(cur)
	v := mustVault(vaultID)
	p := mustPending(v, proposalID)
	require(p.Proposer == caller, "only the proposer can cancel this proposal")

	p.Status = StatusCancelled
	p.ClosedAt = runtime.ChainHeight()
	closePending(v, p)
	chain.Emit("Cancelled", "vault", strconv.Itoa(vaultID), "proposal", strconv.Itoa(proposalID))
}

// ---------------------------------------------------------------------------
// Read-only helpers, for other realms and scripts

func VaultBalance(vaultID int) int64 { return mustVault(vaultID).Balance }

func VaultThreshold(vaultID int) int { return mustVault(vaultID).Threshold }

func IsSigner(vaultID int, addr address) bool {
	return contains(mustVault(vaultID).Signers, normalize(addr))
}

func VaultCount() int { return nextID - 1 }

// ---------------------------------------------------------------------------
// Internals

func tryExecute(cur realm, v *Vault, p *Proposal) {
	if len(p.Approvals) >= v.Threshold && v.Balance >= p.Amount {
		pay(cur, v, p)
	}
}

func pay(cur realm, v *Vault, p *Proposal) {
	// Update state before moving coins.
	v.Balance -= p.Amount
	v.PaidTotal += p.Amount
	p.Status = StatusExecuted
	p.ClosedAt = runtime.ChainHeight()
	closePending(v, p)

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), p.To, chain.Coins{{Denom, p.Amount}})
	chain.Emit("Paid", "vault", strconv.Itoa(v.ID), "proposal", strconv.Itoa(p.ID), "to", p.To.String(), "amount", strconv.FormatInt(p.Amount, 10))
}

// closePending drops a proposal that was just paid or cancelled from the
// pending list and from its proposer's open count.
func closePending(v *Vault, p *Proposal) {
	kept := make([]int, 0, len(v.Pending))
	for _, pid := range v.Pending {
		if pid != p.ID {
			kept = append(kept, pid)
		}
	}
	v.Pending = kept
	open, _ := v.OpenBy.Get(p.Proposer.String()).(int)
	if open <= 1 {
		v.OpenBy.Remove(p.Proposer.String())
	} else {
		v.OpenBy.Set(p.Proposer.String(), open-1)
	}
}

// isCleanText refuses control characters and invisible or
// direction-changing characters, which could make a name or memo display
// as something other than what it is.
func isCleanText(s string) bool {
	for _, r := range s {
		switch {
		case r < 0x20, r == 0x7f, r >= 0x80 && r <= 0x9f:
			return false
		case r >= 0x200b && r <= 0x200f, // zero-width, LRM/RLM
			r >= 0x202a && r <= 0x202e, // bidi embeddings and overrides
			r >= 0x2060 && r <= 0x206f, // word joiner, bidi isolates
			r == 0xfeff, r == 0x00ad,   // BOM, soft hyphen
			r == 0xfffd: // replacement char (invalid UTF-8)
			return false
		}
	}
	return true
}

// assertNoCoins refuses coins sent with any call but Deposit: they would
// land in the realm without belonging to a vault, and be lost. Panicking
// reverts the transaction, so the sender keeps them.
func assertNoCoins(cur realm) {
	if cur.Previous().IsUserCall() {
		require(len(unsafe.OriginSend()) == 0, "do not send coins with this call; use Deposit to fund a vault")
	}
}

// normalize lowercases an address. Bech32 accepts an all-uppercase form
// too, but callers always arrive lowercase: an uppercase signer would never
// match its owner, and could make a vault's threshold unreachable.
func normalize(a address) address {
	return address(strings.ToLower(a.String()))
}

func getProposal(v *Vault, id int) *Proposal {
	return v.Proposals.Get(key(id)).(*Proposal)
}

func getVault(id int) (*Vault, bool) {
	if id < 1 || id >= nextID {
		return nil, false
	}
	v, ok := vaults.Get(key(id)).(*Vault)
	return v, ok
}

func mustVault(id int) *Vault {
	v, ok := getVault(id)
	require(ok, "vault "+strconv.Itoa(id)+" not found")
	return v
}

func mustSigner(v *Vault, addr address) {
	require(contains(v.Signers, addr), "only signers of this vault can do this")
}

func mustPending(v *Vault, proposalID int) *Proposal {
	require(proposalID >= 1 && proposalID <= v.ProposalCount, "proposal "+strconv.Itoa(proposalID)+" not found")
	p := getProposal(v, proposalID)
	require(p.Status == StatusPending, "proposal is already "+p.Status.String())
	return p
}

func key(id int) string {
	s := strconv.Itoa(id)
	return strings.Repeat("0", 10-len(s)) + s
}

func contains(list []address, a address) bool { return indexOf(list, a) >= 0 }

func indexOf(list []address, a address) int {
	for i, x := range list {
		if x == a {
			return i
		}
	}
	return -1
}

func require(cond bool, msg string) {
	if !cond {
		panic(msg)
	}
}

package strongbox

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
	dave  = testutils.TestAddress("dave") // not a signer
	payee = testutils.TestAddress("payee")
)

// fund deposits ugnot into a vault as addr, mirroring a real
// `gnokey maketx call -send`: the coins land in the realm account.
func fund(cur realm, addr address, vaultID int, amount int64) {
	testing.SetRealm(testing.NewUserRealm(addr))
	coins := chain.Coins{{Denom, amount}}
	testing.SetOriginSend(coins)
	testing.IssueCoins(chain.PackageAddress("gno.land/r/g1sjzvhjx4u4cnd92yk5g0jv68j3j302f4fwzd0z/strongbox/v1"), coins)
	Deposit(cross(cur), vaultID)
	testing.SetOriginSend(nil)
}

func balanceOf(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoins(addr).AmountOf(Denom)
}

func signers(addrs ...address) string {
	s := []string{}
	for _, a := range addrs {
		s = append(s, a.String())
	}
	return strings.Join(s, ",")
}

func TestCreateVault(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Team Tavern", signers(bob, carol, bob), 2)

	v := mustVault(id)
	uassert.Equal(t, "Team Tavern", v.Name)
	uassert.Equal(t, 3, len(v.Signers)) // alice added, duplicate bob dropped
	uassert.True(t, IsSigner(id, alice))
	uassert.True(t, IsSigner(id, bob))
	uassert.False(t, IsSigner(id, dave))
	uassert.Equal(t, 2, VaultThreshold(id))

	uassert.AbortsWithMessage(t, cur, "threshold (4) is higher than the number of signers (3)", func() {
		CreateVault(cross(cur), "x", signers(bob, carol), 4)
	})
	uassert.AbortsWithMessage(t, cur, "threshold must be at least 1", func() {
		CreateVault(cross(cur), "x", "", 0)
	})
	uassert.AbortsWithMessage(t, cur, "invalid signer address: nope", func() {
		CreateVault(cross(cur), "x", "nope", 1)
	})
	uassert.AbortsWithMessage(t, cur, "name is required", func() {
		CreateVault(cross(cur), "  ", "", 1)
	})
}

func TestTwoOfThreePayout(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Prize pot", signers(bob, carol), 2)
	fund(cur, dave, id, 10_000_000) // anyone can deposit
	uassert.Equal(t, int64(10_000_000), VaultBalance(id))

	// A non-signer cannot propose.
	testing.SetRealm(testing.NewUserRealm(dave))
	uassert.AbortsWithMessage(t, cur, "only signers of this vault can do this", func() {
		Propose(cross(cur), id, dave, 1, "gimme")
	})

	// Alice proposes: 1/2 approvals, nothing sent yet.
	testing.SetRealm(testing.NewUserRealm(alice))
	pid := Propose(cross(cur), id, payee, 4_000_000, "Design work")
	uassert.Equal(t, 1, pid)
	uassert.Equal(t, int64(0), balanceOf(payee))
	uassert.AbortsWithMessage(t, cur, "you already approved this proposal", func() {
		Approve(cross(cur), id, pid)
	})
	uassert.AbortsWithMessage(t, cur, "not enough approvals: 1/2", func() {
		Execute(cross(cur), id, pid)
	})

	// Bob approves: threshold reached, payout sent automatically.
	testing.SetRealm(testing.NewUserRealm(bob))
	Approve(cross(cur), id, pid)
	uassert.Equal(t, int64(4_000_000), balanceOf(payee))
	uassert.Equal(t, int64(6_000_000), VaultBalance(id))

	v := mustVault(id)
	uassert.Equal(t, "paid", getProposal(v, 1).Status.String())

	// Closed proposals cannot be approved again.
	testing.SetRealm(testing.NewUserRealm(carol))
	uassert.AbortsWithMessage(t, cur, "proposal is already paid", func() {
		Approve(cross(cur), id, pid)
	})
}

func TestShortOfFundsThenExecute(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Small pot", signers(bob), 2)
	fund(cur, alice, id, 1_000_000)

	pid := Propose(cross(cur), id, payee, 3_000_000, "")
	testing.SetRealm(testing.NewUserRealm(bob))
	Approve(cross(cur), id, pid) // approved, but vault is short: stays pending
	uassert.Equal(t, "pending", getProposal(mustVault(id), 1).Status.String())
	uassert.AbortsWithMessage(t, cur, "vault balance too low: has 1 GNOT, needs 3 GNOT", func() {
		Execute(cross(cur), id, pid)
	})

	before := balanceOf(payee)
	fund(cur, carol, id, 2_000_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Execute(cross(cur), id, pid)
	uassert.Equal(t, before+3_000_000, balanceOf(payee))
	uassert.Equal(t, int64(0), VaultBalance(id))
}

func TestRevokeAndCancel(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Ops", signers(bob, carol), 3)
	fund(cur, alice, id, 5_000_000)

	pid := Propose(cross(cur), id, payee, 1_000_000, "servers")
	testing.SetRealm(testing.NewUserRealm(bob))
	Approve(cross(cur), id, pid)
	Revoke(cross(cur), id, pid)
	uassert.Equal(t, 1, len(getProposal(mustVault(id), 1).Approvals))
	uassert.AbortsWithMessage(t, cur, "you have not approved this proposal", func() {
		Revoke(cross(cur), id, pid)
	})
	uassert.AbortsWithMessage(t, cur, "only the proposer can cancel this proposal", func() {
		Cancel(cross(cur), id, pid)
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	Cancel(cross(cur), id, pid)
	uassert.Equal(t, "cancelled", getProposal(mustVault(id), 1).Status.String())
	uassert.Equal(t, int64(5_000_000), VaultBalance(id)) // nothing moved
}

func TestDepositRules(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Deposits", "", 1)

	uassert.AbortsWithMessage(t, cur, "send ugnot with the call (-send 1000000ugnot)", func() {
		Deposit(cross(cur), id)
	})

	testing.SetOriginSend(chain.Coins{{"uatom", 5}})
	uassert.AbortsWithMessage(t, cur, "only ugnot can be deposited", func() {
		Deposit(cross(cur), id)
	})
	testing.SetOriginSend(nil)

	uassert.AbortsWithMessage(t, cur, "vault 999 not found", func() {
		Deposit(cross(cur), 999)
	})
}

func TestOneOfOneSendsImmediately(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Solo", "", 1)
	fund(cur, alice, id, 2_000_000)
	before := balanceOf(payee)

	testing.SetRealm(testing.NewUserRealm(alice))
	Propose(cross(cur), id, payee, 500_000, "")
	uassert.Equal(t, before+500_000, balanceOf(payee))
	uassert.Equal(t, int64(1_500_000), VaultBalance(id))
}

func TestRender(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(alice))
	id := CreateVault(cross(cur), "Render *me* [x](y)", signers(bob), 2)
	fund(cur, alice, id, 2_500_000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Propose(cross(cur), id, payee, 1_000_000, "pay | the bard")

	home := Render("")
	uassert.True(t, strings.Contains(home, "# Strongbox"))
	uassert.True(t, strings.Contains(home, `Render \*me\* \[x\]\(y\)`), "name must be escaped")

	page := Render("vault/" + itoa(id))
	uassert.True(t, strings.Contains(page, "**Balance: 2.5 GNOT**"))
	uassert.True(t, strings.Contains(page, "**2 of 2**"))
	uassert.True(t, strings.Contains(page, "Approvals: **1/2**"))
	uassert.True(t, strings.Contains(page, `pay \| the bard`))

	mine := Render("signer/" + bob.String())
	uassert.True(t, strings.Contains(mine, "1 waiting for your approval"))

	uassert.True(t, strings.Contains(Render("vault/12345"), "There is no vault 12345"))
	uassert.True(t, strings.Contains(Render("nope"), "# Not found"))
}

func TestFormatGNOT(t *testing.T) {
	uassert.Equal(t, "0 GNOT", formatGNOT(0))
	uassert.Equal(t, "1 GNOT", formatGNOT(1_000_000))
	uassert.Equal(t, "1.5 GNOT", formatGNOT(1_500_000))
	uassert.Equal(t, "0.000001 GNOT", formatGNOT(1))
	uassert.Equal(t, "12.03 GNOT", formatGNOT(12_030_000))
}

func itoa(i int) string {
	return strings.TrimLeft(key(i), "0")
}

// Package board is the public OTC board of Trade Window.
//
// A listing says what its owner gives and what they want, in their own
// words. It holds no assets and promises nothing: a deal happens only when
// both parties open a room in gno.land/r/tradewindow/rooms (or wherever that
// realm is deployed) and lock the same version of it. Contact details never
// belong here; everything in this realm is public forever.
package board

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
)

const (
	SideBuy  = "buy"
	SideSell = "sell"
	SideSwap = "swap"

	MaxGiveLen = 80
	MaxWantLen = 80
	MaxNoteLen = 280

	DefaultDays = 7
	MaxDays     = 30

	// MaxActivePerOwner caps open listings per address.
	MaxActivePerOwner = 10

	day = 24 * 60 * 60
)

type listing struct {
	id        uint64
	owner     address
	side      string
	give      string
	want      string
	note      string
	createdAt int64 // unix seconds of block time
	expiresAt int64
	closedAt  int64 // 0 while open
}

var (
	listings avl.Tree // padded id -> *listing
	byOwner  avl.Tree // address -> []uint64 listing ids, oldest first
	lastID   uint64
)

// Post publishes a listing and returns its id. side is buy, sell or swap;
// give and want are short phrases such as "50,000 GNOT"; note is optional.
// days is how long the listing stays up: 0 means 7, the most is 30.
func Post(cur realm, side, give, want, note string, days int) uint64 {
	owner := callerOf(cur)
	refuseCoins(cur)

	side = strings.TrimSpace(side)
	if side != SideBuy && side != SideSell && side != SideSwap {
		panic("side must be buy, sell or swap")
	}
	give = cleanText("give", give, MaxGiveLen, true)
	want = cleanText("want", want, MaxWantLen, true)
	note = cleanText("note", note, MaxNoteLen, false)
	if days == 0 {
		days = DefaultDays
	}
	if days < 1 || days > MaxDays {
		panic("a listing stays up between 1 and 30 days")
	}

	now := time.Now().Unix()
	if activeCount(owner, now) >= MaxActivePerOwner {
		panic("you already have 10 open listings: close one first")
	}

	lastID++
	l := &listing{
		id:        lastID,
		owner:     owner,
		side:      side,
		give:      give,
		want:      want,
		note:      note,
		createdAt: now,
		expiresAt: now + int64(days)*day,
	}
	listings.Set(listingKey(l.id), l)
	var ids []uint64
	if v := byOwner.Get(owner.String()); v != nil {
		ids = v.([]uint64)
	}
	byOwner.Set(owner.String(), append(ids, l.id))

	chain.Emit("ListingPosted",
		"id", strconv.FormatUint(l.id, 10),
		"owner", owner.String(),
		"side", side,
	)
	return l.id
}

// Close takes a listing down. Only its owner can close it.
func Close(cur realm, id uint64) {
	who := callerOf(cur)
	refuseCoins(cur)
	l := mustListing(id)
	if l.owner != who {
		panic("only the owner can close this listing")
	}
	if l.closedAt != 0 {
		panic("this listing is already closed")
	}
	l.closedAt = time.Now().Unix()
	chain.Emit("ListingClosed", "id", strconv.FormatUint(id, 10))
}

func (l *listing) open(now int64) bool {
	return l.closedAt == 0 && now < l.expiresAt
}

// activeCount counts the owner's open listings. Listings older than
// MaxDays cannot be open, so the walk stops there.
func activeCount(owner address, now int64) int {
	v := byOwner.Get(owner.String())
	if v == nil {
		return 0
	}
	ids := v.([]uint64)
	oldest := now - MaxDays*day
	n := 0
	for i := len(ids) - 1; i >= 0 && n < MaxActivePerOwner; i-- {
		l := mustListing(ids[i])
		if l.createdAt < oldest {
			break
		}
		if l.open(now) {
			n++
		}
	}
	return n
}

// cleanText trims s and rejects text that is too long or carries control,
// bidi or zero-width characters.
func cleanText(field, s string, max int, required bool) string {
	s = strings.TrimSpace(s)
	if required && s == "" {
		panic(field + " is required")
	}
	if !utf8.ValidString(s) {
		panic(field + " is not valid text")
	}
	if utf8.RuneCountInString(s) > max {
		panic(field + " is longer than " + strconv.Itoa(max) + " characters")
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) ||
			(r >= 0x200b && r <= 0x200f) || (r >= 0x202a && r <= 0x202e) ||
			(r >= 0x2060 && r <= 0x2069) || r == 0xfeff {
			panic(field + " contains characters that are not allowed")
		}
	}
	return s
}

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	return cur.Previous().Address()
}

func refuseCoins(cur realm) {
	if !cur.IsCurrent() {
		panic("unauthorized: realm token is not current")
	}
	if cur.Previous().IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("the board does not take coins")
	}
}

func mustListing(id uint64) *listing {
	v := listings.Get(listingKey(id))
	if v == nil {
		panic("listing not found")
	}
	return v.(*listing)
}

func listingKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	if len(s) < 20 {
		s = strings.Repeat("0", 20-len(s)) + s
	}
	return s
}

package board

import (
	"strconv"
	"strings"
)

// jsonString quotes s as a JSON string. Everything outside printable ASCII
// is written as a \u escape, so the output is plain ASCII.
func jsonString(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch {
		case r == '"':
			b.WriteString(`\"`)
		case r == '\\':
			b.WriteString(`\\`)
		case r >= 0x20 && r < 0x7f:
			b.WriteRune(r)
		case r > 0xffff:
			r -= 0x10000
			writeU16(&b, 0xd800+(r>>10))
			writeU16(&b, 0xdc00+(r&0x3ff))
		default:
			writeU16(&b, r)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func writeU16(b *strings.Builder, r rune) {
	const hex = "0123456789abcdef"
	b.WriteString(`\u`)
	b.WriteByte(hex[(r>>12)&0xf])
	b.WriteByte(hex[(r>>8)&0xf])
	b.WriteByte(hex[(r>>4)&0xf])
	b.WriteByte(hex[r&0xf])
}

func jsonUint(v uint64) string {
	return strconv.FormatUint(v, 10)
}

func jsonInt(v int64) string {
	return strconv.FormatInt(v, 10)
}

func jsonBool(v bool) string {
	if v {
		return "true"
	}
	return "false"
}

// jsonObject joins already-encoded key/value pairs.
func jsonObject(pairs ...string) string {
	if len(pairs)%2 != 0 {
		panic("jsonObject needs key/value pairs")
	}
	var b strings.Builder
	b.WriteByte('{')
	for i := 0; i < len(pairs); i += 2 {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonString(pairs[i]))
		b.WriteByte(':')
		b.WriteString(pairs[i+1])
	}
	b.WriteByte('}')
	return b.String()
}

func jsonArray(items []string) string {
	return "[" + strings.Join(items, ",") + "]"
}

package board

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
)

const maxPage = 50

// ListingJSON returns one listing, or null.
func ListingJSON(id uint64) string {
	v := listings.Get(listingKey(id))
	if v == nil {
		return "null"
	}
	return v.(*listing).json(time.Now().Unix())
}

// OpenJSON lists open listings, newest first. side filters by buy, sell or
// swap; "" means all.
func OpenJSON(side string, offset, limit int) string {
	offset, limit = page(offset, limit)
	now := time.Now().Unix()
	items := []string{}
	skipped := 0
	more := false
	oldest := now - MaxDays*day
	listings.ReverseIterate("", "", func(_ string, v any) bool {
		l := v.(*listing)
		if l.createdAt < oldest {
			return true // nothing older can still be open
		}
		if !l.open(now) || (side != "" && l.side != side) {
			return false
		}
		if skipped < offset {
			skipped++
			return false
		}
		if len(items) == limit {
			more = true
			return true
		}
		items = append(items, l.json(now))
		return false
	})
	return jsonObject(
		"listings", jsonArray(items),
		"more", jsonBool(more),
		"total", jsonUint(lastID),
		"now", jsonInt(now),
	)
}

// ListingsOfJSON lists every listing of one owner, newest first.
func ListingsOfJSON(owner string, offset, limit int) string {
	offset, limit = page(offset, limit)
	now := time.Now().Unix()
	items := []string{}
	var ids []uint64
	if v := byOwner.Get(strings.TrimSpace(owner)); v != nil {
		ids = v.([]uint64)
	}
	more := false
	for i := len(ids) - 1 - offset; i >= 0; i-- {
		if len(items) == limit {
			more = true
			break
		}
		items = append(items, mustListing(ids[i]).json(now))
	}
	return jsonObject(
		"listings", jsonArray(items),
		"more", jsonBool(more),
		"now", jsonInt(now),
	)
}

// json describes the listing at block time now (unix seconds).
func (l *listing) json(now int64) string {
	return jsonObject(
		"id", jsonUint(l.id),
		"owner", jsonString(l.owner.String()),
		"side", jsonString(l.side),
		"give", jsonString(l.give),
		"want", jsonString(l.want),
		"note", jsonString(l.note),
		"open", jsonBool(l.open(now)),
		"createdAt", jsonInt(l.createdAt),
		"expiresAt", jsonInt(l.expiresAt),
		"closedAt", jsonInt(l.closedAt),
	)
}

func page(offset, limit int) (int, int) {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 || limit > maxPage {
		limit = maxPage
	}
	return offset, limit
}

// Render shows open listings on gnoweb, and one listing at listing/<id>.
func Render(path string) string {
	now := time.Now().Unix()
	path = strings.TrimSpace(path)
	if rest, ok := strings.CutPrefix(path, "listing/"); ok {
		if id, err := strconv.ParseUint(rest, 10, 64); err == nil {
			if v := listings.Get(listingKey(id)); v != nil {
				return renderListing(v.(*listing), now)
			}
		}
		return "# Not found\n\nNo listing at this address.\n"
	}
	if path != "" {
		return "# Not found\n\nNo listing at this address.\n"
	}

	var b strings.Builder
	b.WriteString("# Trade Window board\n\n")
	b.WriteString("Public listings: what someone gives and what they want. ")
	b.WriteString("A listing moves nothing; deals settle in a trade room.\n\n")
	n := 0
	oldest := now - MaxDays*day
	listings.ReverseIterate("", "", func(_ string, v any) bool {
		l := v.(*listing)
		if l.createdAt < oldest {
			return true
		}
		if !l.open(now) {
			return false
		}
		b.WriteString("- [" + sideLabel(l.side) + "](:listing/" + jsonUint(l.id) + "): " +
			sanitize.InlineText(l.give) + " for " + sanitize.InlineText(l.want) + "\n")
		n++
		return n >= 30
	})
	if n == 0 {
		b.WriteString("No open listings.\n")
	}
	return b.String()
}

func renderListing(l *listing, now int64) string {
	var b strings.Builder
	b.WriteString("# " + sideLabel(l.side) + ": " + sanitize.InlineText(l.give) + "\n\n")
	b.WriteString("Wants: " + sanitize.InlineText(l.want) + "\n\n")
	if l.note != "" {
		b.WriteString(sanitize.InlineText(l.note) + "\n\n")
	}
	b.WriteString("Posted by " + sanitize.InlineCode(l.owner.String()) + " on " +
		date(l.createdAt) + ". ")
	if l.open(now) {
		b.WriteString("Open until " + date(l.expiresAt) + ".\n")
	} else {
		b.WriteString("Closed.\n")
	}
	return b.String()
}

func sideLabel(side string) string {
	switch side {
	case SideBuy:
		return "Buying"
	case SideSell:
		return "Selling"
	default:
		return "Swapping"
	}
}

// date writes unix seconds as a UTC calendar date.
func date(unix int64) string {
	return time.Unix(unix, 0).UTC().Format("2006-01-02")
}

package cube3x3

// PhaseSegment describes an inclusive range of one-based solution move indices.
type PhaseSegment struct {
	Name      string
	StartMove int
	EndMove   int
	OBTM      int
}

// PhaseReport records the first Cross, F2L, and OLL checkpoints and the PLL
// checkpoint for the terminal solved run. A zero index means absent.
type PhaseReport struct {
	CrossFace   string
	CrossColor  uint8
	CrossAtMove int
	F2LAtMove   int
	OLLAtMove   int
	PLLAtMove   int
	Segments    []PhaseSegment
}

// Each row maps a face in the new frame to its location in the old frame
// after one clockwise quarter rotation. The columns follow move base order.
var priorFrame = [3][6]uint8{
	X - X: {F, B, L, R, D, U},
	Y - X: {U, D, F, B, R, L},
	Z - X: {L, R, D, U, F, B},
}

// ToPureFaceMoves projects each turn onto the starting frame. A wide turn
// emits its opposite-layer turn and changes the frame. Rotations only change
// the frame. Every projected turn keeps its original modifier and order.
func ToPureFaceMoves(moves []Move) []Move {
	frame := [6]uint8{U, D, L, R, F, B}
	pure := make([]Move, 0, len(moves))
	for _, move := range moves {
		if !isValidMove(move) {
			continue
		}
		if move.Base < Uw {
			pure = append(pure, Move{frame[move.Base], move.Mod})
			continue
		}
		if move.Base < X {
			wide := wideTurns[move.Base-Uw]
			pure = append(pure, Move{frame[wide.oppositeFace], move.Mod})
			move.Base = wide.rotation
			if wide.reverseRotation {
				move.Mod = 4 - move.Mod
			}
		}
		for turn := uint8(0); turn < move.Mod; turn++ {
			previous := frame
			for face, oldFace := range priorFrame[move.Base-X] {
				frame[face] = previous[oldFace]
			}
		}
	}
	return pure
}

var parallelFaceOrder = [3][2]uint8{{U, D}, {R, L}, {F, B}}

// NormalizePureFaceMoves reduces contiguous turns of parallel faces. A pass
// that removes a whole axis block can expose another reducible block.
func NormalizePureFaceMoves(moves []Move) []Move {
	current := ToPureFaceMoves(moves)
	if len(current) < 2 {
		return current
	}
	next := make([]Move, 0, len(current))
	for {
		next = next[:0]
		for i := 0; i < len(current); {
			// Opposite faces have consecutive move bases, grouped by axis.
			axis := current[i].Base / 2
			var totals [2]uint8
			for i < len(current) && current[i].Base/2 == axis {
				move := current[i]
				side := move.Base % 2
				totals[side] = (totals[side] + move.Mod) % 4
				i++
			}
			for _, face := range parallelFaceOrder[axis] {
				if mod := totals[face%2]; mod != 0 {
					next = append(next, Move{face, mod})
				}
			}
		}
		if sameMoveSequence(current, next) {
			return next
		}
		current, next = next, current
	}
}

// IsTrivialInverse compares the reduced physical solution with the reduced
// inverse scramble followed by the target algorithm.
func IsTrivialInverse(scramble, solution, targetAlg []Move) bool {
	expected := append(InvertMoves(scramble), targetAlg...)
	return sameMoveSequence(NormalizePureFaceMoves(solution), NormalizePureFaceMoves(expected))
}

func sameMoveSequence(a, b []Move) bool {
	if len(a) != len(b) {
		return false
	}
	for i, move := range a {
		if move != b[i] {
			return false
		}
	}
	return true
}

type phaseSide struct {
	crossEdge int
	sideEdge  int
	stride    int
}

const phaseFaceLetters = "URFDLB"

// The rows follow facelet order. Each entry gives a cross edge sticker, the
// adjoining side sticker, and the stride along that side's parallel strips.
// Centering strips on the side edge and the side center covers the first two
// layers on the side face.
var phaseSides = [6][4]phaseSide{
	{{5, 10, 1}, {7, 19, 1}, {3, 37, 1}, {1, 46, 1}},     // U
	{{10, 5, 3}, {12, 23, 3}, {16, 32, 3}, {14, 48, 3}},  // R
	{{19, 7, 1}, {23, 12, 3}, {25, 28, 1}, {21, 41, 3}},  // F
	{{32, 16, 1}, {28, 25, 1}, {30, 43, 1}, {34, 52, 1}}, // D
	{{37, 3, 3}, {41, 21, 3}, {43, 30, 3}, {39, 50, 3}},  // L
	{{46, 1, 1}, {48, 14, 3}, {52, 34, 1}, {50, 39, 3}},  // B
}

// AnalyzePhases replays the solution from its scramble state. CrossFace is
// the face at the Cross checkpoint. Later phases follow that center's color
// through rotations and wide turns.
func AnalyzePhases(scrambleState Cube, moves []Move) PhaseReport {
	_, report := replayWithPhases(scrambleState, moves)
	return report
}

// replayWithPhases returns both the final cube and the report from one replay.
func replayWithPhases(scrambleState Cube, moves []Move) (Cube, PhaseReport) {
	state := scrambleState
	var report PhaseReport
	lastTurn := 0
	for i, move := range moves {
		if !isValidMove(move) {
			continue
		}
		state = ApplyMove(state, move)
		if move.Base >= X {
			continue // Every phase is invariant under a whole-cube rotation.
		}

		lastTurn = i + 1
		if report.OLLAtMove != 0 {
			continue
		}
		if report.CrossAtMove == 0 {
			face := findCross(&state)
			if face < 0 || IsSolved(state) {
				continue
			}
			report.CrossFace = phaseFaceLetters[face : face+1]
			report.CrossColor = state[face*9+4]
			report.CrossAtMove = lastTurn
		}

		face := findCenter(&state, report.CrossColor)
		if face < 0 || !firstTwoLayersSolved(&state, face) {
			continue
		}
		if report.F2LAtMove == 0 {
			report.F2LAtMove = lastTurn
		}
		if phaseFaceSolved(&state, (face+3)%6) {
			report.OLLAtMove = lastTurn
		}
	}

	if report.CrossAtMove == 0 {
		if IsSolved(state) {
			report.PLLAtMove = len(moves)
		}
		return state, report
	}
	// A face or wide turn changes a solved cube. If replay ends solved,
	// its terminal solved run began at the last turn before any rotations.
	if IsSolved(state) {
		report.PLLAtMove = lastTurn
	}
	end := 0
	for _, phase := range [4]struct {
		name string
		step int
	}{
		{"Cross", report.CrossAtMove}, {"F2L", report.F2LAtMove},
		{"OLL", report.OLLAtMove}, {"PLL", report.PLLAtMove},
	} {
		if phase.step > end {
			obtm, _ := CountMetrics(moves[end:phase.step])
			report.Segments = append(report.Segments, PhaseSegment{phase.name, end + 1, phase.step, obtm})
			end = phase.step
		}
	}
	return state, report
}

func findCross(state *Cube) int {
	for face, sides := range phaseSides {
		color := state[face*9+4]
		matched := 0
		for _, side := range sides {
			if state[side.crossEdge] != color || state[side.sideEdge] != state[side.sideEdge/9*9+4] {
				break
			}
			matched++
		}
		if matched == len(sides) {
			return face
		}
	}
	return -1
}

func findCenter(state *Cube, color uint8) int {
	for face := 0; face < 6; face++ {
		if state[face*9+4] == color {
			return face
		}
	}
	return -1
}

func firstTwoLayersSolved(state *Cube, face int) bool {
	if !phaseFaceSolved(state, face) {
		return false
	}
	for _, side := range phaseSides[face] {
		center := side.sideEdge/9*9 + 4
		color := state[center]
		for offset := -side.stride; offset <= side.stride; offset += side.stride {
			if state[side.sideEdge+offset] != color || state[center+offset] != color {
				return false
			}
		}
	}
	return true
}

func phaseFaceSolved(state *Cube, face int) bool {
	start := face * 9
	color := state[start+4]
	for i := start; i < start+9; i++ {
		if state[i] != color {
			return false
		}
	}
	return true
}

package cube3x3

import "testing"

func TestToPureFaceMovesFrameTracking(t *testing.T) {
	start := ApplyMoves(SolvedCube(), analyzerMoves(t, "R U' B2 D F2 L'"))
	cases := []struct{ input, want string }{
		{"R x R", "R R"},
		{"R y2 L", "R R"},
		{"R Lw", "R R"},
		{"R Rw", "R L"},
		{"x U x'", "F"},
		{"y F y'", "R"},
		{"z U z'", "L"},
		{"Rw U Lw'", "L F R'"},
		{"R R' U2 U2", "R R' U2 U2"},
		{"x y2 z'", ""},
	}
	for _, tc := range cases {
		moves := analyzerMoves(t, tc.input)
		pure := ToPureFaceMoves(moves)
		if got := FormatMoves(pure); got != tc.want || len(pure) != len(analyzerMoves(t, tc.want)) {
			t.Errorf("%q projected to %q, want %q", tc.input, got, tc.want)
		}
		if ApplyMoves(start, pure) != NormalizeOrientation(ApplyMoves(start, moves)) {
			t.Errorf("%q changed the physical cube state", tc.input)
		}
	}

	// Every wide-turn modifier must also update the frame for subsequent turns.
	follow := analyzerMoves(t, "U D' F2 B R' L x2 z y' Rw2 U")
	for base := Uw; base <= Bw; base++ {
		for mod := uint8(1); mod <= 3; mod++ {
			moves := append([]Move{{base, mod}}, follow...)
			pure := ToPureFaceMoves(moves)
			obtm, _ := CountMetrics(moves)
			if len(pure) != obtm || ApplyMoves(start, pure) != NormalizeOrientation(ApplyMoves(start, moves)) {
				t.Errorf("base %d modifier %d: wrong physical sequence %q", base, mod, FormatMoves(pure))
			}
		}
	}
}

func TestAnalyzePhasesColorTrackedAcrossRotationsAndSkips(t *testing.T) {
	const crossAndF2L = "F R U R'"
	const sune = " R U R' U R U2 R'"
	const tPerm = " R U R' U' R' F R2 U' R' U' R U R' F'"
	const rotatedF2L = "F x2 y F D F'"
	const rotatedSune = " F D F' D F D2 F'"
	const rotatedTPerm = " F D F' D' F' R F2 D' F' D' F D F' R'"
	cases := []struct {
		name, physical, solution string
		checkpoints              [4]int
		segments                 []PhaseSegment
	}{
		{
			"rotated CFOP", crossAndF2L + sune + tPerm, rotatedF2L + rotatedSune + rotatedTPerm,
			[4]int{1, 6, 13, 27},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"OLL", 7, 13, 7}, {"PLL", 14, 27, 14}},
		},
		{
			"OLL skip", crossAndF2L + tPerm, rotatedF2L + rotatedTPerm,
			[4]int{1, 6, 6, 20},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"PLL", 7, 20, 14}},
		},
		{
			"PLL skip", crossAndF2L + sune, rotatedF2L + rotatedSune,
			[4]int{1, 6, 13, 13},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 6, 3}, {"OLL", 7, 13, 7}},
		},
		{
			"last layer oriented while F2L is broken", crossAndF2L + " D" + sune + " D'", crossAndF2L + " D" + sune + " D'",
			[4]int{1, 4, 13, 13},
			[]PhaseSegment{{"Cross", 1, 1, 1}, {"F2L", 2, 4, 3}, {"OLL", 5, 13, 9}},
		},
	}
	for _, tc := range cases {
		state := ApplyMoves(SolvedCube(), InvertMoves(analyzerMoves(t, tc.physical)))
		moves := analyzerMoves(t, tc.solution)
		if !IsSolved(ApplyMoves(state, moves)) {
			t.Fatalf("%s: fixture does not solve the cube", tc.name)
		}
		got := AnalyzePhases(state, moves)
		if got.CrossFace != "D" || got.CrossColor != 3 {
			t.Errorf("%s: cross face/color = %q/%d, want D/3", tc.name, got.CrossFace, got.CrossColor)
		}
		checkpoints := [4]int{got.CrossAtMove, got.F2LAtMove, got.OLLAtMove, got.PLLAtMove}
		if checkpoints != tc.checkpoints {
			t.Errorf("%s: checkpoints = %v, want %v", tc.name, checkpoints, tc.checkpoints)
		}
		if len(got.Segments) != len(tc.segments) {
			t.Errorf("%s: segments = %v, want %v", tc.name, got.Segments, tc.segments)
			continue
		}
		for i, segment := range got.Segments {
			if segment != tc.segments[i] {
				t.Errorf("%s: segment %d = %v, want %v", tc.name, i, segment, tc.segments[i])
			}
		}
	}
}

