		}
		if ApplyMoves(start, normalized) != NormalizeOrientation(ApplyMoves(start, moves)) {
			t.Errorf("normalize(%q) changed the physical cube state", tc.input)
		}
	}

	const checkerboard = "R2 L2 U2 D2 F2 B2"
	for _, tc := range []struct {
		scramble, solution, target string
		want                       bool
	}{
		{"R U", "U' R' x y", "", true},
		{"R U", "x y R' F'", "", true},
		{"R U", "U' x R'", "", true},
		{"R L R' L'", "x y L R L' R'", "", true},
		{"R U", "x y U' R'", "", false},
		{"R U", "U' R' " + checkerboard, checkerboard, true},
		{"R U", "U' R'", checkerboard, false},
		{"x R U", "U' R' U'", "F'", true},
		{
			"R' U' F D2 L2 F R2 U2 R2 B D2 L B2 D' B2 L' R' B D2 B U2 L U2 R' U' F",
			"D2 F' D2 U2 F' L2 D R2 D B2 F L2 R' F' D U'", "", false,
		},
	} {
		scramble := analyzerMoves(t, tc.scramble)
		solution := analyzerMoves(t, tc.solution)
		target := analyzerMoves(t, tc.target)
		if got := IsTrivialInverse(scramble, solution, target); got != tc.want {
			t.Errorf("IsTrivialInverse(%q, %q, %q) = %t, want %t", tc.scramble, tc.solution, tc.target, got, tc.want)
		}
	}
}

func analyzerMoves(t *testing.T, raw string) []Move {
	_, moves, err := Canonicalize(raw)
	if err != nil {
		t.Fatalf("invalid fixture %q: %v", raw, err)
	}
	return moves
}

package cube3x3

import "errors"

const (
	ErrInputTooLong    = "ERR_INPUT_TOO_LONG"
	ErrInvalidNotation = "ERR_INVALID_NOTATION"
	ErrMoveLimit       = "ERR_MOVE_LIMIT"
	ErrNotSolved       = "ERR_NOT_SOLVED"
	ErrTrivialInverse  = "ERR_TRIVIAL_INVERSE"
	ErrRuleViolation   = "ERR_RULE_VIOLATION"
)

// MoveTrace carries the starting state, replay, scores, and checkpoints for a rule.
type MoveTrace struct {
	Scramble      []Move
	ScrambleState Cube
	Moves         []Move
	PureMoves     []Move
	FinalState    Cube
	Phases        PhaseReport
	OBTM          int
	QTM           int
}

// CloneTrace copies the slice data so a rule can inspect or edit its own trace.
func CloneTrace(t MoveTrace) MoveTrace {
	t.Scramble = cloneTraceMoves(t.Scramble)
	t.Moves = cloneTraceMoves(t.Moves)
	t.PureMoves = cloneTraceMoves(t.PureMoves)
	if t.Phases.Segments != nil {
		segments := make([]PhaseSegment, len(t.Phases.Segments))
		copy(segments, t.Phases.Segments)
		t.Phases.Segments = segments
	}
	return t
}

func cloneTraceMoves(moves []Move) []Move {
	if moves == nil {
		return nil
	}
	cloned := make([]Move, len(moves))
	copy(cloned, moves)
	return cloned
}

// ConstraintRule defines a challenge target, scramble alphabet, and replay checks.
// AllowedMoves returns a fresh slice. An empty TargetAlg targets the solved cube.
// Validate returns an error for a rule violation and must not panic.
type ConstraintRule interface {
	ID() string
	Title() string
	Description() string
	AllowedMoves() []Move
	TargetAlg() []Move
	Validate(trace MoveTrace) error
}

// BuiltinRule resolves the five built-in challenge IDs.
func BuiltinRule(id string) (ConstraintRule, bool) {
	switch id {
	case "wca_obtm":
		return wcaOBTMRule{}, true
	case "checkpoint_cross_f2l":
		return checkpointCrossF2LRule{}, true
	case "pattern_checkerboard":
		return checkerboardRule{}, true
	case "no_fb":
		return noFBRule{}, true
	case "no_half_turns":
		return noHalfTurnsRule{}, true
	default:
		return nil, false
	}
}

// DailyTwistedRule selects the daily rule in the fixed four-day cycle.
func DailyTwistedRule(dayID int64) ConstraintRule {
	switch ((dayID % 4) + 4) % 4 {
	case 0:
		return checkpointCrossF2LRule{}
	case 1:
		return checkerboardRule{}
	case 2:
		return noFBRule{}
	default:
		return noHalfTurnsRule{}
	}
}

type wcaOBTMRule struct{}

func (wcaOBTMRule) ID() string    { return "wca_obtm" }
func (wcaOBTMRule) Title() string { return "Classic Fewest Moves" }
func (wcaOBTMRule) Description() string {
	return "Solve the cube in 80 moves or fewer (up to 120 turns including cube rotations). Middle-layer slice turns are not allowed."
}
func (wcaOBTMRule) AllowedMoves() []Move     { return allFaceTurns() }
func (wcaOBTMRule) TargetAlg() []Move        { return nil }
func (wcaOBTMRule) Validate(MoveTrace) error { return nil }

type checkpointCrossF2LRule struct{}

func (checkpointCrossF2LRule) ID() string    { return "checkpoint_cross_f2l" }
func (checkpointCrossF2LRule) Title() string { return "Step-by-Step: Cross then First Two Layers" }
func (checkpointCrossF2LRule) Description() string {
	return "Complete a cross on any face first, then finish the first two layers on a later move."
}
func (checkpointCrossF2LRule) AllowedMoves() []Move { return allFaceTurns() }
func (checkpointCrossF2LRule) TargetAlg() []Move    { return nil }
func (checkpointCrossF2LRule) Validate(trace MoveTrace) error {
	if trace.Phases.CrossAtMove > 0 && trace.Phases.F2LAtMove > trace.Phases.CrossAtMove {
		return nil
	}
	return errors.New("Complete a cross first, then finish the first two layers on a later move.")
}

type checkerboardRule struct{}

func (checkerboardRule) ID() string    { return "pattern_checkerboard" }
func (checkerboardRule) Title() string { return "Checkerboard Pattern" }
func (checkerboardRule) Description() string {
	return "Finish with a checkerboard pattern from any cube angle."
}
func (checkerboardRule) AllowedMoves() []Move { return allFaceTurns() }
func (checkerboardRule) TargetAlg() []Move {
	return []Move{{R, 2}, {L, 2}, {U, 2}, {D, 2}, {F, 2}, {B, 2}}
}
func (checkerboardRule) Validate(MoveTrace) error { return nil }

type noFBRule struct{}

func (noFBRule) ID() string    { return "no_fb" }
func (noFBRule) Title() string { return "No Front or Back Turns" }
func (noFBRule) Description() string {
	return "Solve using only Right, Up, Left, and Down face turns. Front and Back face turns stay locked even after rotating the cube."
}
func (noFBRule) AllowedMoves() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R}, []uint8{1, 2, 3})
}
func (noFBRule) TargetAlg() []Move { return nil }
func (noFBRule) Validate(trace MoveTrace) error {
	for _, move := range trace.PureMoves {
		switch move.Base {
		case R, U, L, D:
		default:
			return errors.New("Only Right (R), Up (U), Left (L), and Down (D) face turns are allowed in this challenge.")
		}
	}
	return nil
}

type noHalfTurnsRule struct{}

func (noHalfTurnsRule) ID() string    { return "no_half_turns" }
func (noHalfTurnsRule) Title() string { return "Quarter Turns Only" }
func (noHalfTurnsRule) Description() string {
	return "Use 90-degree single turns on alternating faces. 180-degree face turns and repeated turns on the same face are not allowed."
}
func (noHalfTurnsRule) AllowedMoves() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 3})
}
func (noHalfTurnsRule) TargetAlg() []Move { return nil }
func (noHalfTurnsRule) Validate(trace MoveTrace) error {
	for i, move := range trace.PureMoves {
		if move.Mod == 2 || (i > 0 && move.Base == trace.PureMoves[i-1].Base) {
			return errors.New("180-degree face turns and back-to-back turns on the same face are not allowed in Quarter Turns Only.")
		}
	}
	return nil
}

func allFaceTurns() []Move {
	return faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 2, 3})
}

// VerifyResult contains the verdict and metrics. Solved reports whether the
// target was reached. Phases is present only for an accepted solution.
type VerifyResult struct {
	Valid          bool
	ErrorCode      string
	ErrorMessage   string
	CanonicalMoves string
	OBTM           int
	QTM            int
	Solved         bool
	Phases         *PhaseReport
}

func (result VerifyResult) withError(code, message string) VerifyResult {
	result.ErrorCode = code
	result.ErrorMessage = message
	return result
}

// VerifySolution parses raw notation and verifies it for the supplied rule.
func VerifySolution(scrambleMoves []Move, rawMoves string, rule ConstraintRule) VerifyResult {
	if len(rawMoves) > MaxRawMovesBytes {
		return VerifyResult{ErrorCode: ErrInputTooLong, ErrorMessage: "Move notation is too long (maximum 512 bytes)."}
	}
	canonical, moves, err := Canonicalize(rawMoves)
	if err != nil {
		return VerifyResult{ErrorCode: ErrInvalidNotation, ErrorMessage: "Use standard face turns, wide turns, and cube rotations (middle-layer slices are not allowed)."}
	}
	return VerifyCanonicalMoves(scrambleMoves, canonical, moves, rule)
}

// VerifyCanonicalMoves verifies a canonical string and moves from Canonicalize
// without parsing them again.
func VerifyCanonicalMoves(scrambleMoves []Move, canonical string, moves []Move, rule ConstraintRule) VerifyResult {
	obtm, qtm := CountMetrics(moves)
	result := VerifyResult{CanonicalMoves: canonical, OBTM: obtm, QTM: qtm}
	if obtm < 1 || obtm > MaxOBTM || len(moves) > MaxTotalMoves {
		return result.withError(ErrMoveLimit, "Solutions must use 1 to 80 moves (maximum 120 turns including cube rotations).")
	}

	scrambleState := ApplyMoves(SolvedCube(), scrambleMoves)
	finalState, phases := replayWithPhases(scrambleState, moves)
	pureMoves := ToPureFaceMoves(moves)

	if rule == nil {
		return result.withError(ErrRuleViolation, "A challenge rule is required.")
	}
	targetAlg := rule.TargetAlg()
	if len(targetAlg) == 0 {
		result.Solved = IsSolved(finalState)
	} else {
		targetState := ApplyMoves(SolvedCube(), targetAlg)
		result.Solved = NormalizeOrientation(finalState) == NormalizeOrientation(targetState)
	}
	if !result.Solved {
		return result.withError(ErrNotSolved, "These moves do not reach the target cube state.")
	}
	if IsTrivialInverse(scrambleMoves, reduceReplayTurns(pureMoves), targetAlg) {
		return result.withError(ErrTrivialInverse, "This solution simply reverses the scramble. Find an original solve instead.")
	}

	trace := MoveTrace{
		Scramble:      scrambleMoves,
		ScrambleState: scrambleState,
		Moves:         moves,
		PureMoves:     pureMoves,
		FinalState:    finalState,
		Phases:        phases,
		OBTM:          obtm,
		QTM:           qtm,
	}
	if err := rule.Validate(CloneTrace(trace)); err != nil {
		return result.withError(ErrRuleViolation, err.Error())
	}
	result.Valid = true
	result.Phases = &phases
	return result
}

// reduceReplayTurns computes the same parallel-axis reduction used by
// IsTrivialInverse. Processing the replay once also bounds the cost when
// many nested blocks disappear. The trace retains the unreduced turns.
func reduceReplayTurns(pureMoves []Move) []Move {
	type axisBlock struct {
		axis  uint8
		turns [2]uint8
	}
	blocks := make([]axisBlock, 0, len(pureMoves))
	for _, move := range pureMoves {
		axis := move.Base / 2
		n := len(blocks)
		if n == 0 || blocks[n-1].axis != axis {
			blocks = append(blocks, axisBlock{axis: axis})
			n++
		}
		last := &blocks[n-1]
		side := move.Base % 2
		last.turns[side] = (last.turns[side] + move.Mod) % 4
		if last.turns[0] == 0 && last.turns[1] == 0 {
			blocks = blocks[:n-1]
		}
	}

	reduced := make([]Move, 0, len(pureMoves))
	for _, block := range blocks {
		for _, face := range parallelFaceOrder[block.axis] {
			if mod := block.turns[face%2]; mod != 0 {
				reduced = append(reduced, Move{face, mod})
			}
		}
	}
	return reduced
}

package cube3x3

import (
	"encoding/base64"
	"errors"
	"strings"
	"testing"
)

// This relation is an identity that the exact anti-inverse reduction keeps.
const constraintIdentity = "R U R' U' R U R' U' R U R' U' R U R' U' R U R' U' R U R' U'"
const checkerboardMoves = "R2 L2 U2 D2 F2 B2"

func requireBuiltinRule(t *testing.T, id string) ConstraintRule {
	t.Helper()
	rule, ok := BuiltinRule(id)
	if !ok || rule == nil || rule.ID() != id {
		t.Fatalf("missing built-in rule %q", id)
	}
	return rule
}

func TestNoHalfTurnsPhysicalFaceBypasses(t *testing.T) {
	rule := requireBuiltinRule(t, "no_half_turns")
	for _, raw := range []string{"R2", "Rw2", "R R", "R R'", "R Lw", "R x R", "R y2 L"} {
		moves := analyzerMoves(t, raw)
		if err := rule.Validate(MoveTrace{Moves: moves, PureMoves: ToPureFaceMoves(moves)}); err == nil {
			t.Errorf("no_half_turns accepted %q", raw)
		}
	}

	scramble := InvertMoves(analyzerMoves(t, "R Rw"))
	solution := constraintIdentity + " R Rw x2 y2 z2"
	got := VerifySolution(scramble, solution, rule)
	if !got.Valid || !got.Solved || got.OBTM != 26 || got.QTM != 26 {
		t.Errorf("no_half_turns rejected distinct physical faces or half rotations: %+v", got)
	}
}

func TestNoFBPhysicalFaceBypasses(t *testing.T) {
	rule := requireBuiltinRule(t, "no_fb")
	for _, raw := range []string{"F", "B'", "Fw", "Bw2", "x U x'", "y R y'", "Rw U Rw'"} {
		moves := analyzerMoves(t, raw)
		if err := rule.Validate(MoveTrace{Moves: moves, PureMoves: ToPureFaceMoves(moves)}); err == nil {
			t.Errorf("no_fb accepted %q", raw)
		}
	}
	scramble := analyzerMoves(t, "F'")
	if got := VerifySolution(scramble, constraintIdentity+" x U x'", rule); got.ErrorCode != "ERR_RULE_VIOLATION" {
		t.Errorf("no_fb verifier returned %+v for a finishing physical F turn", got)
	}
	if got := VerifySolution(nil, constraintIdentity+" x2 y2 z2", rule); !got.Valid {
		t.Errorf("no_fb rejected allowed physical faces: %+v", got)
	}
}

func TestPatternCheckerboardGenericTargetAndAntiInverse(t *testing.T) {
	rule := requireBuiltinRule(t, "pattern_checkerboard")
	target := rule.TargetAlg()
	if FormatMoves(target) != checkerboardMoves {
		t.Fatalf("checkerboard target = %q, want %q", FormatMoves(target), checkerboardMoves)
	}
	target[0] = Move{U, 1}
	if FormatMoves(rule.TargetAlg()) != checkerboardMoves {
		t.Fatal("checkerboard target was shared with the caller")
	}

	scramble := analyzerMoves(t, "R U")
	solution := constraintIdentity + " U' R' " + checkerboardMoves
	for _, tilt := range []string{"", " x", " x2", " x'", " z", " z'"} {
		for _, spin := range []string{"", " y", " y2", " y'"} {
			got := VerifySolution(scramble, solution+tilt+spin, rule)
			if !got.Valid || !got.Solved || got.Phases == nil {
				t.Errorf("checkerboard orientation %q: %+v", tilt+spin, got)
			}
		}
	}
	for _, tc := range []struct{ solution, code string }{
		{constraintIdentity + " U' R'", "ERR_NOT_SOLVED"},
		{"U' R' " + checkerboardMoves, "ERR_TRIVIAL_INVERSE"},
	} {
		got := VerifySolution(scramble, tc.solution, rule)
		if got.Valid || got.ErrorCode != tc.code || got.Phases != nil {
			t.Errorf("checkerboard solution %q: got %+v, want %s", tc.solution, got, tc.code)
		}
	}

	custom := testTargetRule{requireBuiltinRule(t, "wca_obtm")}
	if got := VerifySolution(nil, constraintIdentity+" F' x2", custom); !got.Valid {
		t.Errorf("non-checkerboard target was not verified: %+v", got)
	}
	if got := VerifySolution(nil, "F' x2", custom); got.ErrorCode != "ERR_TRIVIAL_INVERSE" {
		t.Errorf("custom target was not included in the anti-inverse check: %+v", got)
	}
}

type testTargetRule struct{ ConstraintRule }

func (testTargetRule) TargetAlg() []Move { return []Move{{F, 3}} }

type testMutatingTraceRule struct {
	ConstraintRule
	finalState Cube
}

func (rule testMutatingTraceRule) Validate(trace MoveTrace) error {
	if trace.FinalState != rule.finalState {
		return errors.New("unexpected final cube orientation in rule trace")
	}
	trace.Scramble[0] = Move{B, 2}
	trace.Moves[0] = Move{B, 2}
	trace.PureMoves[0] = Move{B, 2}
	trace.Phases.Segments[0] = PhaseSegment{Name: "changed"}
	return nil
}

func TestCloneTraceDeepCopiesSegmentsAndAllowedMoves(t *testing.T) {
	for _, tc := range []struct {
		id        string
		faceCount int
	}{
		{"wca_obtm", 18},
		{"checkpoint_cross_f2l", 18},
		{"pattern_checkerboard", 18},
		{"no_fb", 12},
		{"no_half_turns", 12},
	} {
		rule := requireBuiltinRule(t, tc.id)
		allowed := rule.AllowedMoves()
		if len(allowed) != tc.faceCount || len(rule.Title()) == 0 || len(rule.Description()) == 0 {
			t.Fatalf("invalid rule metadata or alphabet for %s", tc.id)
		}
		var seen [6][4]bool
		for _, move := range allowed {
			if move.Base > B || move.Mod < 1 || move.Mod > 3 {
				t.Fatalf("%s returned invalid alphabet move %v", tc.id, move)
			}
			if seen[move.Base][move.Mod] ||
				(tc.id == "no_fb" && (move.Base == F || move.Base == B)) ||
				(tc.id == "no_half_turns" && move.Mod == 2) {
				t.Errorf("%s returned unexpected alphabet move %v", tc.id, move)
			}
			seen[move.Base][move.Mod] = true
		}
		first := allowed[0]
		allowed[0] = Move{Z, 2}
		if rule.AllowedMoves()[0] != first {
			t.Errorf("%s shares its allowed-move slice", tc.id)
		}
		if tc.id != "pattern_checkerboard" && len(rule.TargetAlg()) != 0 {
			t.Errorf("%s should target the solved cube", tc.id)
		}
	}

	classic := requireBuiltinRule(t, "wca_obtm")
	finalState := ApplyMove(SolvedCube(), Move{X, 2})
	mutator := testMutatingTraceRule{classic, finalState}
	segment := PhaseSegment{"Cross", 1, 2, 2}
	original := MoveTrace{
		Scramble: []Move{{F, 1}}, Moves: []Move{{Rw, 1}}, PureMoves: []Move{{L, 1}},
		FinalState: finalState,
		Phases:     PhaseReport{Segments: []PhaseSegment{segment}},
	}
	if err := mutator.Validate(CloneTrace(original)); err != nil {
		t.Fatal(err)
	}
	if original.Scramble[0] != (Move{F, 1}) || original.Moves[0] != (Move{Rw, 1}) ||
		original.PureMoves[0] != (Move{L, 1}) || original.Phases.Segments[0] != segment {
		t.Fatalf("rule mutation escaped CloneTrace: %+v", original)
	}

	const finalTurns = "F R U R' U"
	scramble := InvertMoves(analyzerMoves(t, finalTurns))
	canonical, moves, err := Canonicalize(constraintIdentity + " " + finalTurns + " x2")
	if err != nil {
		t.Fatal(err)
	}
	want := VerifySolution(scramble, "  "+canonical+"\n", classic)
	if !want.Valid || want.Phases == nil || len(want.Phases.Segments) == 0 {
		t.Fatalf("verification fixture must pass with a phase segment: %+v", want)
	}
	got := VerifyCanonicalMoves(scramble, canonical, moves, mutator)
	if !got.Valid || !got.Solved || got.CanonicalMoves != want.CanonicalMoves ||
		got.OBTM != want.OBTM || got.QTM != want.QTM || got.Phases == nil ||
		len(got.Phases.Segments) != len(want.Phases.Segments) {
		t.Fatalf("canonical verifier returned %+v, want %+v", got, want)
	}
	if moves[0] != (Move{R, 1}) || scramble[0] != (Move{U, 3}) || got.Phases.Segments[0] != want.Phases.Segments[0] {
		t.Fatal("verification exposed caller moves or returned phase segments to the rule")
	}
}

func TestVerifySolution6ErrorCodesAndMaxTotalMoves(t *testing.T) {
	classic := requireBuiltinRule(t, "wca_obtm")
	half := requireBuiltinRule(t, "no_half_turns")
	checkpoint := requireBuiltinRule(t, "checkpoint_cross_f2l")
	for _, tc := range []struct {
		name, scramble, solution, code string
		rule                           ConstraintRule
	}{
		{"raw bytes", "", strings.Repeat(" ", 512) + "M", "ERR_INPUT_TOO_LONG", classic},
		{"invalid notation", "", "M", "ERR_INVALID_NOTATION", classic},
		{"zero OBTM", "", "x y z", "ERR_MOVE_LIMIT", classic},
		{"81 OBTM", "", strings.Repeat("R ", 81), "ERR_MOVE_LIMIT", classic},
		{"121 rotations", "", strings.Repeat("x ", 121), "ERR_MOVE_LIMIT", classic},
		{"121 tokens with valid OBTM", "", "R " + strings.Repeat("x ", 120), "ERR_MOVE_LIMIT", classic},
		{"wrong final state before rule", "", "R2", "ERR_NOT_SOLVED", half},
		{"trivial inverse before rule", "R2", "R2", "ERR_TRIVIAL_INVERSE", half},
		{"physical half turn", "", constraintIdentity + " R2 R2", "ERR_RULE_VIOLATION", half},
		{"missing checkpoint", "", constraintIdentity, "ERR_RULE_VIOLATION", checkpoint},
	} {
		got := VerifySolution(analyzerMoves(t, tc.scramble), tc.solution, tc.rule)
		if got.Valid || got.ErrorCode != tc.code || got.ErrorMessage == "" || got.Phases != nil {
			t.Errorf("%s: got %+v, want %s and nil phases", tc.name, got, tc.code)
		}
	}

	for _, tc := range []struct {
		cross, f2l int
		valid      bool
	}{{0, 4, false}, {4, 0, false}, {4, 4, false}, {4, 3, false}, {4, 5, true}} {
		trace := MoveTrace{Phases: PhaseReport{CrossAtMove: tc.cross, F2LAtMove: tc.f2l}}
		if got := checkpoint.Validate(trace) == nil; got != tc.valid {
			t.Errorf("Cross at %d, F2L at %d: valid=%t, want %t", tc.cross, tc.f2l, got, tc.valid)
		}
	}
	for _, tc := range []struct {
		day int64
		id  string
	}{
		{20782, "no_fb"}, {20783, "no_half_turns"}, {20799, "no_half_turns"},
		{-4, "checkpoint_cross_f2l"}, {-3, "pattern_checkerboard"}, {-2, "no_fb"}, {-1, "no_half_turns"},
		{0, "checkpoint_cross_f2l"}, {1, "pattern_checkerboard"},
	} {
		if got := DailyTwistedRule(tc.day).ID(); got != tc.id {
			t.Errorf("day %d: got %s, want %s", tc.day, got, tc.id)
		}
	}
	if rule, ok := BuiltinRule("unknown"); ok || rule != nil {
		t.Fatal("an unknown ID resolved as a built-in rule")
	}
}

func TestReplayReductionMatchesAntiInverseNormalization(t *testing.T) {
	for _, raw := range []string{
		"x y2 z'",
		"D U L R B F",
		"R L R' L' U",
		"R F U D U' D' F' R' L2",
		"R2 L R2 L L B2 B2 U' D R R' U",
		"x Rw2 U' B B' Uw2 y2 R L D2",
		constraintIdentity,
	} {
		moves := analyzerMoves(t, raw)
		got := reduceReplayTurns(ToPureFaceMoves(moves))
		want := NormalizePureFaceMoves(moves)
		if !sameMoveSequence(got, want) {
			t.Errorf("%q reduced to %q, want %q", raw, FormatMoves(got), FormatMoves(want))
		}
	}
}

const gasRotatedWide = "Rw2 x2 x2 Uw' x2 x2 Fw' x2 x2 "
const gasInverseWide = "Fw Uw Rw2 "
const gasWidePrefix = gasRotatedWide + gasRotatedWide + gasRotatedWide +
	gasRotatedWide + gasRotatedWide + gasRotatedWide + "Rw2 x2 x2 Uw' x2 x2 Fw' Rw2 Uw' "
const gasWidePrefixInverse = "Uw Rw2 " + gasInverseWide + gasInverseWide + gasInverseWide +
	gasInverseWide + gasInverseWide + gasInverseWide + gasInverseWide
const gasSingaporeSolve = "R F Rw Uw R' Fw' Uw' U2 R' Uw F' R2 U' F2 Uw F2 Uw2 Rw2 F2 R2 Uw' U'"

func TestVerifySolutionWorstCaseGas(t *testing.T) {
	// Follow the wide turns with their inverse so the nested turns cancel.
	const canonical = gasWidePrefix + "Fw' Rw2 Uw' Fw' Rw2 Uw' " +
		gasWidePrefixInverse + gasInverseWide + gasInverseWide + gasSingaporeSolve
	checkWorstCaseGasSolve(t, canonical, 108)
}

func TestVerifySolutionWorstCaseGasRetainedTurns(t *testing.T) {
	// Conjugating the wide-turn identity keeps more turns in the reduction.
	const wideCheckerboard = "Rw2 Lw2 Uw2 Dw2 Fw2 Bw2 "
	const canonical = gasWidePrefix + wideCheckerboard + wideCheckerboard +
		gasWidePrefixInverse + gasSingaporeSolve
	checkWorstCaseGasSolve(t, canonical, 116)
}

func checkWorstCaseGasSolve(t *testing.T, canonical string, qtm int) {
	t.Helper()
	// Both replays extend the sourced Singapore solve with 58 wide turns
	// and 40 rotations and pad the notation to the full byte limit.
	scramble := []Move{
		{R, 3}, {U, 3}, {F, 1}, {D, 1}, {R, 2}, {L, 3}, {U, 3}, {F, 1}, {L, 3},
		{U, 3}, {R, 2}, {B, 2}, {L, 1}, {B, 2}, {U, 3}, {L, 2}, {U, 2}, {D, 3},
		{R, 2}, {F, 2}, {L, 2}, {F, 3}, {R, 3}, {U, 3}, {F, 1},
	}
	if strings.Count(canonical, " ")+1 != MaxTotalMoves || len(canonical) > MaxRawMovesBytes {
		t.Fatal("gas fixture must hit the token cap and fit in the raw byte limit")
	}
	raw := canonical + strings.Repeat(" ", MaxRawMovesBytes-len(canonical))

	got := VerifySolution(scramble, raw, wcaOBTMRule{})
	if !got.Valid || !got.Solved || got.OBTM != MaxOBTM || got.QTM != qtm || got.CanonicalMoves != canonical || got.Phases == nil {
		t.Errorf("80-OBTM, 120-token, 512-byte solve failed: %+v", got)
	}
}

func TestSVGRenderMarkdownAndDataURI(t *testing.T) {
	const prefix = "data:image/svg+xml;base64,"
	state := ApplyMove(SolvedCube(), Move{R, 1})
	uri := RenderCubeNetDataURI(state)
	if !strings.HasPrefix(uri, prefix) {
		t.Fatalf("wrong SVG URI prefix: %.40s", uri)
	}
	if got := RenderCubeNetMarkdown(state, "Cube Net"); got != "![Cube Net]("+uri+")" {
		t.Fatal("markdown should wrap the same data URI exactly once")
	}
	data, err := base64.StdEncoding.DecodeString(uri[len(prefix):])
	if err != nil {
		t.Fatal(err)
	}
	svg := string(data)
	if !strings.HasPrefix(svg, "<svg ") || !strings.HasSuffix(svg, "</svg>") || strings.Count(svg, "<rect ") != 54 {
		t.Fatal("decoded image must contain one SVG net with 54 stickers")
	}
	if RenderCubeNetDataURI(SolvedCube()) == uri {
		t.Fatal("turning the cube should change the rendered facelets")
	}
}

package cube3x3

// Cube stores nine row-major facelets per face in U, R, F, D, L, B order.
// Colors 0 through 5 are white, red, green, yellow, orange and blue.
type Cube [54]uint8

// Move is a face turn, wide turn or cube rotation. Mod is 1 for clockwise,
// 2 for a half turn and 3 for counterclockwise.
type Move struct {
	Base uint8
	Mod  uint8
}

// Move bases. X, Y and Z represent x, y and z in algorithm notation.
const (
	U uint8 = iota
	D
	L
	R
	F
	B
	Uw
	Dw
	Lw
	Rw
	Fw
	Bw
	X
	Y
	Z
)

const (
	upCenter    = 4
	rightCenter = 13
	frontCenter = 22
	downCenter  = 31
	leftCenter  = 40
	backCenter  = 49
)

// Each clockwise quarter turn shifts stickers one position forward in its
// disjoint cycles. A half turn shifts two positions and an inverse three.
var turnCycles = [Z + 1][][4]uint8{
	U: {
		{0, 2, 8, 6}, {1, 5, 7, 3}, {9, 18, 36, 45}, {10, 19, 37, 46}, {11, 20, 38, 47},
	},
	D: {
		{15, 51, 42, 24}, {16, 52, 43, 25}, {17, 53, 44, 26}, {27, 29, 35, 33}, {28, 32, 34, 30},
	},
	L: {
		{0, 18, 27, 53}, {3, 21, 30, 50}, {6, 24, 33, 47}, {36, 38, 44, 42}, {37, 41, 43, 39},
	},
	R: {
		{2, 51, 29, 20}, {5, 48, 32, 23}, {8, 45, 35, 26}, {9, 11, 17, 15}, {10, 14, 16, 12},
	},
	F: {
		{6, 9, 29, 44}, {7, 12, 28, 41}, {8, 15, 27, 38}, {18, 20, 26, 24}, {19, 23, 25, 21},
	},
	B: {
		{0, 42, 35, 11}, {1, 39, 34, 14}, {2, 36, 33, 17}, {45, 47, 53, 51}, {46, 50, 52, 48},
	},
	X: {
		{0, 53, 27, 18}, {1, 52, 28, 19}, {2, 51, 29, 20}, {3, 50, 30, 21},
		{4, 49, 31, 22}, {5, 48, 32, 23}, {6, 47, 33, 24}, {7, 46, 34, 25},
		{8, 45, 35, 26}, {9, 11, 17, 15}, {10, 14, 16, 12}, {36, 42, 44, 38},
		{37, 39, 43, 41},
	},
	Y: {
		{0, 2, 8, 6}, {1, 5, 7, 3}, {9, 18, 36, 45}, {10, 19, 37, 46},
		{11, 20, 38, 47}, {12, 21, 39, 48}, {13, 22, 40, 49}, {14, 23, 41, 50},
		{15, 24, 42, 51}, {16, 25, 43, 52}, {17, 26, 44, 53}, {27, 33, 35, 29},
		{28, 30, 34, 32},
	},
	Z: {
		{0, 11, 35, 42}, {1, 14, 34, 39}, {2, 17, 33, 36}, {3, 10, 32, 43},
		{4, 13, 31, 40}, {5, 16, 30, 37}, {6, 9, 29, 44}, {7, 12, 28, 41},
		{8, 15, 27, 38}, {18, 20, 26, 24}, {19, 23, 25, 21}, {45, 51, 53, 47},
		{46, 48, 52, 50},
	},
}

// The opposite face and parallel cube rotation commute. Their combination
// cancels the turn of the opposite layer while moving the other two layers.
var wideTurns = [...]struct {
	oppositeFace    uint8
	rotation        uint8
	reverseRotation bool
}{
	Uw - Uw: {D, Y, false},
	Dw - Uw: {U, Y, true},
	Lw - Uw: {R, X, true},
	Rw - Uw: {L, X, false},
	Fw - Uw: {B, Z, false},
	Bw - Uw: {F, Z, true},
}

// SolvedCube returns the solved state with white on U and green on F.
func SolvedCube() Cube {
	var c Cube
	for i := range c {
		c[i] = uint8(i / 9)
	}
	return c
}

// CubeToFaceletString encodes each color as its solved face letter.
// A facelet outside the six-color palette is encoded as '?'.
func CubeToFaceletString(c Cube) string {
	const colors = "URFDLB"
	var letters [54]byte
	for i, color := range c {
		if color >= uint8(len(colors)) {
			letters[i] = '?'
			continue
		}
		letters[i] = colors[color]
	}
	return string(letters[:])
}

// ApplyMove returns the state after a move. An invalid base or modifier leaves
// the cube unchanged.
func ApplyMove(c Cube, m Move) Cube {
	if m.Base > Z || m.Mod < 1 || m.Mod > 3 {
		return c
	}
	if m.Base >= Uw && m.Base <= Bw {
		wide := wideTurns[m.Base-Uw]
		c = applyTurn(c, wide.oppositeFace, m.Mod)
		if wide.reverseRotation {
			m.Mod = 4 - m.Mod
		}
		return applyTurn(c, wide.rotation, m.Mod)
	}
	return applyTurn(c, m.Base, m.Mod)
}

func applyTurn(c Cube, base, mod uint8) Cube {
	// Each destination reads the sticker mod steps earlier in its cycle.
	back := 4 - mod
	for _, cycle := range turnCycles[base] {
		c[cycle[0]], c[cycle[1]], c[cycle[2]], c[cycle[3]] =
			c[cycle[back]], c[cycle[(back+1)%4]], c[cycle[(back+2)%4]], c[cycle[(back+3)%4]]
	}
	return c
}

// ApplyMoves applies moves in the order given.
func ApplyMoves(c Cube, moves []Move) Cube {
	for _, move := range moves {
		c = ApplyMove(c, move)
	}
	return c
}

// IsSolved reports whether c is a solved cube in any orientation.
func IsSolved(c Cube) bool {
	for i, color := range c {
		if color != c[(i/9)*9+4] {
			return false
		}
	}
	return NormalizeOrientation(c) == SolvedCube()
}

// NormalizeOrientation rotates a cube to white U and green F. If the centers
// cannot be brought to those positions, it returns the input unchanged.
func NormalizeOrientation(c Cube) Cube {
	oriented := c
	// Move White to U with one rotation about X or Z.
	switch {
	case c[upCenter] == 0:
	case c[frontCenter] == 0:
		oriented = applyTurn(c, X, 1)
	case c[downCenter] == 0:
		oriented = applyTurn(c, X, 2)
	case c[backCenter] == 0:
		oriented = applyTurn(c, X, 3)
	case c[leftCenter] == 0:
		oriented = applyTurn(c, Z, 1)
	case c[rightCenter] == 0:
		oriented = applyTurn(c, Z, 3)
	default:
		return c
	}

	// A Y rotation keeps White on U and brings Green to F.
	switch {
	case oriented[frontCenter] == 2:
		return oriented
	case oriented[rightCenter] == 2:
		return applyTurn(oriented, Y, 1)
	case oriented[backCenter] == 2:
		return applyTurn(oriented, Y, 2)
	case oriented[leftCenter] == 2:
		return applyTurn(oriented, Y, 3)
	default:
		return c
	}
}

