		{"ASCII whitespace only", " \t\n\r ", "", 0, 0},
		{"ASCII separators", " \tR   U2\nF'\r\nD\rL2 B' ", "R U2 F' D L2 B'", 6, 8},
		{"wide turns", "Uw Dw' Lw2 Rw Fw' Bw2", "Uw Dw' Lw2 Rw Fw' Bw2", 6, 8},
		{"mixed wide turns and rotations", "Rw x2\tF2 y' Lw2 z U'", "Rw x2 F2 y' Lw2 z U'", 4, 6},
		{"rotations only", "x y2 z'", "x y2 z'", 0, 0},
	}
	for _, tc := range valid {
		canonical, moves, err := Canonicalize(tc.input)
		if err != nil || canonical != tc.expected {
			t.Errorf("%s: got %q, %v, want %q", tc.name, canonical, err, tc.expected)
			continue
		}
		if tc.expected == "" && moves != nil {
			t.Errorf("%s: empty input should return nil moves", tc.name)
		}
		if formatted := FormatMoves(moves); formatted != tc.expected {
			t.Errorf("%s: formatted %q, want %q", tc.name, formatted, tc.expected)
		}
		obtm, qtm := CountMetrics(moves)
		if obtm != tc.obtm || qtm != tc.qtm {
			t.Errorf("%s: got OBTM/QTM %d/%d, want %d/%d", tc.name, obtm, qtm, tc.obtm, tc.qtm)
		}
	}

	invalid := []string{
		"M", "E", "S", "r", "u", "f", "R2'", "R'2", "Rw R'w", "X", "RU",
		"R\vU", "R\fU", "R\x00U", "R\x7fU", "R’", "R\u00a0U",
	}
	for _, input := range invalid {
		canonical, moves, err := Canonicalize(input)
		if err == nil || err.Error() != "ERR_INVALID_NOTATION" || canonical != "" || moves != nil {
			t.Errorf("%q: want ERR_INVALID_NOTATION and no output, got %q, %v, %v", input, canonical, moves, err)
		}
	}

	atLimit := strings.Repeat(" ", 511) + "R"
	canonical, moves, err := Canonicalize(atLimit)
	if err != nil || canonical != "R" || len(moves) != 1 {
		t.Fatalf("512 bytes: got %q, %v, %v", canonical, moves, err)
	}
	for _, input := range []string{atLimit + " ", strings.Repeat(" ", 511) + "é"} {
		canonical, moves, err := Canonicalize(input)
		if err == nil || err.Error() != "ERR_INPUT_TOO_LONG" || canonical != "" || moves != nil {
			t.Errorf("513 bytes: want ERR_INPUT_TOO_LONG and no output, got %q, %v, %v", canonical, moves, err)
		}
	}
}

func TestInvertMoves(t *testing.T) {
	moves := []Move{{R, 1}, {Uw, 2}, {X, 3}, {F, 1}}
	inverse := InvertMoves(moves)
	if got := FormatMoves(inverse); got != "F' x Uw2 R'" {
		t.Errorf("inverse = %q, want F' x Uw2 R'", got)
	}
	if got := FormatMoves(moves); got != "R Uw2 x' F" {
		t.Errorf("original moves changed to %q", got)
	}
	if ApplyMoves(ApplyMoves(SolvedCube(), moves), inverse) != SolvedCube() {
		t.Error("inverse did not restore the original facelets")
	}
}

func TestSourcedGoldenWCASolves(t *testing.T) {
	// These sequences and metrics come from fixtures/wca-golden-solves.json.
	cases := []struct {
		id, scramble, solution string
		obtm, qtm              int
	}{
		{
			"fmc2019-tronto-final-1",
			"R' U' F D2 L2 F R2 U2 R2 B D2 L B2 D' B2 L' R' B D2 B U2 L U2 R' U' F",
			"D2 F' D2 U2 F' L2 D R2 D B2 F L2 R' F' D U'",
			16, 23,
		},
		{
			"singapore2025-chang-first-1",
			"R' U' F D R2 L' U' F L' U' R2 B2 L B2 U' L2 U2 D' R2 F2 L2 F' R' U' F",
			"R F Rw Uw R' Fw' Uw' U2 R' Uw F' R2 U' F2 Uw F2 Uw2 Rw2 F2 R2 Uw' U'",
			22, 30,
		},
		{
			"warszawa2026-pietrusiak-final-3",
			"R' U' F R2 B U2 B' F L2 F U2 B' D' B' R2 U B2 F L D2 L2 F' R' U' F",
			"U B L U2 F' R' B' D2 B' L2 D2 F2 B' R2 B' R2 L2 D' F'",
			19, 27,
		},
	}
	for _, tc := range cases {
		_, scramble, err := Canonicalize(tc.scramble)
		if err != nil {
			t.Fatalf("%s: invalid scramble: %v", tc.id, err)
		}
		_, solution, err := Canonicalize(tc.solution)
		if err != nil || len(solution) == 0 {
			t.Fatalf("%s: invalid or empty solution: %v", tc.id, err)
		}
		obtm, qtm := CountMetrics(solution)
		if obtm != tc.obtm || qtm != tc.qtm {
			t.Errorf("%s: got OBTM/QTM %d/%d, want %d/%d", tc.id, obtm, qtm, tc.obtm, tc.qtm)
		}
		scrambled := ApplyMoves(SolvedCube(), scramble)
		if !IsSolved(ApplyMoves(scrambled, solution)) {
			t.Errorf("%s: reconstruction did not solve the scramble", tc.id)
		}
		if IsSolved(ApplyMoves(scrambled, solution[:len(solution)-1])) {
			t.Errorf("%s: reconstruction still solved without its final move", tc.id)
		}
	}
}

func TestScrambleDeterminismAndSubgroupGuards(t *testing.T) {
	for _, seed := range [][32]byte{{}, {1}, {255, 1}, {31: 255}} {
		wca := GenerateWCAScramble(seed)
		if len(wca) != 30 {
			t.Fatalf("WCA scramble length = %d, want 30", len(wca))
		}
		if FormatMoves(wca[:3]) != "R' U' F" || FormatMoves(wca[27:]) != "R' U' F" {
			t.Errorf("incorrect WCA scramble padding: %s", FormatMoves(wca))
		}
		if wca[3].Base == F || wca[3].Base == B || wca[26].Base == L || wca[26].Base == R {
			t.Errorf("WCA scramble has parallel turns at a padding seam: %s", FormatMoves(wca))
		}
		for _, move := range wca {
			if move.Base > B || move.Mod < 1 || move.Mod > 3 {
				t.Errorf("invalid WCA scramble move: %v", move)
			}
		}
		assertNoRedundantFaceTurns(t, wca)
		for _, rule := range []string{"wca_obtm", "checkpoint_cross_f2l", "pattern_checkerboard"} {
			got, err := ScrambleForRule(seed, rule, []Move{{X, 1}})
			if err != nil || FormatMoves(got) != FormatMoves(wca) {
				t.Errorf("%s did not reproduce the WCA scramble: %v", rule, err)
			}
		}

		for _, rule := range []string{"no_fb", "no_half_turns"} {
			got, err := ScrambleForRule(seed, rule, nil)
			if err != nil || len(got) != 35 {
				t.Fatalf("%s: want 35 moves, got %d, %v", rule, len(got), err)
			}
			for _, move := range got {
				if move.Base > B || move.Mod < 1 || move.Mod > 3 {
					t.Errorf("%s: invalid scramble move %v", rule, move)
				}
				if (rule == "no_fb" && (move.Base == F || move.Base == B)) ||
					(rule == "no_half_turns" && move.Mod == 2) {
					t.Errorf("%s: forbidden scramble move %v", rule, move)
				}
			}
			assertNoRedundantFaceTurns(t, got)
		}
	}

	if FormatMoves(GenerateWCAScramble([32]byte{})) == FormatMoves(GenerateWCAScramble([32]byte{1})) {
		t.Error("different seeds produced the same WCA scramble")
	}
	for _, bad := range [][]Move{
		{{R, 1}, {R, 3}, {L, 1}},
		{{X, 1}, {Y, 1}},
		{{R, 1}, {Rw, 3}, {U, 0}},
	} {
		if moves, err := GenerateSubgroupScramble([32]byte{}, bad, 35); err == nil || moves != nil {
			t.Errorf("invalid alphabet %v: want error and nil moves, got %v, %v", bad, moves, err)
		}
	}
}

func TestCustomSubgroupScramble(t *testing.T) {
	seed := [32]byte{7}
	clean := []Move{{U, 3}, {Rw, 2}}
	withDuplicates := []Move{{Y, 2}, {Rw, 2}, {U, 3}, {Rw, 2}, {U, 3}}
	want, err := GenerateSubgroupScramble(seed, clean, 35)
	if err != nil || len(want) != 35 {
		t.Fatalf("clean alphabet: want 35 moves, got %d, %v", len(want), err)
	}
	got, err := ScrambleForRule(seed, "custom", withDuplicates)
	if err != nil || FormatMoves(got) != FormatMoves(want) {
		t.Errorf("custom rule did not use the deduplicated subgroup: %v", err)
	}
	got, err = GenerateSubgroupScramble(seed, withDuplicates, 0)
	if err != nil || FormatMoves(got) != FormatMoves(want) {
		t.Errorf("default length did not produce the 35-move subgroup: %v", err)
	}
	short, err := GenerateSubgroupScramble(seed, clean, 6)
	const fromRight = "Rw2 U' Rw2 U' Rw2 U'"
	const fromUp = "U' Rw2 U' Rw2 U' Rw2"
	if formatted := FormatMoves(short); err != nil || (formatted != fromRight && formatted != fromUp) {
		t.Errorf("short custom scramble: expected alternating Rw2/U', got %q, %v", formatted, err)
	}
	if moves, err := GenerateSubgroupScramble(seed, clean, -1); err == nil || moves != nil {
		t.Errorf("negative length: want error and nil moves, got %v, %v", moves, err)
	}

	full := []Move{{U, 1}, {R, 1}, {Rw, 2}, {L, 3}}
	withExtras := []Move{{Z, 1}, {L, 3}, {Rw, 2}, {R, 1}, {Rw, 2}, {U, 1}, {R, 1}}
	want, err = GenerateSubgroupScramble(seed, full, 35)
	if err != nil || len(want) != 35 {
		t.Fatalf("custom alphabet: want 35 moves, got %d, %v", len(want), err)
	}
	got, err = GenerateSubgroupScramble(seed, withExtras, 35)
	if err != nil || FormatMoves(got) != FormatMoves(want) {
		t.Errorf("input ordering, duplicates, or rotations changed sampling: %v", err)
	}
	for i := 1; i < len(want); i++ {
		a, b := want[i-1].Base, want[i].Base
		if (a == R && b == Rw) || (a == Rw && b == R) {
			t.Errorf("custom scramble repeated a nominal face: %s", FormatMoves(want))
			break
		}
	}
}

func assertNoRedundantFaceTurns(t *testing.T, moves []Move) {
	for i := 1; i < len(moves); i++ {
		current, previous := moves[i].Base, moves[i-1].Base
		if current == previous {
			t.Errorf("consecutive same-face turns at %d: %s", i, FormatMoves(moves))
		}
		if i > 1 && current == moves[i-2].Base && current/2 == previous/2 {
			t.Errorf("parallel-axis ABA at %d: %s", i, FormatMoves(moves))
		}
	}
}

package cube3x3

import (
	"crypto/sha256"
	"errors"
)

const subgroupScrambleLength = 35

// GenerateWCAScramble wraps 24 random face turns in the FMC padding.
// The body starts and ends on axes different from their neighboring padding.
func GenerateWCAScramble(seed [32]byte) []Move {
	const bodyLength = 24
	padding := []Move{{R, 3}, {U, 3}, {F, 1}}
	moves := make([]Move, 0, bodyLength+2*len(padding))
	moves = append(moves, padding...)
	allowed := faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 2, 3})
	moves = extendScramble(seed, moves, allowed, bodyLength, true)
	return append(moves, padding...)
}

// GenerateSubgroupScramble samples the valid non-rotation moves in allowed.
// The alphabet is sorted by base and modifier so ordering and duplicates have
// no effect. A zero length requests the default 35 moves.
func GenerateSubgroupScramble(seed [32]byte, allowed []Move, length int) ([]Move, error) {
	if length < 0 {
		return nil, errors.New("ERR_RULE_VIOLATION: scramble length cannot be negative")
	}
	if length == 0 {
		length = subgroupScrambleLength
	}

	var seen [X][4]bool
	var axes [3]bool
	axisCount := 0
	for _, move := range allowed {
		if move.Base < X && isValidMove(move) {
			seen[move.Base][move.Mod] = true
			axis := scrambleFace(move.Base) / 2
			if !axes[axis] {
				axes[axis] = true
				axisCount++
			}
		}
	}
	if axisCount < 2 {
		return nil, errors.New("ERR_RULE_VIOLATION: scramble needs moves on at least two axes")
	}

	var alphabet []Move
	for base := U; base < X; base++ {
		for mod := uint8(1); mod <= 3; mod++ {
			if seen[base][mod] {
				alphabet = append(alphabet, Move{base, mod})
			}
		}
	}
	return extendScramble(seed, make([]Move, 0, length), alphabet, length, false), nil
}

// ScrambleForRule selects the fixed alphabet for a built-in rule or the
// supplied alphabet for a custom rule.
func ScrambleForRule(seed [32]byte, ruleID string, allowed []Move) ([]Move, error) {
	switch ruleID {
	case "wca_obtm", "checkpoint_cross_f2l", "pattern_checkerboard":
		return GenerateWCAScramble(seed), nil
	case "no_fb":
		allowed = faceTurnAlphabet([]uint8{U, D, L, R}, []uint8{1, 2, 3})
	case "no_half_turns":
		allowed = faceTurnAlphabet([]uint8{U, D, L, R, F, B}, []uint8{1, 3})
	}
	return GenerateSubgroupScramble(seed, allowed, subgroupScrambleLength)
}

func faceTurnAlphabet(faces, mods []uint8) []Move {
	allowed := make([]Move, 0, len(faces)*len(mods))
	for _, face := range faces {
		for _, mod := range mods {
			allowed = append(allowed, Move{face, mod})
		}
	}
	return allowed
}

// scrambleFace groups a wide turn with the face named by its token.
func scrambleFace(base uint8) uint8 {
	if base >= Uw {
		return base - Uw
	}
	return base
}

func extendScramble(seed [32]byte, moves, allowed []Move, length int, padded bool) []Move {
	rng := scrambleRNG{next: sha256.Size}
	copy(rng.input[:32], seed[:])
	var candidates [X * 3]Move
	for i := 0; i < length; i++ {
		// Opposing faces are consecutive in the base constants and share an axis.
		lastFace, blockedAxis := X, X
		n := len(moves)
		if n > 0 {
			lastFace = scrambleFace(moves[n-1].Base)
			if n > 1 && scrambleFace(moves[n-2].Base)/2 == lastFace/2 {
				blockedAxis = lastFace / 2
			}
		}
		if padded && i == 0 {
			blockedAxis = F / 2
		}

		count := 0
		for _, move := range allowed {
			face := scrambleFace(move.Base)
			if face == lastFace || face/2 == blockedAxis ||
				(padded && i == length-1 && face/2 == R/2) {
				continue
			}
			candidates[count] = move
			count++
		}
		// Each subgroup has at least two axes. The padded form has three,
		// so the two axis exclusions at its final step leave a candidate.
		moves = append(moves, candidates[rng.uniform(count)])
	}
	return moves
}

// scrambleRNG streams SHA-256(seed || big-endian uint64 counter) from counter 0.
type scrambleRNG struct {
	input   [40]byte
	counter uint64
	block   [sha256.Size]byte
	next    int
}

func (rng *scrambleRNG) nextByte() byte {
	if rng.next == len(rng.block) {
		counter := rng.counter
		for i := len(rng.input) - 1; i >= 32; i-- {
			rng.input[i] = byte(counter)
			counter >>= 8
		}
		rng.block = sha256.Sum256(rng.input[:])
		rng.counter++
		rng.next = 0
	}
	value := rng.block[rng.next]
	rng.next++
	return value
}

func (rng *scrambleRNG) uniform(count int) int {
	// Discard the incomplete tail so every index has equal probability.
	limit := 256 - 256%count
	for {
		value := int(rng.nextByte())
		if value < limit {
			return value % count
		}
	}
}

package cube3x3

import "gno.land/p/nt/svg/v0"

// RenderCubeNetMarkdown returns a Markdown image of the cube net.
func RenderCubeNetMarkdown(c Cube, alt string) string {
	return cubeNetCanvas(c).Render(alt)
}

// RenderCubeNetDataURI returns the base64 SVG data URI of the cube net.
func RenderCubeNetDataURI(c Cube) string {
	return "data:image/svg+xml;base64," + cubeNetCanvas(c).Base64()
}

func cubeNetCanvas(c Cube) *svg.Canvas {
	const stickerSize = 12
	const faceSize = 3 * stickerSize
	const width, height = 4 * faceSize, 3 * faceSize
	canvas := svg.NewCanvas(width, height).WithViewBox(0, 0, width, height)

	// Place U above F and D below it, with L F R B across the middle.
	facePositions := [6][2]int{{1, 0}, {2, 1}, {1, 1}, {1, 2}, {0, 1}, {3, 1}}
	colors := [6]string{"#f5f5f5", "#b91c1c", "#15803d", "#facc15", "#f97316", "#1d4ed8"}
	for i, color := range c {
		face := facePositions[i/9]
		sticker := i % 9
		x := face[0]*faceSize + sticker%3*stickerSize
		y := face[1]*faceSize + sticker/3*stickerSize
		fill := "#6b7280"
		if int(color) < len(colors) {
			fill = colors[color]
		}
		canvas.Append(svg.NewRectangle(x, y, stickerSize-1, stickerSize-1, fill))
	}
	return canvas
}

// Package core provides shared validation helpers, deterministic identifier
// rules and status vocabulary for the PROOFLOOM protocol realms.
//
// core holds no mutable state: it is a pure library so it can be imported by
// every other PROOFLOOM realm and by external consumer realms without any
// interrealm authority concerns.
package core

import (
	"strings"
)

// Protocol version stamped on every record produced by these realms.
const ProtocolVersion = "1.0.0"

// Release lifecycle statuses. The authoritative state machine is enforced by
// the releases realm; these constants are shared so callers can reference
// states without magic strings.
const (
	ReleaseDraft          = "DRAFT"
	ReleaseEvidencePending = "EVIDENCE_PENDING"
	ReleaseValidating     = "VALIDATING"
	ReleaseReviewRequired = "REVIEW_REQUIRED"
	ReleaseApproved       = "APPROVED"
	ReleasePublished      = "PUBLISHED"
	ReleaseVerified       = "VERIFIED"
	ReleaseRejected       = "REJECTED"
	ReleaseRevoked        = "REVOKED"
	ReleaseSuperseded     = "SUPERSEDED"
	ReleaseDisputed       = "DISPUTED"
)

// Attestation statuses.
const (
	AttestationActive  = "ACTIVE"
	AttestationRevoked = "REVOKED"
	AttestationExpired = "EXPIRED"
)

// Agent statuses.
const (
	AgentActive    = "ACTIVE"
	AgentSuspended = "SUSPENDED"
	AgentRevoked   = "REVOKED"
)

// Agent permission scopes. Permissions are least-privilege and explicitly
// granted; there is no wildcard scope by design.
const (
	AgentScopeRead          = "READ"
	AgentScopeEvidence      = "EVIDENCE"
	AgentScopeVerifyRequest = "VERIFY_REQUEST"
	AgentScopeTaskUpdate    = "TASK_UPDATE"
	AgentScopeReviewPropose = "REVIEW_PROPOSE"
	AgentScopePublishReq    = "PUBLISH_REQUEST"
)

// Attestation subject types.
const (
	SubjectRelease  = "RELEASE"
	SubjectProject  = "PROJECT"
	SubjectComponent = "COMPONENT"
	SubjectTask     = "TASK"
	SubjectExecution = "AGENT_EXECUTION"
)

// Attestation categories supported by the protocol.
const (
	AttestBuild          = "BUILD_PROVENANCE"
	AttestSource         = "SOURCE_PROVENANCE"
	AttestTest           = "TEST_EXECUTION"
	AttestSecurity       = "SECURITY_ASSESSMENT"
	AttestCodeReview     = "CODE_REVIEW"
	AttestReleaseApprove = "RELEASE_APPROVAL"
	AttestAgentTask      = "AGENT_TASK_COMPLETION"
	AttestBenchmark      = "BENCHMARK_RESULT"
	AttestDependency     = "DEPENDENCY_VERIFICATION"
	AttestOwnership      = "OWNERSHIP_VERIFICATION"
	AttestDeployment     = "DEPLOYMENT_VERIFICATION"
	AttestCompliance     = "COMPLIANCE_EVIDENCE"
	AttestIncident       = "INCIDENT_REMEDIATION"
)

// IsValidAddress reports whether a looks like a Gno bech32 user or package
// address (g1-prefixed). It does not checksum-verify; the VM guarantees the
// addresses it hands out, and externally supplied strings must pass this gate
// before being stored.
func IsValidAddress(a string) bool {
	if len(a) != 40 && len(a) != 43 {
		// user addresses are g1 + 38 chars; package addresses vary slightly.
		if len(a) < 10 || len(a) > 64 {
			return false
		}
	}
	if !strings.HasPrefix(a, "g1") {
		return false
	}
	for i := 0; i < len(a); i++ {
		c := a[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// IsValidDigest reports whether d is a plausible sha256 hex digest
// (64 lowercase hex characters).
func IsValidDigest(d string) bool {
	if len(d) != 64 {
		return false
	}
	for i := 0; i < len(d); i++ {
		c := d[i]
		ok := (c >= 'a' && c <= 'f') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// IsValidID reports whether id is a safe slug: lowercase letters, digits and
// dashes, 1..64 characters, no leading or trailing dash.
func IsValidID(id string) bool {
	if len(id) == 0 || len(id) > 64 {
		return false
	}
	if id[0] == '-' || id[len(id)-1] == '-' {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidSlugList validates a comma-free, whitespace-free list of IDs.
func IsValidSlugList(ids []string) bool {
	for _, id := range ids {
		if !IsValidID(id) {
			return false
		}
	}
	return true
}

// IsValidVersion checks a loose semver-ish version string: digits and dots
// with optional alphanum suffix, 1..32 chars.
func IsValidVersion(v string) bool {
	if len(v) == 0 || len(v) > 32 {
		return false
	}
	for i := 0; i < len(v); i++ {
		c := v[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidShortHash validates git commit-ish strings (7..64 hex chars).
func IsValidShortHash(h string) bool {
	if len(h) < 7 || len(h) > 64 {
		return false
	}
	for i := 0; i < len(h); i++ {
		c := h[i]
		ok := (c >= 'a' && c <= 'f') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// BoundedText guards free-form metadata length on-chain to prevent state
// bloat. Nothing longer than maxLen may be persisted.
func BoundedText(s string, maxLen int) bool {
	return len(s) <= maxLen
}

// ComposeReleaseID derives a deterministic release identifier from the
// project ID and version. Release IDs must be reproducible off-chain so
// external consumers can address them without a lookup.
func ComposeReleaseID(projectID, version string) string {
	return projectID + "-" + strings.ToLower(version)
}

// ComposeAttestationID derives a deterministic attestation identifier from
// subject, category and issuer so duplicate attestations from the same issuer
// for the same subject/category are structurally impossible.
func ComposeAttestationID(subjectID, category, issuer string) string {
	return subjectID + "-" + strings.ToLower(category) + "-" + issuer
}

