// Package registry is the authoritative on-chain registry of PROOFLOOM
// projects and software components. It is the ownership backbone of the
// protocol: every other realm consults it for authorization decisions.
//
// Security model:
//   - The protocol admin (set once at Init) can only manage registrar
//     allow-lists, never project state owned by users.
//   - Project owners are recorded from cur.Previous().Address() and never
//     from caller-supplied arguments.
//   - Getters return value copies; internal maps and slices are never
//     exposed.
package registry

import (
        "gno.land/r/g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq/proofloom/core"

        "sort"
        "strings"
        "time"
)

// Project is a registered software project. Owned by the address that
// registered it.
type Project struct {
        ID          string
        Name        string
        Description string
        Repo        string
        Category    string
        Visibility  string // "public" or "private"
        Owner       address
        CreatedAt   int64
        Archived    bool
}

// Component is a software component (package, image, binary, SBOM...)
// associated with a project.
type Component struct {
        ID           string
        ProjectID    string
        Name         string
        License      string
        ArtifactType string // source, container, binary, sbom, docs
        Owner        address
        CreatedAt    int64
        Deprecated   bool
}

var (
        projects   map[string]*Project
        components map[string]*Component

        admin      address
        registrars map[string]bool // addresses allowed to register projects
)

// projectIDs preserves registration order for deterministic listing.
var projectIDs []string
var componentIDs []string

func mustAdmin(cur realm) {
        if cur.Previous().Address() != admin {
                panic("registry: caller is not protocol admin")
        }
        if !cur.IsCurrent() {
                panic("registry: cross-realm admin call rejected")
        }
}

// IsInitialized reports whether the realm has been initialized.
func IsInitialized() bool {
        return admin != ""
}

// assertCore panics when the realm is used before Init.
func assertCore() {
        if admin == "" {
                panic("registry: realm not initialized")
        }
}

// Init initializes the realm. The caller of the deployment transaction
// becomes the protocol admin. Idempotent: a second call always panics.
func Init(cur realm) {
        if admin != "" {
                panic("registry: already initialized")
        }
        projects = make(map[string]*Project)
        components = make(map[string]*Component)
        registrars = make(map[string]bool)
        admin = cur.Previous().Address()
}

// SetAdmin transfers protocol admin to a new address. Only the current admin
// may call it.
func SetAdmin(cur realm, next address) {
        mustAdmin(cur)
        if !core.IsValidAddress(string(next)) {
                panic("registry: invalid admin address")
        }
        admin = next
}

// GrantRegistrar allow-lists an address to register projects. Only the
// protocol admin may grant registration rights.
func GrantRegistrar(cur realm, addr address) {
        mustAdmin(cur)
        if !core.IsValidAddress(string(addr)) {
                panic("registry: invalid registrar address")
        }
        registrars[string(addr)] = true
}

// RevokeRegistrar removes an address from the registrar allow-list.
func RevokeRegistrar(cur realm, addr address) {
        mustAdmin(cur)
        delete(registrars, string(addr))
}

// IsRegistrar reports whether addr may register projects (owner implicitly
// administers).
func IsRegistrar(addr address) bool {
        assertCore()
        if string(addr) == string(admin) {
                return true
        }
        return registrars[string(addr)]
}

// RegisterProject records a new project owned by the caller.
func RegisterProject(cur realm, id, name, description, repo, category, visibility string) {
        assertCore()
        caller := cur.Previous().Address()
        if !cur.IsCurrent() {
                panic("registry: project registration must run in current realm")
        }
        if !core.IsValidID(id) {
                panic("registry: invalid project id")
        }
        if _, ok := projects[id]; ok {
                panic("registry: project id already registered")
        }
        if !core.BoundedText(name, 128) || !core.BoundedText(description, core.MaxTextLen) ||
                !core.BoundedText(repo, 256) || !core.BoundedText(category, 64) {
                panic("registry: metadata exceeds size limits")
        }
        if name == "" {
                panic("registry: project name required")
        }
        if visibility != "public" && visibility != "private" {
                panic("registry: visibility must be public or private")
        }
        if !IsRegistrar(caller) {
                panic("registry: caller is not a registrar")
        }
        projects[id] = &Project{
                ID:          id,
                Name:        name,
                Description: description,
                Repo:        repo,
                Category:    category,
                Visibility:  visibility,
                Owner:       caller,
                CreatedAt:   time.Now().Unix(),
                Archived:    false,
        }
        projectIDs = append(projectIDs, id)
}

// TransferProject moves project ownership to a new address. Only the current
// owner may transfer.
func TransferProject(cur realm, id string, next address) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner {
                panic("registry: only the project owner may transfer ownership")
        }
        if !core.IsValidAddress(string(next)) {
                panic("registry: invalid target owner")
        }
        if string(next) == string(p.Owner) {
                panic("registry: target owner already owns project")
        }
        p.Owner = next
}

// SetProjectVisibility toggles public/private. Owner only.
func SetProjectVisibility(cur realm, id, visibility string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        if cur.Previous().Address() != p.Owner {
                panic("registry: only the project owner may change visibility")
        }
        if visibility != "public" && visibility != "private" {
                panic("registry: visibility must be public or private")
        }
        p.Visibility = visibility
}

// ArchiveProject soft-archives a project. Owner or protocol admin.
func ArchiveProject(cur realm, id string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner && caller != admin {
                panic("registry: not authorized to archive project")
        }
        p.Archived = true
}

// RestoreProject reactivates an archived project. Owner only.
func RestoreProject(cur realm, id string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        if cur.Previous().Address() != p.Owner {
                panic("registry: only the project owner may restore")
        }
        p.Archived = false
}

// RegisterComponent records a component under a project owned by the caller.
func RegisterComponent(cur realm, id, projectID, name, license, artifactType string) {
        assertCore()
        p, ok := projects[projectID]
        if !ok {
                panic("registry: unknown project")
        }
        if p.Archived {
                panic("registry: project is archived")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner {
                panic("registry: only the project owner may register components")
        }
        if !core.IsValidID(id) {
                panic("registry: invalid component id")
        }
        if _, exists := components[id]; exists {
                panic("registry: component id already registered")
        }
        if !core.BoundedText(name, 128) || !core.BoundedText(license, 64) || !core.BoundedText(artifactType, 32) {
                panic("registry: component metadata exceeds size limits")
        }
        validTypes := map[string]bool{"source": true, "container": true, "binary": true, "sbom": true, "docs": true, "library": true}
        if !validTypes[artifactType] {
                panic("registry: unsupported artifact type")
        }
        components[id] = &Component{
                ID:           id,
                ProjectID:    projectID,
                Name:         name,
                License:      license,
                ArtifactType: artifactType,
                Owner:        caller,
                CreatedAt:    time.Now().Unix(),
                Deprecated:   false,
        }
        componentIDs = append(componentIDs, id)
}

// DeprecateComponent marks a component deprecated. Owner only.
func DeprecateComponent(cur realm, id string) {
        assertCore()
        c, ok := components[id]
        if !ok {
                panic("registry: unknown component")
        }
        if cur.Previous().Address() != c.Owner {
                panic("registry: only the component owner may deprecate")
        }
        c.Deprecated = true
}

// HasProject reports existence regardless of visibility.
func HasProject(id string) bool {
        assertCore()
        _, ok := projects[id]
        return ok
}

// GetProject returns a copy of the project if it exists and is public, or
// the caller is the owner. Private projects are hidden from foreign readers.
func GetProject(id string) (Project, bool) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                return Project{}, false
        }
        return *p, true
}

// GetProjectFor checks visibility for a specific reader address.
func GetProjectFor(id string, reader address) (Project, bool) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                return Project{}, false
        }
        if p.Visibility == "private" && reader != p.Owner {
                return Project{}, false
        }
        return *p, true
}

// GetPublicProject returns the project only when public. Used by the verify
// realm and external consumers.
func GetPublicProject(id string) (Project, bool) {
        assertCore()
        p, ok := projects[id]
        if !ok || p.Visibility != "public" || p.Archived {
                return Project{}, false
        }
        return *p, true
}

// IsProjectOwner reports whether addr owns the given project.
func IsProjectOwner(id string, addr address) bool {
        assertCore()
        p, ok := projects[id]
        if !ok {
                return false
        }
        return p.Owner == addr
}

// GetComponent returns a copy of the component.
func GetComponent(id string) (Component, bool) {
        assertCore()
        c, ok := components[id]
        if !ok {
                return Component{}, false
        }
        return *c, true
}

// IsComponentOwner reports whether addr owns the component's project.
func IsComponentOwner(id string, addr address) bool {
        assertCore()
        c, ok := components[id]
        if !ok {
                return false
        }
        return c.Owner == addr
}

// ListProjectIDs returns all project IDs, newest first.
func ListProjectIDs() []string {
        assertCore()
        out := make([]string, len(projectIDs))
        copy(out, projectIDs)
        // newest first: reverse of registration order
        for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
                out[i], out[j] = out[j], out[i]
        }
        return out
}

// ListPublicProjectIDs returns IDs of public, non-archived projects, sorted
// for deterministic output.
func ListPublicProjectIDs() []string {
        assertCore()
        var out []string
        for _, id := range projectIDs {
                p := projects[id]
                if p != nil && p.Visibility == "public" && !p.Archived {
                        out = append(out, id)
                }
        }
        sort.Strings(out)
        return out
}

// ListComponentIDsByProject returns component IDs for a project, newest first.
func ListComponentIDsByProject(projectID string) []string {
        assertCore()
        var out []string
        for _, id := range componentIDs {
                if c := components[id]; c != nil && c.ProjectID == projectID {
                        out = append(out, id)
                }
        }
        for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
                out[i], out[j] = out[j], out[i]
        }
        return out
}

// ProjectCount returns the number of registered projects.
func ProjectCount() int {
        assertCore()
        return len(projectIDs)
}

// ComponentCount returns the number of registered components.
func ComponentCount() int {
        assertCore()
        return len(componentIDs)
}

// IsProtocolAdmin reports whether addr is the protocol admin. Other realms
// delegate admin decisions to the same root of trust.
func IsProtocolAdmin(addr address) bool {
        assertCore()
        return string(addr) == string(admin)
}

// ProtocolAdminAddress returns the current admin address.
func ProtocolAdminAddress() address {
        assertCore()
        return admin
}

// NormalizeRepo trims scheme and trailing slash for consistent repo keys.
func NormalizeRepo(repo string) string {
        r := strings.TrimSuffix(repo, "/")
        r = strings.TrimPrefix(r, "https://")
        r = strings.TrimPrefix(r, "http://")
        r = strings.TrimPrefix(r, "git@")
        return r
}

package registry

import (
	"testing"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

// expectAbort asserts that f aborts (panics) when executed. It relies on the
// gno `revive` builtin, which captures the panic value without unwinding the
// test frame — the sanctioned way to assert reverts on crossing calls.
func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

// NOTE: testing.SetRealm(...) is frame-local: it MUST be called inline within
// the test function body for the realm to apply to subsequent cross(cur)
// calls made from that frame.

func TestRegisterProjectFlow(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	before := ProjectCount()
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "core-api", "Core API", "Primary service", "github.com/example/core-api", "service", "public")

	if ProjectCount() != before+1 {
		t.Fatalf("expected project count to grow by 1, got %d -> %d", before, ProjectCount())
	}
	p, ok := GetPublicProject("core-api")
	if !ok {
		t.Fatal("project should be public readable")
	}
	if p.Owner != aliceAddr {
		t.Fatalf("owner mismatch: %s", p.Owner)
	}
	if p.CreatedAt <= 0 {
		t.Fatal("timestamp missing")
	}

	// duplicate registration must abort
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		RegisterProject(cross(cur), "core-api", "Dup", "", "", "", "public")
	})

	// invalid id must abort
	expectAbort(t, func() {
		RegisterProject(cross(cur), "INVALID ID", "Bad", "", "", "", "public")
	})
}

func TestUnauthorizedRegistration(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	// bob is not a registrar: must abort
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		RegisterProject(cross(cur), "bob-proj-x", "Bob", "", "", "", "public")
	})
}

func TestOwnershipTransfer(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "transfer-me", "Transfer", "", "", "", "public")

	// bob cannot transfer alice's project
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", bobAddr)
	})

	// owner transfers to bob
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	TransferProject(cross(cur), "transfer-me", bobAddr)
	if !IsProjectOwner("transfer-me", bobAddr) {
		t.Fatal("bob should now own project")
	}
	if IsProjectOwner("transfer-me", aliceAddr) {
		t.Fatal("alice should no longer own project")
	}

	// transfer to self must abort
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", bobAddr)
	})

	// transfer to invalid address must abort
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", address("not-an-address"))
	})
}

func TestComponentsAndVisibility(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "priv-proj", "Private", "", "", "", "private")
	RegisterComponent(cross(cur), "priv-proj-lib", "priv-proj", "lib", "MIT", "library")

	// foreign reader cannot see private project
	if _, ok := GetProjectFor("priv-proj", bobAddr); ok {
		t.Fatal("private project must be hidden from foreign readers")
	}
	if _, ok := GetPublicProject("priv-proj"); ok {
		t.Fatal("private project must not be public")
	}
	if _, ok := GetProjectFor("priv-proj", aliceAddr); !ok {
		t.Fatal("owner must see own private project")
	}

	// bob cannot register component on alice's project
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		RegisterComponent(cross(cur), "bob-lib-x", "priv-proj", "x", "", "library")
	})

	// invalid artifact type must abort
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		RegisterComponent(cross(cur), "bad-type-x", "priv-proj", "x", "", "quantum")
	})

	// duplicate component must abort
	expectAbort(t, func() {
		RegisterComponent(cross(cur), "priv-proj-lib", "priv-proj", "dup", "", "library")
	})

	// deprecate
	DeprecateComponent(cross(cur), "priv-proj-lib")
	c, ok := GetComponent("priv-proj-lib")
	if !ok || !c.Deprecated {
		t.Fatal("component should be deprecated")
	}

	// bob cannot deprecate
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		DeprecateComponent(cross(cur), "priv-proj-lib")
	})
}

func TestArchiveAndRestore(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "archive-me", "Archive", "", "", "", "public")

	ArchiveProject(cross(cur), "archive-me")
	if _, ok := GetPublicProject("archive-me"); ok {
		t.Fatal("archived public project must not be public")
	}
	if !HasProject("archive-me") {
		t.Fatal("archived project still exists")
	}
	RestoreProject(cross(cur), "archive-me")
	if _, ok := GetPublicProject("archive-me"); !ok {
		t.Fatal("restored project must be public again")
	}

	// bob cannot archive
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		ArchiveProject(cross(cur), "archive-me")
	})

	// bob cannot restore
	expectAbort(t, func() {
		RestoreProject(cross(cur), "archive-me")
	})
}

func TestAdminCannotBeUsurped(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	if !IsProtocolAdmin(adminAddr) {
		t.Fatal("admin should be the deployer")
	}

	// alice cannot elevate herself
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		SetAdmin(cross(cur), aliceAddr)
	})
	expectAbort(t, func() {
		GrantRegistrar(cross(cur), aliceAddr)
	})

	// admin CAN transfer admin, then original loses power
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	SetAdmin(cross(cur), bobAddr)
	if IsProtocolAdmin(adminAddr) {
		t.Fatal("old admin must lose power")
	}
	if !IsProtocolAdmin(bobAddr) {
		t.Fatal("bob must be admin")
	}

	// hand admin back to the deployer for the rest of the suite
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	SetAdmin(cross(cur), adminAddr)
	if !IsProtocolAdmin(adminAddr) {
		t.Fatal("admin handback failed")
	}
}

func TestListingDeterministic(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	ids := ListPublicProjectIDs()
	for i := 1; i < len(ids); i++ {
		if ids[i-1] > ids[i] {
			t.Fatalf("public ids not sorted: %v", ids)
		}
	}
	all := ListProjectIDs()
	if len(all) == 0 {
		t.Fatal("expected registered projects")
	}
	if !HasProject(all[0]) {
		t.Fatal("head of newest-first listing must exist")
	}

	if NormalizeRepo("https://github.com/x/y/") != "github.com/x/y" {
		t.Fatalf("NormalizeRepo broken: %s", NormalizeRepo("https://github.com/x/y/"))
	}
}

// Package releases is the on-chain release provenance engine of the
// PROOFLOOM protocol. It records release commitments and enforces the
// authoritative release state machine:
//
//	DRAFT -> EVIDENCE_PENDING -> VALIDATING -> REVIEW_REQUIRED ->
//	APPROVED -> PUBLISHED -> VERIFIED
//
// with terminal states REJECTED, REVOKED, SUPERSEDED and DISPUTED.
//
// A PUBLISHED record can never silently change: corrections require an
// explicit supersede or revocation, both of which are auditable state
// transitions in their own right.
//
// Authorization: every state-changing call is attributed to
// cur.Previous().Address() and must be the project owner (per the registry
// realm), the release publisher, or the protocol admin.
package releases

import (
	"sort"
	"time"

	core "gno.land/r/g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq/proofloom/core"
	reg "gno.land/r/g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq/proofloom/registry"
)

// Release is the durable on-chain record of a software release commitment.
type Release struct {
	ID             string
	ProjectID      string
	ComponentID    string
	Version        string
	Commit         string
	Branch         string
	Repo           string
	ArtifactDigest string
	Status         string
	Publisher      address
	CreatedAt      int64
	PublishedAt    int64
	SupersededBy   string
}

var releases map[string]*Release

// releaseOrder preserves creation order for deterministic listing.
var releaseIDs []string

func initialized() bool {
	return releases != nil
}

func ensure() {
	if releases == nil {
		panic("releases: realm not initialized")
	}
}

// Init seeds realm state. The registry realm must already be deployed and
// initialized: this realm relies on registry.IsProtocolAdmin for its root of
// trust, so there is no separate admin to configure here.
func Init(cur realm) {
	if initialized() {
		panic("releases: already initialized")
	}
	releases = make(map[string]*Release)
}

func caller(cur realm) address {
	return cur.Previous().Address()
}

func requireCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("releases: call must run in current realm")
	}
}

// authorized returns true when addr may act on the given release: as the
// release publisher, the project owner, or the protocol admin.
func authorized(r *Release, addr address) bool {
	if r.Publisher == addr {
		return true
	}
	if reg.IsProjectOwner(r.ProjectID, addr) {
		return true
	}
	if reg.IsProtocolAdmin(addr) {
		return true
	}
	return false
}

func getRelease(id string) *Release {
	r, ok := releases[id]
	if !ok {
		panic("releases: unknown release " + id)
	}
	return r
}

// CreateRelease starts a new release in DRAFT state. Caller must be the
// project owner. The release id is derived deterministically from project
// and version.
func CreateRelease(cur realm, projectID, version, commit, branch, repo, componentID string) string {
	ensure()
	requireCurrent(cur)
	if !reg.HasProject(projectID) {
		panic("releases: unknown project")
	}
	if !core.IsValidVersion(version) {
		panic("releases: invalid version")
	}
	if commit != "" && !core.IsValidShortHash(commit) {
		panic("releases: invalid commit hash")
	}
	if !core.BoundedText(branch, 128) || !core.BoundedText(repo, 256) || !core.BoundedText(componentID, 64) {
		panic("releases: field exceeds size limits")
	}
	id := core.ComposeReleaseID(projectID, version)
	if _, exists := releases[id]; exists {
		panic("releases: release already exists " + id)
	}
	// Authorization: only the project owner may create releases.
	if !reg.IsProjectOwner(projectID, caller(cur)) {
		panic("releases: only the project owner may create releases")
	}
	releases[id] = &Release{
		ID:          id,
		ProjectID:   projectID,
		ComponentID: componentID,
		Version:     version,
		Commit:      commit,
		Branch:      branch,
		Repo:        repo,
		Status:      core.ReleaseDraft,
		Publisher:   caller(cur),
		CreatedAt:   time.Now().Unix(),
	}
	releaseIDs = append(releaseIDs, id)
	return id
}

// SetEvidence attaches the build artifact digest and moves the release from
// DRAFT to EVIDENCE_PENDING, or from EVIDENCE_PENDING to VALIDATING when the
// digest changes. Digest correctness against artifacts is verified off-chain
// by the evidence worker; the chain stores the commitment.
func SetEvidence(cur realm, id, artifactDigest string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if !core.IsValidDigest(artifactDigest) {
		panic("releases: invalid artifact digest")
	}
	switch r.Status {
	case core.ReleaseDraft:
		r.Status = core.ReleaseEvidencePending
	case core.ReleaseEvidencePending:
		r.Status = core.ReleaseValidating
	default:
		panic("releases: cannot set evidence in state " + r.Status)
	}
	r.ArtifactDigest = artifactDigest
}

// MarkValidating records that automated validation started.
func MarkValidating(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseEvidencePending {
		panic("releases: expected EVIDENCE_PENDING, got " + r.Status)
	}
	r.Status = core.ReleaseValidating
}

// RequireReview moves a release into REVIEW_REQUIRED (policy or verifier
// decision).
func RequireReview(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseValidating {
		panic("releases: expected VALIDATING, got " + r.Status)
	}
	r.Status = core.ReleaseReviewRequired
}

// Approve authorizes the release for publication. Only REVIEW_REQUIRED and
// VALIDATING releases may be approved.
func Approve(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseReviewRequired && r.Status != core.ReleaseValidating {
		panic("releases: cannot approve from state " + r.Status)
	}
	r.Status = core.ReleaseApproved
}

// Reject terminates the release lifecycle. Terminal state.
func Reject(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status == core.ReleasePublished || r.Status == core.ReleaseVerified {
		panic("releases: published releases cannot be rejected; revoke instead")
	}
	r.Status = core.ReleaseRejected
}

// Publish commits the release on-chain. Requires APPROVED state and an
// attached artifact digest. Publish stamps the publication time and makes
// the record immutable except through Revoke/Supersede/Dispute.
func Publish(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseApproved {
		panic("releases: only APPROVED releases can be published")
	}
	if r.ArtifactDigest == "" {
		panic("releases: missing artifact digest")
	}
	r.Status = core.ReleasePublished
	r.PublishedAt = time.Now().Unix()
}

// MarkVerified records a successful verification pass over a published
// release. Only moves PUBLISHED -> VERIFIED.
func MarkVerified(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleasePublished {
		panic("releases: only PUBLISHED releases can be verified")
	}
	r.Status = core.ReleaseVerified
}

// Revoke withdraws a published release. Authorization: publisher, project
// owner, or protocol admin. Revoked releases remain publicly readable —
// revocation is a visible state, never a deletion.
func Revoke(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to revoke")
	}
	if r.Status != core.ReleasePublished && r.Status != core.ReleaseVerified {
		panic("releases: only published releases can be revoked")
	}
	r.Status = core.ReleaseRevoked
}

// Supersede marks a release replaced by a newer release of the same project.
// The superseding release must exist and be published.
func Supersede(cur realm, id, byID string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	nxt := getRelease(byID)
	if r.ProjectID != nxt.ProjectID {
		panic("releases: superseding release belongs to another project")
	}
	if nxt.Status != core.ReleasePublished && nxt.Status != core.ReleaseVerified {
		panic("releases: superseding release is not published")
	}
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to supersede")
	}
	r.Status = core.ReleaseSuperseded
	r.SupersededBy = byID
}

// Dispute flags a release as disputed (compliance or legal hold). Admin or
// project owner.
func Dispute(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to dispute")
	}
	if r.Status == core.ReleaseRevoked || r.Status == core.ReleaseSuperseded {
		panic("releases: terminal release cannot be disputed")
	}
	r.Status = core.ReleaseDisputed
}

// GetRelease returns a copy of a release if visible to the reader. Public
// visibility: any reader sees published/verified/revoked/superseded/disputed
// records; pre-publication states are visible to authorized parties only.
func GetRelease(id string, reader address) (Release, bool) {
	ensure()
	r, ok := releases[id]
	if !ok {
		return Release{}, false
	}
	if !isPublicState(r.Status) && !authorized(r, reader) {
		return Release{}, false
	}
	return *r, true
}

// HasRelease reports existence without visibility checks.
func HasRelease(id string) bool {
	ensure()
	_, ok := releases[id]
	return ok
}

func isPublicState(status string) bool {
	switch status {
	case core.ReleasePublished, core.ReleaseVerified, core.ReleaseRevoked,
		core.ReleaseSuperseded, core.ReleaseDisputed:
		return true
	}
	return false
}

// ReleaseStatus returns the current status of a release, or "" when unknown.
// Status is public metadata for every release (needed by external verifiers
// to check revocation without full record access).
func ReleaseStatus(id string) string {
	ensure()
	if r, ok := releases[id]; ok {
		return r.Status
	}
	return ""
}

// GetPublishedRelease returns the release only when in a published-family
// state, for external consumers.
func GetPublishedRelease(id string) (Release, bool) {
	ensure()
	r, ok := releases[id]
	if !ok || !isPublicState(r.Status) {
		return Release{}, false
	}
	return *r, true
}

// ListReleaseIDsByProject returns release ids of a project, newest first.
func ListReleaseIDsByProject(projectID string) []string {
	ensure()
	var out []string
	for _, id := range releaseIDs {
		if r := releases[id]; r != nil && r.ProjectID == projectID {
			out = append(out, id)
		}
	}
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

// FindByDigest returns published release ids whose artifact digest matches,
// sorted for deterministic output. This powers digest-based public
// verification.
func FindByDigest(digest string) []string {
	ensure()
	if !core.IsValidDigest(digest) {
		return nil
	}
	var out []string
	for _, id := range releaseIDs {
		if r := releases[id]; r != nil && r.ArtifactDigest == digest && isPublicState(r.Status) {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

// ReleaseCount returns the total number of releases.
func ReleaseCount() int {
	ensure()
	return len(releaseIDs)
}

// Initialized reports whether the releases realm has been initialized.
func Initialized() bool {
	return releases != nil
}

package releases

import (
	"testing"

	core "gno.land/r/g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq/proofloom/core"
	reg "gno.land/r/g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq/proofloom/registry"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

const digestA = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2"

func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

// seedRegistry initializes the registry realm (shared across test binaries)
// and registers a project owned by alice.
func seedProject(cur realm, projectID string) {
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !reg.IsInitialized() {
		reg.Init(cross(cur))
	}
	reg.GrantRegistrar(cross(cur), aliceAddr)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	if !reg.HasProject(projectID) {
		reg.RegisterProject(cross(cur), projectID, "Proj", "desc", "github.com/example/proj", "service", "public")
	}
}

func TestReleaseStateMachine(cur realm, t *testing.T) {
	seedProject(cur, "sm-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id := CreateRelease(cross(cur), "sm-proj", "1.0.0", "abc1234", "main", "github.com/example/proj", "")

	if id != "sm-proj-1.0.0" {
		t.Fatalf("unexpected release id %s", id)
	}

	// pre-publication states are hidden from foreign readers
	if _, ok := GetRelease(id, bobAddr); ok {
		t.Fatal("draft release must be hidden from foreign readers")
	}
	if _, ok := GetRelease(id, aliceAddr); !ok {
		t.Fatal("publisher must see own draft release")
	}

	// publish without evidence must abort
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		Publish(cross(cur), id)
	})

	SetEvidence(cross(cur), id, digestA)
	r, _ := GetRelease(id, aliceAddr)
	if r.Status != core.ReleaseEvidencePending {
		t.Fatalf("expected EVIDENCE_PENDING, got %s", r.Status)
	}

	// invalid digest aborts
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		SetEvidence(cross(cur), id, "nothex")
	})

	// full happy path
	MarkValidating(cross(cur), id)
	RequireReview(cross(cur), id)
	Approve(cross(cur), id)
	Publish(cross(cur), id)

	r, _ = GetRelease(id, bobAddr)
	if r.Status != core.ReleasePublished {
		t.Fatalf("expected PUBLISHED, got %s", r.Status)
	}
	if r.PublishedAt <= 0 {
		t.Fatal("publication timestamp missing")
	}

	// published records are public
	if _, ok := GetRelease(id, bobAddr); !ok {
		t.Fatal("published release must be public")
	}
	if ReleaseStatus(id) != core.ReleasePublished {
		t.Fatal("status query broken")
	}

	MarkVerified(cross(cur), id)
	if ReleaseStatus(id) != core.ReleaseVerified {
		t.Fatal("expected VERIFIED")
	}

	// digest lookup must find it
	found := FindByDigest(digestA)
	if len(found) != 1 || found[0] != id {
		t.Fatalf("digest lookup failed: %v", found)
	}
}

func TestReleaseAuthorization(cur realm, t *testing.T) {
	seedProject(cur, "authz-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	// bob cannot create releases on alice's project
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		CreateRelease(cross(cur), "authz-proj", "0.1.0", "abc1234", "main", "", "")
	})

	// alice creates; bob cannot touch it
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id := CreateRelease(cross(cur), "authz-proj", "0.2.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id, digestA)

	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		Approve(cross(cur), id)
	})
	expectAbort(t, func() {
		Revoke(cross(cur), id)
	})

	// admin CAN act (protocol admin override)
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	MarkValidating(cross(cur), id)
	Approve(cross(cur), id)
	Publish(cross(cur), id)

	// invalid transition: approve after publish
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		Approve(cross(cur), id)
	})
}

func TestRevokeAndSupersede(cur realm, t *testing.T) {
	seedProject(cur, "rv-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id1 := CreateRelease(cross(cur), "rv-proj", "2.0.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id1, digestA)
	MarkValidating(cross(cur), id1)
	Approve(cross(cur), id1)
	Publish(cross(cur), id1)

	id2 := CreateRelease(cross(cur), "rv-proj", "2.1.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id2, digestA)
	MarkValidating(cross(cur), id2)
	Approve(cross(cur), id2)
	Publish(cross(cur), id2)

	// supersede 2.0.0 with 2.1.0
	Supersede(cross(cur), id1, id2)
	r1, _ := GetRelease(id1, bobAddr)
	if r1.Status != core.ReleaseSuperseded || r1.SupersededBy != id2 {
		t.Fatalf("supersede failed: %s -> %s", r1.Status, r1.SupersededBy)
	}

	// cross-project supersede must abort
	idX := CreateRelease(cross(cur), "sm-proj", "9.9.9", "abc1234", "main", "", "")
	SetEvidence(cross(cur), idX, digestA)
	MarkValidating(cross(cur), idX)
	Approve(cross(cur), idX)
	Publish(cross(cur), idX)
	expectAbort(t, func() {
		Supersede(cross(cur), id2, idX)
	})

	// revoke remains publicly visible
	Revoke(cross(cur), id2)
	r2, ok := GetRelease(id2, bobAddr)
	if !ok || r2.Status != core.ReleaseRevoked {
		t.Fatalf("revoked release must remain visible: %v %s", ok, r2.Status)
	}
}

// Package tavern implements the Gnome Tavern Quests & Verifiable Escrow Realm on Gno.land.
// Sponsors lock ugnot bounties into realm escrow with deterministic deadline and arbitration
// invariants; guild builders claim quests, submit 64-hex SHA-256 proof digests, and settle
// payouts without double-spend or off-chain custodians.
package tavern

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

const (
	DenomUgnot = "ugnot"

	StatusOpen      = "OPEN"
	StatusClaimed   = "CLAIMED"
	StatusSubmitted = "SUBMITTED"
	StatusDisputed  = "DISPUTED"
	StatusSettled   = "SETTLED"
	StatusRefunded  = "REFUNDED"
)

// Quest represents an escrowed work order tracked deterministically on-chain.
type Quest struct {
	ID                 uint64
	Title              string
	SpecHash           string
	AcceptanceCriteria string
	Sponsor            address
	Arbitrator         address
	Worker             address
	BountyUgnot        int64
	CreatedHeight      int64
	DeadlineHeight     int64
	Status             string
	WorkerNote         string
	ProofSHA256        string
	ProofURI           string
	DisputeReason      string
}

// GuildStats tracks verified on-chain settlement history per builder address.
type GuildStats struct {
	Address     address
	Completed   uint64
	DisputesWon uint64
	EarnedUgnot int64
}

var (
	nextQuestID uint64
	quests      []*Quest
	guildBoard  []*GuildStats
	totalLocked int64
	totalPaid   int64
)

func resetStateForTests() {
	nextQuestID = 0
	quests = nil
	guildBoard = nil
	totalLocked = 0
	totalPaid = 0
}

func isSafeProofURI(uri string) bool {
	if strings.ContainsAny(uri, "\r\n\t ") {
		return false
	}
	lower := strings.ToLower(uri)
	return strings.HasPrefix(lower, "https://") ||
		strings.HasPrefix(lower, "ipfs://") ||
		strings.HasPrefix(lower, "ar://") ||
		strings.HasPrefix(lower, "gno.land/")
}

func sanitizeMarkdownCell(s string) string {
	r := strings.NewReplacer("|", "/", "\r", " ", "\n", " ")
	return strings.TrimSpace(r.Replace(s))
}

func isValidHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		isDigit := c >= '0' && c <= '9'
		isHex := c >= 'a' && c <= 'f'
		if !isDigit && !isHex {
			return false
		}
	}
	return true
}

func findQuest(questID uint64) *Quest {
	if questID == 0 || questID > uint64(len(quests)) {
		panic("quest not found")
	}
	q := quests[questID-1]
	if q == nil || q.ID != questID {
		panic("quest index mismatch")
	}
	return q
}

func recordGuildPayout(worker address, amount int64, viaDispute bool) {
	for i := 0; i < len(guildBoard); i++ {
		if guildBoard[i].Address == worker {
			guildBoard[i].Completed++
			if viaDispute {
				guildBoard[i].DisputesWon++
			}
			guildBoard[i].EarnedUgnot += amount
			return
		}
	}
	var dw uint64
	if viaDispute {
		dw = 1
	}
	guildBoard = append(guildBoard, &GuildStats{
		Address:     worker,
		Completed:   1,
		DisputesWon: dw,
		EarnedUgnot: amount,
	})
}

// PostQuest locks the caller's sent ugnot into realm escrow and opens a new quest.
func PostQuest(
	cur realm,
	title string,
	specHash string,
	acceptanceCriteria string,
	arbitrator address,
	deadlineHeight int64,
) uint64 {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	title = strings.TrimSpace(title)
	if title == "" {
		panic("title must be non-empty")
	}
	if !isValidHex64(specHash) {
		panic("specHash must be 64 lowercase hex characters")
	}
	if strings.TrimSpace(acceptanceCriteria) == "" {
		panic("acceptanceCriteria must be non-empty")
	}
	if arbitrator == "" || !arbitrator.IsValid() {
		panic("arbitrator address must be valid bech32")
	}
	if arbitrator == cur.Address() {
		panic("arbitrator cannot be realm address")
	}

	nowHeight := runtime.ChainHeight()
	if deadlineHeight <= nowHeight {
		panic("deadlineHeight must be strictly greater than current chain height")
	}

	sent := unsafe.OriginSend()
	bounty := sent.AmountOf(DenomUgnot)
	if bounty <= 0 {
		panic("must attach positive ugnot bounty")
	}

	sponsor := cur.Previous().Address()
	if sponsor == arbitrator {
		panic("arbitrator must be distinct from sponsor")
	}

	nextQuestID++
	q := &Quest{
		ID:                 nextQuestID,
		Title:              title,
		SpecHash:           specHash,
		AcceptanceCriteria: strings.TrimSpace(acceptanceCriteria),
		Sponsor:            sponsor,
		Arbitrator:         arbitrator,
		BountyUgnot:        bounty,
		CreatedHeight:      nowHeight,
		DeadlineHeight:     deadlineHeight,
		Status:             StatusOpen,
	}
	quests = append(quests, q)
	totalLocked += bounty

	chain.Emit(
		"QuestPosted",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"sponsor", string(sponsor),
		"bounty_ugnot", strconv.FormatInt(bounty, 10),
	)
	return q.ID
}

// ClaimQuest assigns an OPEN quest to the calling guild worker.
func ClaimQuest(cur realm, questID uint64, workerNote string) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusOpen {
		panic("quest is not open")
	}
	if runtime.ChainHeight() > q.DeadlineHeight {
		panic("quest deadline has passed")
	}
	caller := cur.Previous().Address()
	if caller == q.Sponsor {
		panic("sponsor cannot claim own quest")
	}
	if caller == q.Arbitrator {
		panic("arbitrator cannot claim quest")
	}

	q.Worker = caller
	q.WorkerNote = strings.TrimSpace(workerNote)
	q.Status = StatusClaimed

	chain.Emit(
		"QuestClaimed",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"worker", string(caller),
	)
}

// SubmitProof attaches a verifiable 64-hex SHA-256 artifact digest and proof URI.
func SubmitProof(cur realm, questID uint64, artifactSHA256 string, proofURI string) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusClaimed {
		panic("quest is not claimed")
	}
	caller := cur.Previous().Address()
	if caller != q.Worker {
		panic("only assigned worker can submit proof")
	}
	if runtime.ChainHeight() > q.DeadlineHeight {
		panic("quest deadline has passed")
	}
	if !isValidHex64(artifactSHA256) {
		panic("artifactSHA256 must be 64 lowercase hex characters")
	}
	proofURI = strings.TrimSpace(proofURI)
	if !isSafeProofURI(proofURI) {
		panic("proofURI must use https://, ipfs://, ar://, or gno.land/ prefix")
	}

	q.ProofSHA256 = artifactSHA256
	q.ProofURI = proofURI
	q.Status = StatusSubmitted

	chain.Emit(
		"ProofSubmitted",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"worker", string(caller),
		"sha256", artifactSHA256,
	)
}

// ApproveAndRelease lets the sponsor release escrowed ugnot to the worker after proof review.
func ApproveAndRelease(cur realm, questID uint64) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusSubmitted {
		panic("quest must be in SUBMITTED state to release")
	}
	caller := cur.Previous().Address()
	if caller != q.Sponsor {
		panic("only sponsor can approve and release")
	}

	// Checks-Effects-Interactions: update state before bank transfer.
	payout := q.BountyUgnot
	q.Status = StatusSettled
	totalLocked -= payout
	totalPaid += payout
	recordGuildPayout(q.Worker, payout, false)

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), q.Worker, chain.NewCoins(chain.NewCoin(DenomUgnot, payout)))

	chain.Emit(
		"QuestSettled",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"worker", string(q.Worker),
		"bounty_ugnot", strconv.FormatInt(payout, 10),
	)
}

// OpenDispute lets either the sponsor or worker escalate a SUBMITTED quest to the arbitrator.
func OpenDispute(cur realm, questID uint64, reason string) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusSubmitted {
		panic("dispute requires SUBMITTED status")
	}
	caller := cur.Previous().Address()
	if caller != q.Sponsor && caller != q.Worker {
		panic("only sponsor or assigned worker can open dispute")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("dispute reason must be non-empty")
	}

	q.DisputeReason = reason
	q.Status = StatusDisputed

	chain.Emit(
		"QuestDisputed",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"by", string(caller),
	)
}

// ResolveDispute lets the designated arbitrator settle a DISPUTED quest to worker or sponsor.
func ResolveDispute(cur realm, questID uint64, awardToWorker bool) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusDisputed {
		panic("quest is not in DISPUTED state")
	}
	caller := cur.Previous().Address()
	if caller != q.Arbitrator {
		panic("only designated arbitrator can resolve dispute")
	}

	amount := q.BountyUgnot
	totalLocked -= amount
	var recipient address
	if awardToWorker {
		q.Status = StatusSettled
		totalPaid += amount
		recipient = q.Worker
		recordGuildPayout(q.Worker, amount, true)
	} else {
		q.Status = StatusRefunded
		recipient = q.Sponsor
	}

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), recipient, chain.NewCoins(chain.NewCoin(DenomUgnot, amount)))

	chain.Emit(
		"DisputeResolved",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"recipient", string(recipient),
		"amount_ugnot", strconv.FormatInt(amount, 10),
	)
}

// CancelExpired refunds escrowed ugnot to the sponsor once deadlineHeight passes without submission.
func CancelExpired(cur realm, questID uint64) {
	if !cur.Previous().IsUserCall() {
		panic("only direct user calls accepted")
	}
	q := findQuest(questID)
	if q.Status != StatusOpen && q.Status != StatusClaimed {
		panic("only OPEN or CLAIMED quests can expire")
	}
	caller := cur.Previous().Address()
	if caller != q.Sponsor {
		panic("only sponsor can cancel expired quest")
	}
	if runtime.ChainHeight() <= q.DeadlineHeight {
		panic("quest has not expired yet")
	}

	refund := q.BountyUgnot
	q.Status = StatusRefunded
	totalLocked -= refund

	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), q.Sponsor, chain.NewCoins(chain.NewCoin(DenomUgnot, refund)))

	chain.Emit(
		"QuestRefunded",
		"quest_id", strconv.FormatUint(q.ID, 10),
		"sponsor", string(q.Sponsor),
		"refund_ugnot", strconv.FormatInt(refund, 10),
	)
}

// TotalEscrowLocked returns the tracked total ugnot currently locked in active quests.
func TotalEscrowLocked() int64 {
	return totalLocked
}

// TotalSettledUgnot returns cumulative ugnot paid to guild builders.
func TotalSettledUgnot() int64 {
	return totalPaid
}

// QuestCount returns the total number of quests ever posted.
func QuestCount() uint64 {
	return nextQuestID
}

// ComputeActiveEscrowSum recomputes locked escrow directly from quest records for invariant checks.
func ComputeActiveEscrowSum() int64 {
	var sum int64
	for i := 0; i < len(quests); i++ {
		q := quests[i]
		if q.Status == StatusOpen || q.Status == StatusClaimed || q.Status == StatusSubmitted || q.Status == StatusDisputed {
			sum += q.BountyUgnot
		}
	}
	return sum
}

// Render serves the gnoweb Markdown interface for "", "quest/<id>", and "guild".
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	if path == "guild" {
		return renderGuild()
	}
	if strings.HasPrefix(path, "quest/") {
		idStr := strings.TrimPrefix(path, "quest/")
		id, err := strconv.ParseUint(idStr, 10, 64)
		if err != nil || id == 0 || id > uint64(len(quests)) {
			return "# Quest Not Found\n\nNo quest exists for path `" + path + "`.\n"
		}
		return renderQuest(quests[id-1])
	}
	return "# Gnome Tavern\n\nUnknown route `" + path + "`. Try `/` or `/guild`.\n"
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Gnome Tavern Quests & Verifiable Escrow\n\n")
	b.WriteString("Deterministic on-chain quest ledger on Gno.land (`gno.land/r/nym-tavern247/tavern`).\n\n")
	b.WriteString("- **Quests Posted:** " + strconv.FormatUint(nextQuestID, 10) + "\n")
	b.WriteString("- **Active Escrow Locked:** " + strconv.FormatInt(totalLocked, 10) + " ugnot\n")
	b.WriteString("- **Cumulative Settled:** " + strconv.FormatInt(totalPaid, 10) + " ugnot\n")
	b.WriteString("- **Conservation Check:** `totalLocked == sum(active)` -> `" + strconv.FormatBool(totalLocked == ComputeActiveEscrowSum()) + "`\n\n")
	b.WriteString("[View Guild Reputation Board](/r/nym-tavern247/tavern:guild)\n\n")

	if len(quests) == 0 {
		b.WriteString("_No quests posted yet._\n")
		return b.String()
	}

	b.WriteString("## Active & Historical Quests\n\n")
	b.WriteString("| ID | Title | Bounty (ugnot) | Status | Deadline Height |\n")
	b.WriteString("| :--- | :--- | ---: | :--- | ---: |\n")
	for i := len(quests) - 1; i >= 0; i-- {
		q := quests[i]
		idStr := strconv.FormatUint(q.ID, 10)
		b.WriteString("| [#" + idStr + "](/r/nym-tavern247/tavern:quest/" + idStr + ") | " + sanitizeMarkdownCell(q.Title) + " | " + strconv.FormatInt(q.BountyUgnot, 10) + " | " + q.Status + " | " + strconv.FormatInt(q.DeadlineHeight, 10) + " |\n")
	}
	return b.String()
}

func renderQuest(q *Quest) string {
	var b strings.Builder
	idStr := strconv.FormatUint(q.ID, 10)
	b.WriteString("# Quest #" + idStr + ": " + q.Title + "\n\n")
	b.WriteString("- **Status:** " + q.Status + "\n")
	b.WriteString("- **Bounty:** " + strconv.FormatInt(q.BountyUgnot, 10) + " ugnot\n")
	b.WriteString("- **Sponsor:** `" + string(q.Sponsor) + "`\n")
	b.WriteString("- **Arbitrator:** `" + string(q.Arbitrator) + "`\n")
	if q.Worker != "" {
		b.WriteString("- **Worker:** `" + string(q.Worker) + "`\n")
	}
	b.WriteString("- **Spec SHA-256:** `" + q.SpecHash + "`\n")
	b.WriteString("- **Acceptance Criteria:** " + q.AcceptanceCriteria + "\n")
	b.WriteString("- **Deadline Height:** " + strconv.FormatInt(q.DeadlineHeight, 10) + "\n")
	if q.ProofSHA256 != "" {
		b.WriteString("- **Submitted Proof SHA-256:** `" + q.ProofSHA256 + "`\n")
		b.WriteString("- **Proof URI:** " + q.ProofURI + "\n")
	}
	if q.DisputeReason != "" {
		b.WriteString("- **Dispute Reason:** " + q.DisputeReason + "\n")
	}
	b.WriteString("\n[Back to Tavern Ledger](/r/nym-tavern247/tavern)\n")
	return b.String()
}

func renderGuild() string {
	var b strings.Builder
	b.WriteString("# Gnome Tavern Guild Reputation Board\n\n")
	if len(guildBoard) == 0 {
		b.WriteString("_No settled quests yet._\n\n[Back to Tavern Ledger](/r/nym-tavern247/tavern)\n")
		return b.String()
	}
	b.WriteString("| Builder | Completed | Disputes Won | Earned (ugnot) |\n")
	b.WriteString("| :--- | ---: | ---: | ---: |\n")
	for i := 0; i < len(guildBoard); i++ {
		g := guildBoard[i]
		b.WriteString("| `" + string(g.Address) + "` | " + strconv.FormatUint(g.Completed, 10) + " | " + strconv.FormatUint(g.DisputesWon, 10) + " | " + strconv.FormatInt(g.EarnedUgnot, 10) + " |\n")
	}
	b.WriteString("\n[Back to Tavern Ledger](/r/nym-tavern247/tavern)\n")
	return b.String()
}

package tavern

import (
	"chain"
	"chain/runtime"
	"strings"
	"testing"
)

const (
	validSpecHash  = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
	validProofHash = "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08"
)

var (
	addrSponsor    = chain.PackageAddress("gno.land/r/gnometavern/test_sponsor")
	addrWorker     = chain.PackageAddress("gno.land/r/gnometavern/test_worker")
	addrArbitrator = chain.PackageAddress("gno.land/r/gnometavern/test_arbitrator")
	addrIntruder   = chain.PackageAddress("gno.land/r/gnometavern/test_intruder")
)

func assertPanics(t *testing.T, label string, fn func()) {
	t.Helper()
	if ex := revive(fn); ex == nil {
		t.Fatalf("%s: expected panic/abort, but call succeeded", label)
	}
}

func TestHappyPathLifecycleAndEscrowConservation(cur realm, t *testing.T) {
	resetStateForTests()
	pkgAddr := chain.PackageAddress("gno.land/r/nym-tavern247/tavern")
	testing.IssueCoins(pkgAddr, chain.NewCoins(chain.NewCoin(DenomUgnot, 50_000_000)))

	// 1. Sponsor posts quest with 1,000,000 ugnot escrow; invalid or self-realm arbitrator rejected.
	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(DenomUgnot, 1_000_000)))
	deadline := runtime.ChainHeight() + 50
	assertPanics(t, "invalid bech32 arbitrator", func() {
		PostQuest(cross(cur), "Bad Arb", validSpecHash, "Criteria", address("not_a_valid_bech32"), deadline)
	})
	assertPanics(t, "self-realm arbitrator", func() {
		PostQuest(cross(cur), "Realm Arb", validSpecHash, "Criteria", pkgAddr, deadline)
	})
	qid := PostQuest(
		cross(cur),
		"Deterministic Gno Escrow Verifier | v1",
		validSpecHash,
		"All unit tests and conservation invariants pass",
		addrArbitrator,
		deadline,
	)
	if qid != 1 {
		t.Fatalf("expected quest id 1, got %d", qid)
	}
	if TotalEscrowLocked() != 1_000_000 || ComputeActiveEscrowSum() != 1_000_000 {
		t.Fatalf("escrow mismatch after post: locked=%d sum=%d", TotalEscrowLocked(), ComputeActiveEscrowSum())
	}

	// 2. Unauthorized actor cannot claim if sponsor, worker claims cleanly.
	assertPanics(t, "sponsor self-claim", func() {
		ClaimQuest(cross(cur), qid, "self")
	})
	testing.SetRealm(testing.NewUserRealm(addrWorker))
	ClaimQuest(cross(cur), qid, "Implementing deterministic state machine")

	// 3. Invalid SHA-256 proof and unsafe URI schemes rejected; valid 64-hex SHA-256 + https succeeds.
	assertPanics(t, "short proof hash", func() {
		SubmitProof(cross(cur), qid, "deadbeef", "https://github.com/HindsightWise/gnome-tavern")
	})
	assertPanics(t, "javascript proof URI", func() {
		SubmitProof(cross(cur), qid, validProofHash, "javascript:alert(1)")
	})
	SubmitProof(cross(cur), qid, validProofHash, "https://github.com/HindsightWise/gnome-tavern")

	// 4. Intruder cannot release funds.
	testing.SetRealm(testing.NewUserRealm(addrIntruder))
	assertPanics(t, "intruder release", func() {
		ApproveAndRelease(cross(cur), qid)
	})

	// 5. Sponsor approves and releases escrowed ugnot; double release panics.
	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	ApproveAndRelease(cross(cur), qid)
	if TotalEscrowLocked() != 0 || ComputeActiveEscrowSum() != 0 {
		t.Fatalf("escrow not zero after settlement: locked=%d sum=%d", TotalEscrowLocked(), ComputeActiveEscrowSum())
	}
	if TotalSettledUgnot() != 1_000_000 {
		t.Fatalf("expected settled=1000000, got %d", TotalSettledUgnot())
	}
	assertPanics(t, "double release", func() {
		ApproveAndRelease(cross(cur), qid)
	})

	// 6. Verify gnoweb Render routes and Markdown table sanitization.
	home := Render("")
	if !strings.Contains(home, "Deterministic Gno Escrow Verifier / v1") || !strings.Contains(home, "SETTLED") {
		t.Fatalf("unexpected home render: %s", home)
	}
	detail := Render("quest/1")
	if !strings.Contains(detail, validProofHash) {
		t.Fatalf("detail render missing proof hash: %s", detail)
	}
	guild := Render("guild")
	if !strings.Contains(guild, string(addrWorker)) || !strings.Contains(guild, "1000000") {
		t.Fatalf("guild render missing worker payout: %s", guild)
	}
}

func TestDisputeResolutionBothOutcomes(cur realm, t *testing.T) {
	resetStateForTests()
	pkgAddr := chain.PackageAddress("gno.land/r/nym-tavern247/tavern")
	testing.IssueCoins(pkgAddr, chain.NewCoins(chain.NewCoin(DenomUgnot, 50_000_000)))

	// Quest 1: Dispute awarded to worker.
	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(DenomUgnot, 750_000)))
	q1 := PostQuest(cross(cur), "Audit Parser", validSpecHash, "Zero panics", addrArbitrator, runtime.ChainHeight()+40)

	testing.SetRealm(testing.NewUserRealm(addrWorker))
	ClaimQuest(cross(cur), q1, "Starting audit")
	SubmitProof(cross(cur), q1, validProofHash, "ipfs://bafyproof1")
	OpenDispute(cross(cur), q1, "Sponsor delayed approval past review window")

	// Non-arbitrator cannot resolve.
	assertPanics(t, "worker resolve dispute", func() {
		ResolveDispute(cross(cur), q1, true)
	})

	testing.SetRealm(testing.NewUserRealm(addrArbitrator))
	ResolveDispute(cross(cur), q1, true)
	if TotalEscrowLocked() != 0 || TotalSettledUgnot() != 750_000 {
		t.Fatalf("unexpected state after worker dispute win: locked=%d paid=%d", TotalEscrowLocked(), TotalSettledUgnot())
	}

	// Quest 2: Dispute refunded to sponsor.
	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(DenomUgnot, 500_000)))
	q2 := PostQuest(cross(cur), "Indexer Hook", validSpecHash, "Matches schema", addrArbitrator, runtime.ChainHeight()+40)

	testing.SetRealm(testing.NewUserRealm(addrWorker))
	ClaimQuest(cross(cur), q2, "On it")
	SubmitProof(cross(cur), q2, validProofHash, "ipfs://bafyproof2")

	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	OpenDispute(cross(cur), q2, "Artifact fails schema invariant")

	testing.SetRealm(testing.NewUserRealm(addrArbitrator))
	ResolveDispute(cross(cur), q2, false)
	if TotalEscrowLocked() != 0 || TotalSettledUgnot() != 750_000 {
		t.Fatalf("unexpected state after sponsor refund: locked=%d paid=%d", TotalEscrowLocked(), TotalSettledUgnot())
	}
	if ComputeActiveEscrowSum() != TotalEscrowLocked() {
		t.Fatalf("conservation invariant broken")
	}
}

func TestExpiredQuestRefund(cur realm, t *testing.T) {
	resetStateForTests()
	pkgAddr := chain.PackageAddress("gno.land/r/nym-tavern247/tavern")
	testing.IssueCoins(pkgAddr, chain.NewCoins(chain.NewCoin(DenomUgnot, 50_000_000)))

	testing.SetRealm(testing.NewUserRealm(addrSponsor))
	testing.SetOriginSend(chain.NewCoins(chain.NewCoin(DenomUgnot, 250_000)))
	deadline := runtime.ChainHeight() + 10
	qid := PostQuest(cross(cur), "Expired Task", validSpecHash, "Complete before height", addrArbitrator, deadline)

	// Cannot cancel before deadline.
	assertPanics(t, "early cancel", func() {
		CancelExpired(cross(cur), qid)
	})

	testing.SkipHeights(15)
	CancelExpired(cross(cur), qid)
	if TotalEscrowLocked() != 0 || ComputeActiveEscrowSum() != 0 {
		t.Fatalf("escrow not cleared after expiry refund")
	}
}

// Package lastcall is a price prediction game settled by Tapster.
//
// Every new Tapster answer for a feed opens a game. While that answer is
// the latest one, anyone can bet GNOT that the price will be higher (UP) or
// lower (DOWN) a few oracle rounds later. Once Tapster has published an
// answer at least settleAfter rounds newer, anyone can settle the game and
// earns a small tip for doing it. Winners split the whole pot in
// proportion to their bets. Ties, games with only one side and games
// nobody settled in time are refunded in full.
//
// There is no keeper, no house edge and no admin over the funds: the only
// inputs are bets and Tapster prices.
package lastcall

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapmath/v0"
	"gno.land/r/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapster/v0"
)

const (
	ugnot = "ugnot"

	minBet      int64 = 100000      // 0.1 GNOT
	maxBet      int64 = 100000000   // 100 GNOT per address per game
	maxPot      int64 = 10000000000 // 10,000 GNOT per game keeps payout math in int64
	maxPriceAge int64 = 600         // a game only opens on a price at most 10 minutes old

	settleAfter = 3  // settle on an answer at least 3 oracle rounds after the game's
	voidAfter   = 12 // after 12 rounds without settlement the game is refunded

	tipBps int64 = 50      // settler earns 0.5% of the pot...
	maxTip int64 = 1000000 // ...capped at 1 GNOT
)

// Outcomes.
const (
	Open      = "open"
	Up        = "up"
	Down      = "down"
	Tie       = "tie"       // refunded
	OneSided  = "one-sided" // refunded
	Unsettled = "expired"   // refunded
)

// Position is one address's bet in a game.
type Position struct {
	Addr    address
	Up      bool
	Amount  int64
	Claimed bool
	Payout  int64
}

// Game is one prediction round for one feed.
type Game struct {
	Pair       string
	Round      int64 // Tapster round the game opened on
	StartPrice int64
	Decimals   int
	OpenedAt   int64
	UpPot      int64
	DownPot    int64
	Bettors    int

	Outcome   string
	EndRound  int64
	EndPrice  int64
	SettledAt int64
	Settler   address
	Tip       int64
	Payable   int64 // pot minus tip, shared by the winners

	bets *avl.Tree // address -> *Position
}

// Player keeps lifetime stats for the leaderboard.
type Player struct {
	Addr    address
	Bets    int
	Wagered int64
	Won     int64 // total payouts received, including returned stakes
	Wins    int
}

var (
	games   = avl.NewTree() // gameKey -> *Game
	players = avl.NewTree() // address -> *Player
	open    = avl.NewTree() // gameKey of unsettled games

	totalGames   int
	totalBets    int
	totalVolume  int64
	totalSettled int
	settledLog   []string // gameKeys in settlement order, newest last (max 100)
)

func init(cur realm) {
	tapster.RegisterConsumer(cross(cur), "Last Call: UP/DOWN price game")
}

func now() int64 { return time.Now().Unix() }

func gameKey(pair string, round int64) string {
	return pair + ":" + ufmt.Sprintf("%016d", round)
}

func mustGame(pair string, round int64) *Game {
	v := games.Get(gameKey(pair, round))
	if v == nil {
		panic("no such game")
	}
	return v.(*Game)
}

func assertCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
}

func player(a address) *Player {
	if v := players.Get(a.String()); v != nil {
		return v.(*Player)
	}
	p := &Player{Addr: a}
	players.Set(a.String(), p)
	return p
}

// mulDiv returns a*b/c for 0 <= a <= maxBet and 0 <= b, c <= maxPot
// without overflowing int64.
func mulDiv(a, b, c int64) int64 {
	q, r := b/c, b%c
	return a*q + a*r/c
}

// ----------------------------------------------------------------------
// Playing

// Bet stakes the GNOT sent with the call on the price of pair going up
// (up=true) or down by the time the game settles. The game is the one for
// the latest Tapster answer; adding to an existing bet is allowed, but not
// switching sides. Returns the Tapster round of the game.
func Bet(cur realm, pair string, up bool) int64 {
	assertCurrent(cur)
	// IsUserCall + OriginSend are a pair: only for a direct call from an
	// account are the -send coins guaranteed to have reached this realm.
	if !cur.Previous().IsUserCall() {
		panic("bet directly from an account")
	}
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != ugnot {
			panic("only ugnot is accepted")
		}
	}
	amount := sent.AmountOf(ugnot)
	if amount < minBet {
		panic("minimum bet is 0.1 GNOT (100000ugnot)")
	}

	price, dec, at, round, ok := tapster.Latest(pair)
	if !ok {
		panic("Tapster has no price for " + pair + " yet")
	}
	if now()-at > maxPriceAge {
		panic("the " + pair + " price is stale; games open again when Tapster updates")
	}

	key := gameKey(pair, round)
	var g *Game
	if v := games.Get(key); v != nil {
		g = v.(*Game)
	} else {
		g = &Game{Pair: pair, Round: round, StartPrice: price, Decimals: dec, OpenedAt: now(), Outcome: Open, bets: avl.NewTree()}
	}
	if g.Outcome != Open {
		panic("game already settled")
	}
	if g.UpPot+g.DownPot+amount > maxPot {
		panic("this game's pot is full")
	}
	caller := cur.Previous().Address()
	var b *Position
	if v := g.bets.Get(caller.String()); v != nil {
		b = v.(*Position)
		if b.Up != up {
			panic("you already bet the other way in this game")
		}
	}
	if b == nil {
		if amount > maxBet {
			panic("maximum bet is 100 GNOT per game")
		}
	} else if b.Amount+amount > maxBet {
		panic("maximum bet is 100 GNOT per game")
	}

	// All checks passed: write state.
	if !games.Has(key) {
		games.Set(key, g)
		open.Set(key, true)
		totalGames++
	}
	if b == nil {
		b = &Position{Addr: caller, Up: up}
		g.bets.Set(caller.String(), b)
		g.Bettors++
	}
	b.Amount += amount
	if up {
		g.UpPot += amount
	} else {
		g.DownPot += amount
	}
	p := player(caller)
	p.Bets++
	p.Wagered += amount
	totalBets++
	totalVolume += amount
	chain.Emit("Bet", "pair", pair, "round", strconv.FormatInt(round, 10), "up", strconv.FormatBool(up),
		"amount", strconv.FormatInt(amount, 10), "bettor", caller.String())
	return round
}

// Settle closes a game once Tapster has an answer at least settleAfter
// rounds newer than the game's. The caller earns 0.5% of the pot (max
// 1 GNOT) when there are winners to pay. Anyone can call it.
func Settle(cur realm, pair string, round int64) string {
	assertCurrent(cur)
	g := mustGame(pair, round)
	if g.Outcome != Open {
		panic("game already settled")
	}
	price, _, _, latest, ok := tapster.Latest(pair)
	if !ok || latest < g.Round+settleAfter {
		panic(ufmt.Sprintf("too early: this game settles once Tapster reaches round %d (now %d)", g.Round+settleAfter, latest))
	}
	g.EndRound = latest
	g.EndPrice = price
	g.SettledAt = now()
	g.Settler = cur.Previous().Address()
	open.Remove(gameKey(pair, round))
	totalSettled++
	settledLog = append(settledLog, gameKey(pair, round))
	if len(settledLog) > 100 {
		settledLog = settledLog[len(settledLog)-100:]
	}

	switch {
	case latest > g.Round+voidAfter:
		g.Outcome = Unsettled
	case g.UpPot == 0 || g.DownPot == 0:
		g.Outcome = OneSided
	case price == g.StartPrice:
		g.Outcome = Tie
	case price > g.StartPrice:
		g.Outcome = Up
	default:
		g.Outcome = Down
	}

	pot := g.UpPot + g.DownPot
	g.Payable = pot
	if g.Outcome == Up || g.Outcome == Down {
		tip := tapmath.ApplyBps(pot, tipBps)
		if tip > maxTip {
			tip = maxTip
		}
		g.Tip = tip
		g.Payable = pot - tip
		send(cur, g.Settler, tip)
	}
	chain.Emit("Settle", "pair", pair, "round", strconv.FormatInt(round, 10), "outcome", g.Outcome,
		"endPrice", strconv.FormatInt(price, 10))
	return g.Outcome
}

// Claim pays the caller's winnings, or refund, from a settled game.
func Claim(cur realm, pair string, round int64) int64 {
	assertCurrent(cur)
	g := mustGame(pair, round)
	if g.Outcome == Open {
		panic("game not settled yet")
	}
	caller := cur.Previous().Address()
	v := g.bets.Get(caller.String())
	if v == nil {
		panic("you have no bet in this game")
	}
	b := v.(*Position)
	if b.Claimed {
		panic("already claimed")
	}
	payout := payoutFor(g, b)
	if payout == 0 {
		panic("this bet lost")
	}
	b.Claimed = true
	b.Payout = payout
	p := player(caller)
	p.Won += payout
	if g.Outcome == Up || g.Outcome == Down {
		p.Wins++
	}
	send(cur, caller, payout)
	chain.Emit("Claim", "pair", pair, "round", strconv.FormatInt(round, 10), "amount", strconv.FormatInt(payout, 10))
	return payout
}

func payoutFor(g *Game, b *Position) int64 {
	switch g.Outcome {
	case Tie, OneSided, Unsettled:
		return b.Amount
	case Up:
		if !b.Up {
			return 0
		}
		return mulDiv(b.Amount, g.Payable, g.UpPot)
	case Down:
		if b.Up {
			return 0
		}
		return mulDiv(b.Amount, g.Payable, g.DownPot)
	}
	return 0
}

func send(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), to, chain.Coins{{ugnot, amount}})
}

// ----------------------------------------------------------------------
// Reads

// Odds returns the current pots of the open game for pair and its round,
// or ok=false when there is none.
func Odds(pair string) (round int64, upPot int64, downPot int64, ok bool) {
	_, _, _, r, has := tapster.Latest(pair)
	if !has {
		return 0, 0, 0, false
	}
	v := games.Get(gameKey(pair, r))
	if v == nil {
		return r, 0, 0, true
	}
	g := v.(*Game)
	return r, g.UpPot, g.DownPot, true
}

// Owed returns what addr can claim from a settled game.
func Owed(pair string, round int64, addr address) int64 {
	v := games.Get(gameKey(pair, round))
	if v == nil {
		return 0
	}
	g := v.(*Game)
	if g.Outcome == Open {
		return 0
	}
	bv := g.bets.Get(addr.String())
	if bv == nil {
		return 0
	}
	b := bv.(*Position)
	if b.Claimed {
		return 0
	}
	return payoutFor(g, b)
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func gnot(u int64) string { return tapmath.FormatRounded(u, 6, 3) + " GNOT" }

package lastcall

import (
	"strconv"
	"strings"

	"gno.land/p/moul/txlink/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/p/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapmath/v0"
	"gno.land/r/g1wdkzlexhwjvltvzkfmexyrm6jf5syzrrg0ymzy/tapster/v0"
)

// Render pages:
//
//	(empty)              open games, games ready to settle, recent results, leaderboard
//	player/<address>     a player's bets and what they can claim
//	json                 open and recent games as JSON
func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case path == "":
		return renderHome()
	case parts[0] == "player" && len(parts) == 2:
		return renderPlayer(address(parts[1]))
	case parts[0] == "json":
		return renderJSON()
	}
	return "# 404\n\n[Back](" + realmPath() + ")"
}

func realmPath() string {
	l := txlink.Call("Bet")
	if i := strings.Index(l, "$"); i >= 0 {
		return l[:i]
	}
	return l
}

func price(p int64, dec int) string {
	keep := 2
	if p < tapmath.Pow10(dec) {
		keep = dec
	}
	return "$" + tapmath.FormatRounded(p, dec, keep)
}

// multiplier shows what 1 GNOT on a side would pay if that side wins now.
func multiplier(side, other int64) string {
	if side == 0 {
		if other == 0 {
			return "—"
		}
		return "first bet takes the pot"
	}
	if other == 0 {
		return "no takers yet"
	}
	total := side + other
	payable := total - tapmath.ApplyBps(total, tipBps)
	// x100 for two decimals
	m := mulDiv(100, payable, side)
	return ufmt.Sprintf("%d.%02dx", m/100, m%100)
}

func ago(t int64) string {
	d := now() - t
	switch {
	case d < 120:
		return ufmt.Sprintf("%ds ago", d)
	case d < 7200:
		return ufmt.Sprintf("%dm ago", d/60)
	}
	return ufmt.Sprintf("%dh ago", d/3600)
}

func betLink(pair string, up bool, amount int64) string {
	return txlink.NewLink("Bet").AddArgs("pair", pair, "up", strconv.FormatBool(up)).SetSend(strconv.FormatInt(amount, 10) + "ugnot").URL()
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 🔔 Last Call\n\n")
	b.WriteString("**Will the price be higher or lower in about 15 minutes?** Bet GNOT on UP or DOWN. ")
	b.WriteString("Games are priced and settled by [Tapster](/" + strings.TrimPrefix(strings.Replace(realmPath(), "/lastcall/v0", "/tapster/v0", 1), "/") + ") price feeds. ")
	b.WriteString("Winners split the pot. No house edge; the settler earns 0.5%.\n\n")
	b.WriteString(ufmt.Sprintf("%d games · %d bets · %s wagered\n\n", totalGames, totalBets, gnot(totalVolume)))

	b.WriteString("## Open games\n\n| Feed | Opening price | Round | UP pot | DOWN pot | Bet |\n|---|---|---|---|---|---|\n")
	for _, pair := range strings.Split(tapster.Pairs(), ",") {
		p, dec, at, round, ok := tapster.Latest(pair)
		if !ok {
			b.WriteString("| " + pair + " | waiting for Tapster | | | | |\n")
			continue
		}
		if now()-at > maxPriceAge {
			b.WriteString("| " + pair + " | " + price(p, dec) + " (stale) | " + strconv.FormatInt(round, 10) + " | | | paused |\n")
			continue
		}
		var up, down int64
		if v := games.Get(gameKey(pair, round)); v != nil {
			g := v.(*Game)
			up, down = g.UpPot, g.DownPot
		}
		b.WriteString(ufmt.Sprintf("| **%s** | %s | %d | %s (%s) | %s (%s) | [⬆ UP 1 GNOT](%s) · [⬇ DOWN 1 GNOT](%s) |\n",
			pair, price(p, dec), round, gnot(up), multiplier(up, down), gnot(down), multiplier(down, up),
			betLink(pair, true, 1000000), betLink(pair, false, 1000000)))
	}
	b.WriteString("\nA game takes bets while its opening price is Tapster's latest answer, then settles on an answer at least 3 rounds later.\n\n")

	// Ready to settle
	var ready []string
	open.Iterate("", "", func(k string, _ any) bool {
		g := games.Get(k).(*Game)
		_, _, _, latest, ok := tapster.Latest(g.Pair)
		if ok && latest >= g.Round+settleAfter {
			ready = append(ready, ufmt.Sprintf("| %s | %d | %s | %d | [Settle and earn the tip](%s) |",
				g.Pair, g.Round, gnot(g.UpPot+g.DownPot), g.Bettors,
				txlink.NewLink("Settle").AddArgs("pair", g.Pair, "round", strconv.FormatInt(g.Round, 10)).URL()))
		}
		return len(ready) >= 20
	})
	if len(ready) > 0 {
		b.WriteString("## Ready to settle\n\n| Feed | Round | Pot | Bettors | |\n|---|---|---|---|---|\n")
		b.WriteString(strings.Join(ready, "\n") + "\n\n")
	}

	// Recent results
	b.WriteString("## Recent results\n\n| Feed | Round | Open → Close | Result | Pot |\n|---|---|---|---|---|\n")
	n := 0
	for i := len(settledLog) - 1; i >= 0 && n < 15; i-- {
		g := games.Get(settledLog[i]).(*Game)
		b.WriteString(ufmt.Sprintf("| %s | %d | %s → %s | %s | %s |\n", g.Pair, g.Round,
			price(g.StartPrice, g.Decimals), price(g.EndPrice, g.Decimals), badge(g.Outcome), gnot(g.UpPot+g.DownPot)))
		n++
	}
	if n == 0 {
		b.WriteString("| No settled games yet | | | | |\n")
	}

	// Leaderboard by profit
	b.WriteString("\n## Leaderboard\n\n| # | Player | Bets | Wins | Wagered | Profit |\n|---|---|---|---|---|---|\n")
	var list []*Player
	players.Iterate("", "", func(_ string, v any) bool {
		list = append(list, v.(*Player))
		return false
	})
	for i := 1; i < len(list); i++ {
		p := list[i]
		j := i - 1
		for j >= 0 && list[j].Won-list[j].Wagered < p.Won-p.Wagered {
			list[j+1] = list[j]
			j--
		}
		list[j+1] = p
	}
	for i, p := range list {
		if i >= 10 {
			break
		}
		profit := p.Won - p.Wagered
		sign := "+"
		if profit < 0 {
			sign = "-"
			profit = -profit
		}
		b.WriteString(ufmt.Sprintf("| %d | [%s](%s:player/%s) | %d | %d | %s | %s%s |\n",
			i+1, shortAddr(p.Addr), realmPath(), p.Addr.String(), p.Bets, p.Wins, gnot(p.Wagered), sign, gnot(profit)))
	}
	if len(list) == 0 {
		b.WriteString("| | No players yet | | | | |\n")
	}
	b.WriteString("\nSee your bets and claims at `" + realmPath() + ":player/<your address>`.\n")
	return b.String()
}

func badge(o string) string {
	switch o {
	case Up:
		return "⬆ UP won"
	case Down:
		return "⬇ DOWN won"
	case Tie:
		return "= tie, refunded"
	case OneSided:
		return "one-sided, refunded"
	case Unsettled:
		return "expired, refunded"
	}
	return o
}

func renderPlayer(a address) string {
	var b strings.Builder
	b.WriteString("# Player " + shortAddr(a) + "\n\n[All games](" + realmPath() + ")\n\n")
	pv := players.Get(a.String())
	if pv == nil {
		b.WriteString("No bets yet.\n")
		return b.String()
	}
	p := pv.(*Player)
	b.WriteString(ufmt.Sprintf("%d bets · %d wins · %s wagered · %s paid out\n\n", p.Bets, p.Wins, gnot(p.Wagered), gnot(p.Won)))
	b.WriteString("| Feed | Round | Side | Stake | Result | |\n|---|---|---|---|---|---|\n")
	n := 0
	games.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		bv := g.bets.Get(a.String())
		if bv == nil {
			return false
		}
		bt := bv.(*Position)
		side := "⬇ DOWN"
		if bt.Up {
			side = "⬆ UP"
		}
		action := ""
		switch {
		case g.Outcome == Open:
			action = "waiting"
		case bt.Claimed:
			action = "claimed " + gnot(bt.Payout)
		default:
			if owed := payoutFor(g, bt); owed > 0 {
				action = "[Claim " + gnot(owed) + "](" + txlink.NewLink("Claim").AddArgs("pair", g.Pair, "round", strconv.FormatInt(g.Round, 10)).URL() + ")"
			} else {
				action = "lost"
			}
		}
		res := badge(g.Outcome)
		if g.Outcome == Open {
			res = "open"
		}
		b.WriteString(ufmt.Sprintf("| %s | %d | %s | %s | %s | %s |\n", g.Pair, g.Round, side, gnot(bt.Amount), res, action))
		n++
		return n >= 50
	})
	return b.String()
}

func renderJSON() string {
	var items []string
	n := 0
	games.ReverseIterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		var bets []string
		g.bets.Iterate("", "", func(_ string, bv any) bool {
			bt := bv.(*Position)
			bets = append(bets, ufmt.Sprintf("{\"addr\":\"%s\",\"up\":%t,\"amount\":%d,\"claimed\":%t,\"owed\":%d}",
				bt.Addr.String(), bt.Up, bt.Amount, bt.Claimed, func() int64 {
					if g.Outcome == Open || bt.Claimed {
						return 0
					}
					return payoutFor(g, bt)
				}()))
			return false
		})
		items = append(items, ufmt.Sprintf("{\"pair\":\"%s\",\"round\":%d,\"startPrice\":%d,\"decimals\":%d,\"openedAt\":%d,\"upPot\":%d,\"downPot\":%d,\"outcome\":\"%s\",\"endRound\":%d,\"endPrice\":%d,\"settleAt\":%d,\"bets\":[%s]}",
			g.Pair, g.Round, g.StartPrice, g.Decimals, g.OpenedAt, g.UpPot, g.DownPot, g.Outcome, g.EndRound, g.EndPrice, g.Round+settleAfter, strings.Join(bets, ",")))
		n++
		return n >= 60
	})
	return ufmt.Sprintf("{\"games\":%d,\"bets\":%d,\"volume\":%d,\"settleAfter\":%d,\"minBet\":%d,\"maxBet\":%d,\"list\":[%s]}",
		totalGames, totalBets, totalVolume, settleAfter, minBet, maxBet, strings.Join(items, ","))
}
